// Promise.try, adapted from https://github.com/sindresorhus/p-try
export const promiseTry = async <TValue, TArgs extends unknown[]>(
  fn: (...args: TArgs) => PromiseLike<TValue> | TValue,
  ...args: TArgs
): Promise<TValue> => {
  return new Promise((resolve) => {
    resolve(fn(...args));
  });
};

export const isAnyTrue = (...args: boolean[]): boolean =>
  Math.max(...args.map((arg) => (arg ? 1 : 0))) > 0;

export const safelyParseJSON = (json: string): Record<string, any> | null => {
  try {
    return JSON.parse(json);
  } catch {
    return null;
  }
};

/**
 * use when you need to render unsafe string as HTML attribute, but MAKE SURE
 * the attribute is double-quoted when constructing the HTML string
 */
export const escapeDoubleQuotes = (str: string) => {
  return str.replace(/"/g, "&quot;");
};

export const castArray = <T>(value: T | T[]): T[] =>
  Array.isArray(value) ? value : [value];

/** hack for Array.isArray type guard not working with readonly value[] */
export const isReadonlyArray = (value?: any): value is readonly any[] => {
  return Array.isArray(value);
};

export const sizeOf = (
  value:
    | readonly unknown[]
    | Readonly<Map<string, unknown>>
    | Readonly<Record<string, unknown>>
    | ReadonlySet<unknown>,
): number => {
  return isReadonlyArray(value)
    ? value.length
    : value instanceof Map || value instanceof Set
    ? value.size
    : Object.keys(value).length;
};

export const reduceToCommonValue = <T, R = T>(
  collection: readonly T[] | ReadonlySet<T>,
  getValue?: (item: T) => R,
): R | null => {
  if (sizeOf(collection) === 0) {
    return null;
  }

  const valueExtractor = getValue || ((item: T) => item as unknown as R);

  let commonValue: R | null = null;

  for (const item of collection) {
    const value = valueExtractor(item);
    if ((commonValue === null || commonValue === value) && value != null) {
      commonValue = value;
    } else {
      return null;
    }
  }

  return commonValue;
};

type FEATURE_FLAGS = {
  COMPLEX_BINDINGS: boolean;
};

const FEATURE_FLAGS_STORAGE_KEY = "excalidraw-feature-flags";
const DEFAULT_FEATURE_FLAGS: FEATURE_FLAGS = {
  COMPLEX_BINDINGS: false,
};
let featureFlags: FEATURE_FLAGS | null = null;

export const getFeatureFlag = <F extends keyof FEATURE_FLAGS>(
  flag: F,
): FEATURE_FLAGS[F] => {
  if (!featureFlags) {
    try {
      const serializedFlags = localStorage.getItem(FEATURE_FLAGS_STORAGE_KEY);
      if (serializedFlags) {
        const flags = JSON.parse(serializedFlags);
        featureFlags = flags ?? DEFAULT_FEATURE_FLAGS;
      }
    } catch {}
  }

  return (featureFlags || DEFAULT_FEATURE_FLAGS)[flag];
};

export const setFeatureFlag = <F extends keyof FEATURE_FLAGS>(
  flag: F,
  value: FEATURE_FLAGS[F],
) => {
  try {
    featureFlags = {
      ...(featureFlags || DEFAULT_FEATURE_FLAGS),
      [flag]: value,
    };
    localStorage.setItem(
      FEATURE_FLAGS_STORAGE_KEY,
      JSON.stringify(featureFlags),
    );
  } catch (e) {
    console.error("unable to set feature flag", e);
  }
};

export const oneOf = <N extends string | number | symbol | null, H extends N>(
  needle: N,
  haystack: readonly H[],
): needle is H => {
  return haystack.includes(needle as any);
};

export type VersionedSnapshot<T> = Readonly<{
  version: number;
  value: T;
}>;

export class VersionedSnapshotStore<T> {
  private version = 0;
  private value: T;
  private readonly waiters = new Set<
    (snapshot: VersionedSnapshot<T>) => void
  >();
  private readonly subscribers = new Set<
    (snapshot: VersionedSnapshot<T>) => void
  >();

  constructor(
    initialValue: T,
    private readonly isEqual: (prev: T, next: T) => boolean = Object.is,
  ) {
    this.value = initialValue;
  }

  public getSnapshot(): VersionedSnapshot<T> {
    return { version: this.version, value: this.value };
  }

  public set(nextValue: T): boolean {
    if (this.isEqual(this.value, nextValue)) {
      return false;
    }

    this.value = nextValue;
    this.version += 1;

    const snapshot = this.getSnapshot();

    for (const subscriber of this.subscribers) {
      subscriber(snapshot);
    }
    for (const waiter of this.waiters) {
      waiter(snapshot);
    }
    this.waiters.clear();

    return true;
  }

  public update(updater: (prev: T) => T): boolean {
    return this.set(updater(this.value));
  }

  public subscribe(
    subscriber: (snapshot: VersionedSnapshot<T>) => void,
  ): () => void {
    this.subscribers.add(subscriber);
    return () => {
      this.subscribers.delete(subscriber);
    };
  }

  public pull(sinceVersion = -1): Promise<VersionedSnapshot<T>> {
    if (this.version !== sinceVersion) {
      return Promise.resolve(this.getSnapshot());
    }

    return new Promise((resolve) => {
      this.waiters.add(resolve);
    });
  }
}

import { BinaryHeap } from "../src/binary-heap";

describe("BinaryHeap", () => {
  const numberHeap = () => new BinaryHeap<number>((n) => n);

  const drain = (heap: BinaryHeap<number>) => {
    const out: number[] = [];
    while (heap.size() > 0) {
      out.push(heap.pop()!);
    }
    return out;
  };

  describe("empty heap", () => {
    it("has size 0", () => {
      expect(numberHeap().size()).toBe(0);
    });

    it("pop() returns null", () => {
      expect(numberHeap().pop()).toBe(null);
    });

    it("remove() is a no-op and does not throw", () => {
      const heap = numberHeap();
      expect(() => heap.remove(1)).not.toThrow();
      expect(heap.size()).toBe(0);
    });
  });

  describe("push / pop", () => {
    it("tracks size as items are added and removed", () => {
      const heap = numberHeap();
      [3, 1, 2].forEach((n) => heap.push(n));
      expect(heap.size()).toBe(3);

      heap.pop();
      expect(heap.size()).toBe(2);
    });

    it("pops a single pushed element back out", () => {
      const heap = numberHeap();
      heap.push(42);
      expect(heap.pop()).toBe(42);
      expect(heap.pop()).toBe(null);
    });

    it("always pops the smallest score first", () => {
      const heap = numberHeap();
      [5, 3, 8, 1, 9, 2, 7].forEach((n) => heap.push(n));
      expect(drain(heap)).toEqual([1, 2, 3, 5, 7, 8, 9]);
    });

    it("handles duplicate scores", () => {
      const heap = numberHeap();
      [4, 1, 4, 1, 2].forEach((n) => heap.push(n));
      expect(drain(heap)).toEqual([1, 1, 2, 4, 4]);
    });

    it("maintains the heap invariant for a large adversarial (reverse-sorted) input", () => {
      const heap = numberHeap();
      // pushing in descending order forces a sift-up on every insert
      const input = Array.from({ length: 1000 }, (_, i) => 1000 - i);
      input.forEach((n) => heap.push(n));
      expect(drain(heap)).toEqual([...input].sort((a, b) => a - b));
    });
  });

  describe("remove", () => {
    it("removes an interior element and keeps the rest ordered", () => {
      const heap = numberHeap();
      [5, 3, 8, 1, 9].forEach((n) => heap.push(n));

      heap.remove(8);

      expect(heap.size()).toBe(4);
      expect(drain(heap)).toEqual([1, 3, 5, 9]);
    });

    it("can remove the current minimum", () => {
      const heap = numberHeap();
      [5, 3, 8, 1, 9].forEach((n) => heap.push(n));

      heap.remove(1);

      expect(heap.size()).toBe(4);
      expect(heap.pop()).toBe(3);
    });
  });

  describe("rescoreElement", () => {
    type Node = { id: string; f: number };

    it("re-sorts a node after its score is lowered", () => {
      const heap = new BinaryHeap<Node>((node) => node.f);

      const a = { id: "a", f: 10 };
      const b = { id: "b", f: 20 };
      const c = { id: "c", f: 30 };
      [a, b, c].forEach((node) => heap.push(node));

      c.f = 5;
      heap.rescoreElement(c);

      expect(heap.pop()).toBe(c);
      expect(heap.pop()).toBe(a);
      expect(heap.pop()).toBe(b);
    });
  });
});

