import { arrayToMap, ROUNDNESS } from "@excalidraw/common";
import {
  distanceToLineSegment,
  lineSegment,
  pointFrom,
  polygonIncludesPoint,
} from "@excalidraw/math";

import { API } from "@excalidraw/excalidraw/tests/helpers/api";

import type { GlobalPoint, LocalPoint, Polygon } from "@excalidraw/math";

import { computeBucketFillPolygon, isRestylableFill } from "../src/bucketFill";
import { getFreedrawStrokeCenterPoints } from "../src/shape";

import type { ElementsMap, NonDeletedExcalidrawElement } from "../src/types";

const setup = (elements: NonDeletedExcalidrawElement[]) => ({
  elements,
  elementsMap: arrayToMap(elements) as ElementsMap,
});

const polygonArea = (pts: GlobalPoint[]): number => {
  let area = 0;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    area += (pts[j][0] + pts[i][0]) * (pts[j][1] - pts[i][1]);
  }
  return Math.abs(area / 2);
};

/**
 * Turn a computed fill polygon into the line element the app would create
 * for it, so a follow-up `computeBucketFillPolygon` sees the prior fill.
 */
const materializeFill = (scenePoints: readonly GlobalPoint[]) => {
  const minX = Math.min(...scenePoints.map((p) => p[0]));
  const minY = Math.min(...scenePoints.map((p) => p[1]));
  const maxX = Math.max(...scenePoints.map((p) => p[0]));
  const maxY = Math.max(...scenePoints.map((p) => p[1]));
  return API.createElement({
    type: "line",
    x: minX,
    y: minY,
    width: maxX - minX,
    height: maxY - minY,
    points: scenePoints.map((p) =>
      pointFrom<LocalPoint>(p[0] - minX, p[1] - minY),
    ),
    polygon: true,
    backgroundColor: "#ffc9c9",
    fillStyle: "solid",
    strokeColor: "transparent",
  });
};

const isClosed = (pts: GlobalPoint[]): boolean =>
  pts.length > 3 &&
  pts[0][0] === pts[pts.length - 1][0] &&
  pts[0][1] === pts[pts.length - 1][1];

describe("computeBucketFillPolygon", () => {
  it("fills a simple rectangle and returns a closed polygon", () => {
    const rect = API.createElement({
      type: "rectangle",
      x: 0,
      y: 0,
      width: 100,
      height: 100,
      roundness: null,
    });
    const { elements, elementsMap } = setup([rect]);

    const result = computeBucketFillPolygon({
      point: pointFrom<GlobalPoint>(50, 50),
      elements,
      elementsMap,
    });

    expect(result.ok).toBe(true);
    if (!result.ok) {
      return;
