describe("Crop an image", () => {
  it("Cropping changes the dimension", async () => {
    const image = h.elements[0] as ExcalidrawImageElement;

    const initialWidth = image.width;
    const initialHeight = image.height;

    const { naturalWidth, naturalHeight } =
      generateRandomNaturalWidthAndHeight(image);

    UI.crop(image, "w", naturalWidth, naturalHeight, [initialWidth / 2, 0]);

    expect(image.width).toBeLessThan(initialWidth);
    UI.crop(image, "n", naturalWidth, naturalHeight, [0, initialHeight / 2]);
    expect(image.height).toBeLessThan(initialHeight);
  });

  it("In the crop editor, dragging a handle crops the image, and dragging the image moves it within its crop (along one axis with shift)", () => {
    const image = API.createElement({
      type: "image",
      width: 200,
      height: 100,
      fileId: "file",
    });
    API.setElements([image]);
    // the file loaded, at twice the element's size
    const htmlImage = new Image();
    Object.defineProperties(htmlImage, {
      naturalWidth: { value: 400 },
      naturalHeight: { value: 200 },
    });
    h.app.imageCache.set(image.fileId!, {
      image: htmlImage,
      mimeType: "image/png",
    });
    API.setSelectedElements([image]);
    Keyboard.keyDown(KEYS.ENTER);
    expect(h.state.croppingElementId).toBe(image.id);

    UI.resize(image, "nw", [50, 25]);

    expect(API.getElement(image)).toMatchObject({ x: 50, y: 25, width: 150 });
    expect(API.getElement(image).crop).toMatchObject({ x: 100, y: 50 });

    // 20px to the right = 40px of the file, at twice the element's size
    mouse.downAt(100, 50);
    mouse.move(20, 0);
    mouse.upAt();

    expect(API.getElement(image)).toMatchObject({ x: 50, y: 25, width: 150 });
    expect(API.getElement(image).crop).toMatchObject({ x: 60, y: 50 });

    Keyboard.withModifierKeys({ shift: true }, () => {
      mouse.downAt(100, 50);
      mouse.move(10, 4);
      mouse.upAt();
    });

    expect(API.getElement(image).crop).toMatchObject({ x: 40, y: 50 });

    // dragged past the file's edge, it moves back as soon as dragged back
    mouse.downAt(100, 50);
    mouse.move(40, 0);
    expect(API.getElement(image).crop).toMatchObject({ x: 0 });
    mouse.move(-10, 0);
    mouse.upAt();

    expect(API.getElement(image).crop).toMatchObject({ x: 20, y: 50 });
  });

  it("In the crop editor, alt-dragging a handle crops the image from its center", () => {
    const image = API.createElement({
      type: "image",
      width: 200,
      height: 100,
      fileId: "file",
    });
    API.setElements([image]);
    // the file loaded, at twice the element's size
    const htmlImage = new Image();
    Object.defineProperties(htmlImage, {
      naturalWidth: { value: 400 },
      naturalHeight: { value: 200 },
    });
    h.app.imageCache.set(image.fileId!, {
      image: htmlImage,
      mimeType: "image/png",
    });
    API.setSelectedElements([image]);
    Keyboard.keyDown(KEYS.ENTER);

    // as resizing, pressing alt mid-drag crops about the center the drag
    // started with, and releasing it, from the opposite side again
    mouse.downAt(200, 50);
    mouse.moveTo(170, 50);
    expect(API.getElement(image)).toMatchObject({ x: 0, width: 170 });
    Keyboard.withModifierKeys({ alt: true }, () => {
      Keyboard.keyDown(KEYS.ALT);
    });
    expect(API.getElement(image)).toMatchObject({ x: 30, width: 140 });
    Keyboard.keyUp(KEYS.ALT);
    expect(API.getElement(image)).toMatchObject({ x: 0, width: 170 });
    mouse.moveTo(200, 50);
    mouse.upAt();

    UI.resize(image, "e", [-30, 0], { alt: true });

    expect(API.getElement(image)).toMatchObject({ x: 30, width: 140 });
    // 30px off each side = 60px of the file, at twice the element's size
    expect(API.getElement(image).crop).toMatchObject({ x: 60, width: 280 });

    // keeping the aspect ratio too
    UI.resize(image, "e", [-35, 0], { alt: true, shift: true });

    expect(API.getElement(image)).toMatchObject({
      x: 65,
      y: 25,
      width: 70,
      height: 50,
    });
  });

  it("In the crop editor, double-clicking a handle uncrops its side(s), mirrored with alt", () => {
    // the middle of an image twice the element's size, at (0, 0)
    const image = API.createElement({
      type: "image",
      x: 50,
      y: 25,
      width: 100,
      height: 50,
      fileId: "file",
    });
    API.setElements([image]);
    API.updateElement(image, {
      crop: {
        x: 100,
        y: 50,
        width: 200,
        height: 100,
        naturalWidth: 400,
        naturalHeight: 200,
      },
    });
    // bound near the image's south-east corner
    const arrow = UI.createElement("arrow", {
      x: 140,
      y: 300,
      width: 0,
      height: -230,
    });
    API.setSelectedElements([image]);
    Keyboard.keyDown(KEYS.ENTER);

    // the north-east handle
    mouse.doubleClickAt(150, 25);

    expect(API.getElement(image)).toMatchObject({
      x: 50,
      y: 0,
      width: 150,
      height: 75,
    });
    expect(API.getElement(image).crop).toMatchObject({ y: 0, width: 300 });
    // the arrow following the image
    const { x, points } = API.getElement(arrow);
    expect(x + points[1][0]).toBeCloseTo(185);

    Keyboard.undo();

    expect(API.getElement(image)).toMatchObject({ y: 25, width: 100 });

    // the west handle, and so the east one
    Keyboard.withModifierKeys({ alt: true }, () => {
      mouse.doubleClickAt(50, 50);
    });

    expect(API.getElement(image)).toMatchObject({
      x: 0,
      y: 25,
      width: 200,
      height: 50,
    });
    expect(API.getElement(image).crop).toMatchObject({ x: 0, width: 400 });
  });

  it("Cropping has minimal sizes", async () => {
    const image = h.elements[0] as ExcalidrawImageElement;
    const initialWidth = image.width;
    const initialHeight = image.height;

    const { naturalWidth, naturalHeight } =
      generateRandomNaturalWidthAndHeight(image);

    UI.crop(image, "w", naturalWidth, naturalHeight, [initialWidth, 0]);
    expect(image.width).toBeLessThan(initialWidth);
    expect(image.width).toBeGreaterThan(0);
    UI.crop(image, "w", naturalWidth, naturalHeight, [-initialWidth, 0]);
    UI.crop(image, "n", naturalWidth, naturalHeight, [0, initialHeight]);
    expect(image.height).toBeLessThan(initialHeight);
    expect(image.height).toBeGreaterThan(0);
  });

  it("Preserve aspect ratio", async () => {
    let image = h.elements[0] as ExcalidrawImageElement;
    const initialWidth = image.width;
    const initialHeight = image.height;

    const { naturalWidth, naturalHeight } =
      generateRandomNaturalWidthAndHeight(image);

    UI.crop(image, "w", naturalWidth, naturalHeight, [initialWidth / 3, 0]);

    let resizedWidth = image.width;
    let resizedHeight = image.height;

    // max height, cropping should not change anything
    UI.crop(
      image,
      "w",
      naturalWidth,
      naturalHeight,
      [-initialWidth / 3, 0],
      true,
    );
    expect(image.width).toBeCloseTo(resizedWidth, 10);
    expect(image.height).toBeCloseTo(resizedHeight, 10);

    // re-crop to initial state
    UI.crop(image, "w", naturalWidth, naturalHeight, [-initialWidth / 3, 0]);
    // change crop height and width
    UI.crop(image, "s", naturalWidth, naturalHeight, [0, -initialHeight / 2]);
    UI.crop(image, "e", naturalWidth, naturalHeight, [-initialWidth / 3, 0]);

    resizedWidth = image.width;
    resizedHeight = image.height;

    // test corner handle aspect ratio preserving
    UI.crop(image, "se", naturalWidth, naturalHeight, [initialWidth, 0], true);
    expect(image.width / image.height).toBe(resizedWidth / resizedHeight);
    expect(image.width).toBeLessThanOrEqual(initialWidth + 0.0001);
    expect(image.height).toBeLessThanOrEqual(initialHeight + 0.0001);

    // reset
    image = API.createElement({ type: "image", width: 200, height: 100 });
    API.setElements([image]);
    API.setAppState({
      selectedElementIds: {
        [image.id]: true,
      },
    });

    // 50 x 50 square
    UI.crop(image, "nw", naturalWidth, naturalHeight, [150, 50]);
    UI.crop(image, "n", naturalWidth, naturalHeight, [0, -100], true);
    expect(image.width).toBeCloseTo(image.height);
    // image is at the corner, not space to its right to expand, should not be able to resize
    expect(image.height).toBeCloseTo(50);

    UI.crop(image, "nw", naturalWidth, naturalHeight, [-150, -100], true);
    expect(image.width).toBeCloseTo(image.height);
    // max height should be reached
    expect(image.height).toBeCloseTo(initialHeight);
    expect(image.width).toBeCloseTo(initialHeight);
  });
});

describe("Cropping and other features", async () => {
  it("Cropping works independently of duplication", async () => {
    const image = h.elements[0] as ExcalidrawImageElement;
    const initialWidth = image.width;
    const initialHeight = image.height;

    const { naturalWidth, naturalHeight } =
      generateRandomNaturalWidthAndHeight(image);

    UI.crop(image, "nw", naturalWidth, naturalHeight, [
      initialWidth / 2,
      initialHeight / 2,
    ]);
    Keyboard.keyDown(KEYS.ESCAPE);
    const duplicatedImage = duplicateElement(null, new Map(), image);
    act(() => {
      h.app.scene.insertElement(duplicatedImage);
    });

    expect(duplicatedImage.width).toBe(image.width);
    expect(duplicatedImage.height).toBe(image.height);

    UI.crop(duplicatedImage, "nw", naturalWidth, naturalHeight, [
      -initialWidth / 2,
      -initialHeight / 2,
    ]);
    expect(duplicatedImage.width).toBe(initialWidth);
    expect(duplicatedImage.height).toBe(initialHeight);
    const resizedWidth = image.width;
    const resizedHeight = image.height;

    expect(image.width).not.toBe(duplicatedImage.width);
    expect(image.height).not.toBe(duplicatedImage.height);
    UI.crop(duplicatedImage, "se", naturalWidth, naturalHeight, [
      -initialWidth / 1.5,
      -initialHeight / 1.5,
    ]);
    expect(duplicatedImage.width).not.toBe(initialWidth);
    expect(image.width).toBe(resizedWidth);
    expect(duplicatedImage.height).not.toBe(initialHeight);
    expect(image.height).toBe(resizedHeight);
  });

  it("Resizing should not affect crop", async () => {
    const image = h.elements[0] as ExcalidrawImageElement;
    const initialWidth = image.width;
    const initialHeight = image.height;

    const { naturalWidth, naturalHeight } =
      generateRandomNaturalWidthAndHeight(image);

    UI.crop(image, "nw", naturalWidth, naturalHeight, [
      initialWidth / 2,
      initialHeight / 2,
    ]);
    const cropBeforeResizingCloned = cloneJSON(image.crop) as ImageCrop;
    expect(image.crop).not.toBe(null);

    UI.crop(image, "e", naturalWidth, naturalHeight, [200, 0]);
    compareCrops(cropBeforeResizingCloned, image.crop!);
    const cropBeforeResizing = image.crop;

    UI.resize(image, "s", [0, -100]);
    expect(cropBeforeResizing).toBe(image.crop);
    compareCrops(cropBeforeResizingCloned, image.crop!);

    UI.resize(image, "ne", [-50, -50]);
    expect(cropBeforeResizing).toBe(image.crop);
    compareCrops(cropBeforeResizingCloned, image.crop!);
  });

  it("Flipping does not change crop", async () => {
    const image = h.elements[0] as ExcalidrawImageElement;
    const initialWidth = image.width;
    const initialHeight = image.height;

    const { naturalWidth, naturalHeight } =
      generateRandomNaturalWidthAndHeight(image);

    mouse.doubleClickOn(image);
    expect(h.state.croppingElementId).not.toBe(null);
    UI.crop(image, "nw", naturalWidth, naturalHeight, [
      initialWidth / 2,
      initialHeight / 2,
    ]);
    Keyboard.keyDown(KEYS.ESCAPE);
    const cropBeforeResizing = image.crop;
    const cropBeforeResizingCloned = cloneJSON(image.crop) as ImageCrop;

    API.executeAction(actionFlipHorizontal);
    expect(image.crop).toBe(cropBeforeResizing);
    compareCrops(cropBeforeResizingCloned, image.crop!);

    API.executeAction(actionFlipVertical);
    expect(image.crop).toBe(cropBeforeResizing);
    compareCrops(cropBeforeResizingCloned, image.crop!);
  });

  it("Exports should preserve crops", async () => {
    const image = h.elements[0] as NonDeleted<ExcalidrawImageElement>;
    const initialWidth = image.width;
    const initialHeight = image.height;

    const { naturalWidth, naturalHeight } =
      generateRandomNaturalWidthAndHeight(image);

    mouse.doubleClickOn(image);
    expect(h.state.croppingElementId).not.toBe(null);
    UI.crop(image, "nw", naturalWidth, naturalHeight, [
      initialWidth / 2,
      initialHeight / 4,
    ]);
    Keyboard.keyDown(KEYS.ESCAPE);
    const widthToHeightRatio = image.width / image.height;

    const canvas = await exportScene({
      type: "canvas",
      data: {
        elements: [image],
        // @ts-ignore
        appState: h.state,
        files: h.app.files,
      },
      config: {
        padding: 0,
      },
    });
    const exportedCanvasRatio = canvas.width / canvas.height;

    expect(widthToHeightRatio).toBeCloseTo(exportedCanvasRatio);

    const svg = await exportScene({
      type: "svg",
      data: {
        elements: [image],
        // @ts-ignore
        appState: h.state,
        files: h.app.files,
      },
      config: {
        padding: 0,
      },
    });
    const svgWidth = svg.getAttribute("width");
    const svgHeight = svg.getAttribute("height");

    expect(svgWidth).toBeDefined();
    expect(svgHeight).toBeDefined();

    const exportedSvgRatio = Number(svgWidth) / Number(svgHeight);
    expect(widthToHeightRatio).toBeCloseTo(exportedSvgRatio);
  });
});

import { API } from "@excalidraw/excalidraw/tests/helpers/api";
import { arrayToMap } from "@excalidraw/common";
import { pointFrom } from "@excalidraw/math";

import type { ObservedAppState } from "@excalidraw/excalidraw/types";
import type { LinearElementEditor } from "@excalidraw/element";
import type {
  ExcalidrawTextElement,
  FractionalIndex,
  SceneElementsMap,
} from "@excalidraw/element/types";

import { AppStateDelta, Delta, ElementsDelta } from "../src/delta";
import { mutateElement, newElementWith } from "../src/mutateElement";

describe("ElementsDelta", () => {
  describe("visible changes", () => {
    const apply = (before: SceneElementsMap, after: SceneElementsMap) =>
      ElementsDelta.calculate(before, after).applyTo(before, before, {
        excludedProperties: new Set(["version", "versionNonce"]),
      });

    const boundText = (
      type: "rectangle" | "stickynote" | "arrow",
      text = "",
    ) => {
      const container = API.createElement({
        type,
        id: "container",
        index: "a0" as FractionalIndex,
        width: 250,
        height: type === "arrow" ? 0 : 250,
        baseHeight: type === "stickynote" ? 250 : undefined,
        points:
          type === "arrow" ? [pointFrom(0, 0), pointFrom(250, 0)] : undefined,
        boundElements: [{ id: "label", type: "text" }],
      });
      const label: ExcalidrawTextElement = {
        ...API.createElement({
          type: "text",
          id: "label",
          index: "a1" as FractionalIndex,
          containerId: container.id,
          fontSize: 20,
          textAlign: "center",
          verticalAlign: "middle",
        }),
        // API.createElement substitutes "test" for an empty string.
        text,
        originalText: text,
      };
      const before = arrayToMap([container, label]) as SceneElementsMap;
      const after = arrayToMap([
        newElementWith(container, { boundElements: [] }),
        newElementWith(label, { isDeleted: true }),
      ]) as SceneElementsMap;
      return { container, label, before, after };
    };

    it.each(["rectangle", "stickynote"] as const)(
      "ignores empty-label deletion and restoration on a %s",
      (type) => {
        const { before, after, container, label } = boundText(type);
        const [deleted, deletionIsVisible] = apply(before, after);
        expect(deletionIsVisible).toBe(false);
        expect(deleted.get(label.id)?.isDeleted).toBe(true);
        expect(deleted.get(container.id)?.boundElements).toEqual([]);

        const [restored, restorationIsVisible] = apply(after, before);
        expect(restorationIsVisible).toBe(false);
        expect(restored.get(label.id)?.isDeleted).toBe(false);
        expect(restored.get(container.id)?.boundElements).toEqual([
          { id: label.id, type: "text" },
        ]);
      },
    );

    it("keeps deletion and restoration of nonempty labels visible", () => {
      const { before, after } = boundText("stickynote", "hello");
      expect(apply(before, after)[1]).toBe(true);
      expect(apply(after, before)[1]).toBe(true);
    });

    it.each(["excluded", "already applied"])(
      "ignores %s properties when deciding visibility",
      (mode) => {
        const element = API.createElement({
          type: "rectangle",
          index: "a0" as FractionalIndex,
        });
        const before = arrayToMap([element]) as SceneElementsMap;
        const after = arrayToMap([
          newElementWith(element, { strokeColor: "red" }),
        ]) as SceneElementsMap;
        const delta = ElementsDelta.calculate(before, after);
        const current = mode === "excluded" ? before : after;
        const [elements, isVisible] = delta.applyTo(current, current, {
          excludedProperties: new Set([
            "version",
            "versionNonce",
            ...(mode === "excluded" ? ["strokeColor" as const] : []),
          ]),
        });

        expect(elements.get(element.id)?.strokeColor).toBe(
          current.get(element.id)?.strokeColor,
        );
        expect(isVisible).toBe(false);
      },
    );

    it("keeps snapshot restoration visible for a metadata-only update", () => {
      const element = API.createElement({
        type: "rectangle",
        index: "a0" as FractionalIndex,
      });
      const before = arrayToMap([element]) as SceneElementsMap;
      const after = arrayToMap([
        newElementWith(element, { version: element.version + 1 }),
      ]) as SceneElementsMap;
      const delta = ElementsDelta.calculate(before, after);
      const [elements, isVisible] = delta.applyTo(
        new Map() as SceneElementsMap,
        before,
      );

      expect(elements.get(element.id)?.isDeleted).toBe(false);
      expect(isVisible).toBe(true);
    });

    it("keeps an arrow's empty-label gap visible", () => {
      const { before, after } = boundText("arrow");
      expect(apply(before, after)[1]).toBe(true);
      expect(apply(after, before)[1]).toBe(true);
    });

    it("detects a container resized by restoring an empty label", () => {
      const { container, label } = boundText("rectangle");
      const smallContainer = newElementWith(container, {
        width: 20,
        height: 10,
        boundElements: [],
      });
      const before = arrayToMap([
        smallContainer,
        newElementWith(label, { isDeleted: true }),
      ]) as SceneElementsMap;
      const after = arrayToMap([
        newElementWith(smallContainer, {
          boundElements: [{ id: label.id, type: "text" }],
        }),
        newElementWith(label, { isDeleted: false }),
      ]) as SceneElementsMap;

      const [elements, isVisible] = apply(before, after);
      expect(elements.get(container.id)?.height).toBeGreaterThan(10);
      expect(isVisible).toBe(true);
    });

    it("detects a bound label repositioned by a container's redraw", () => {
      const { container, label } = boundText("rectangle", "hello");
      const misplacedLabel = newElementWith(label, { x: -100, y: -100 });
      const before = arrayToMap([
        container,
        misplacedLabel,
      ]) as SceneElementsMap;
      const after = arrayToMap([
        newElementWith(container, { version: container.version + 1 }),
        misplacedLabel,
      ]) as SceneElementsMap;

      const [elements, isVisible] = apply(before, after);
      expect(elements.get(container.id)?.height).toBe(container.height);
      expect(elements.get(label.id)?.x).not.toBe(-100);
      expect(isVisible).toBe(true);
    });

    it("detects a bound arrow repositioned by a container's redraw", () => {
      const container = API.createElement({
        type: "rectangle",
        id: "container",
        index: "a0" as FractionalIndex,
        boundElements: [{ id: "arrow", type: "arrow" }],
      });
      const arrow = API.createElement({
        type: "arrow",
        id: "arrow",
        index: "a1" as FractionalIndex,
        x: 200,
        y: 50,
        points: [pointFrom(0, 0), pointFrom(100, 0)],
        startBinding: {
          elementId: container.id,
          mode: "orbit",
          fixedPoint: [1, 0.5],
        },
      });
      const before = arrayToMap([container, arrow]) as SceneElementsMap;
      const after = arrayToMap([
        newElementWith(container, { version: container.version + 1 }),
        arrow,
      ]) as SceneElementsMap;

      const [elements, isVisible] = apply(before, after);
      expect(elements.get(container.id)?.width).toBe(container.width);
      expect(elements.get(arrow.id)?.x).not.toBe(200);
      expect(isVisible).toBe(true);
    });

    it.each(["test", "development", "production"])(
      "guards against untracked layout mutations in %s mode",
      (mode) => {
        const element = API.createElement({
          type: "rectangle",
          id: "changed",
          index: "a0" as FractionalIndex,
        });
        const unrelated = API.createElement({
          type: "rectangle",
          id: "unrelated",
          index: "a1" as FractionalIndex,
        });
        const before = arrayToMap([element, unrelated]) as SceneElementsMap;
        const after = arrayToMap([
          newElementWith(element, { strokeColor: "red" }),
          unrelated,
        ]) as SceneElementsMap;
        // Simulate a future layout dependency missing from idsToCheck.
        // Mutate the shared instance so the guard must snapshot version values.
        const redraw = vi
          .spyOn(ElementsDelta, "redrawElements")
          .mockImplementationOnce((elements) => {
            mutateElement(elements.get(unrelated.id)!, elements, {
              x: unrelated.x + 1,
            });
            return elements;
          });
        const consoleError = vi
          .spyOn(console, "error")
          .mockImplementation(() => {});
        vi.stubEnv("MODE", mode);

        try {
          if (mode === "production") {
            expect(apply(before, after)[1]).toBe(true);
            expect(consoleError).not.toHaveBeenCalled();
          } else {
            expect(() => apply(before, after)).toThrow(
              'Redrawn element "unrelated" is missing from idsToCheck',
            );
          }
        } finally {
          redraw.mockRestore();
          consoleError.mockRestore();
          vi.unstubAllEnvs();
        }
      },
    );

    it("keeps an empty text element's arrow bindings visible", () => {
      const label: ExcalidrawTextElement = {
        ...API.createElement({
          type: "text",
          id: "label",
          index: "a0" as FractionalIndex,
          boundElements: [{ id: "arrow", type: "arrow" }],
        }),
        text: "",
        originalText: "",
      };
      const arrow = API.createElement({
        type: "arrow",
        id: "arrow",
        index: "a1" as FractionalIndex,
        startBinding: {
          elementId: label.id,
          mode: "orbit",
          fixedPoint: [1, 0.5],
        },
      });
      const before = arrayToMap([label, arrow]) as SceneElementsMap;
      const after = arrayToMap([
        newElementWith(label, { isDeleted: true, boundElements: [] }),
        newElementWith(arrow, { startBinding: null }),
      ]) as SceneElementsMap;
      expect(apply(before, after)[1]).toBe(true);
    });
  });

  describe("elements delta calculation", () => {
    it("should not throw when element gets removed but was already deleted", () => {
      const element = API.createElement({
        type: "rectangle",
        x: 100,
        y: 100,
        isDeleted: true,
      });

      const prevElements = new Map([[element.id, element]]);
      const nextElements = new Map();

      expect(() =>
        ElementsDelta.calculate(prevElements, nextElements),
      ).not.toThrow();
    });

    it("should not throw when adding element as already deleted", () => {
      const element = API.createElement({
        type: "rectangle",
        x: 100,
        y: 100,
        isDeleted: true,
      });

      const prevElements = new Map();
      const nextElements = new Map([[element.id, element]]);

      expect(() =>
        ElementsDelta.calculate(prevElements, nextElements),
      ).not.toThrow();
    });

    it("should create updated delta even when there is only version and versionNonce change", () => {
      const baseElement = API.createElement({
        type: "rectangle",
        x: 100,
        y: 100,
        strokeColor: "#000000",
        backgroundColor: "#ffffff",
      });

      const modifiedElement = {
        ...baseElement,
        version: baseElement.version + 1,
        versionNonce: baseElement.versionNonce + 1,
      };

      // Create maps for the delta calculation
      const prevElements = new Map([[baseElement.id, baseElement]]);
      const nextElements = new Map([[modifiedElement.id, modifiedElement]]);

      // Calculate the delta
      const delta = ElementsDelta.calculate(
        prevElements as SceneElementsMap,
        nextElements as SceneElementsMap,
      );

      expect(delta).toEqual(
        ElementsDelta.create(
          {},
          {},
          {
            [baseElement.id]: Delta.create(
              {
                version: baseElement.version,
                versionNonce: baseElement.versionNonce,
              },
              {
                version: baseElement.version + 1,
                versionNonce: baseElement.versionNonce + 1,
              },
            ),
          },
        ),
      );
    });
  });

  describe("squash", () => {
    it("should not squash when second delta is empty", () => {
      const updatedDelta = Delta.create(
        { x: 100, version: 1, versionNonce: 1 },
        { x: 200, version: 2, versionNonce: 2 },
      );

      const elementsDelta1 = ElementsDelta.create(
        {},
        {},
        { id1: updatedDelta },
      );
      const elementsDelta2 = ElementsDelta.empty();
      const elementsDelta = elementsDelta1.squash(elementsDelta2);

      expect(elementsDelta.isEmpty()).toBeFalsy();
      expect(elementsDelta).toBe(elementsDelta1);
      expect(elementsDelta.updated.id1).toBe(updatedDelta);
    });

    it("should squash mutually exclusive delta types", () => {
      const addedDelta = Delta.create(
        { x: 100, version: 1, versionNonce: 1, isDeleted: true },
        { x: 200, version: 2, versionNonce: 2, isDeleted: false },
      );

      const removedDelta = Delta.create(
        { x: 100, version: 1, versionNonce: 1, isDeleted: false },
        { x: 200, version: 2, versionNonce: 2, isDeleted: true },
      );

      const updatedDelta = Delta.create(
        { x: 100, version: 1, versionNonce: 1 },
        { x: 200, version: 2, versionNonce: 2 },
      );

      const elementsDelta1 = ElementsDelta.create(
        { id1: addedDelta },
        { id2: removedDelta },
        {},
      );

      const elementsDelta2 = ElementsDelta.create(
        {},
        {},
        { id3: updatedDelta },
      );

      const elementsDelta = elementsDelta1.squash(elementsDelta2);

      expect(elementsDelta.isEmpty()).toBeFalsy();
      expect(elementsDelta).toBe(elementsDelta1);
      expect(elementsDelta.added.id1).toBe(addedDelta);
      expect(elementsDelta.removed.id2).toBe(removedDelta);
      expect(elementsDelta.updated.id3).toBe(updatedDelta);
    });

    it("should squash the same delta types", () => {
      const elementsDelta1 = ElementsDelta.create(
        {
          id1: Delta.create(
            { x: 100, version: 1, versionNonce: 1, isDeleted: true },
            { x: 200, version: 2, versionNonce: 2, isDeleted: false },
          ),
        },
        {
          id2: Delta.create(
            { x: 100, version: 1, versionNonce: 1, isDeleted: false },
            { x: 200, version: 2, versionNonce: 2, isDeleted: true },
          ),
        },
        {
          id3: Delta.create(
            { x: 100, version: 1, versionNonce: 1 },
            { x: 200, version: 2, versionNonce: 2 },
          ),
        },
      );

      const elementsDelta2 = ElementsDelta.create(
        {
          id1: Delta.create(
            { y: 100, version: 2, versionNonce: 2, isDeleted: true },
            { y: 200, version: 3, versionNonce: 3, isDeleted: false },
          ),
        },
        {
          id2: Delta.create(
            { y: 100, version: 2, versionNonce: 2, isDeleted: false },
            { y: 200, version: 3, versionNonce: 3, isDeleted: true },
          ),
        },
        {
          id3: Delta.create(
            { y: 100, version: 2, versionNonce: 2 },
            { y: 200, version: 3, versionNonce: 3 },
          ),
        },
      );

      const elementsDelta = elementsDelta1.squash(elementsDelta2);

      expect(elementsDelta.isEmpty()).toBeFalsy();
      expect(elementsDelta).toBe(elementsDelta1);
      expect(elementsDelta.added.id1).toEqual(
        Delta.create(
          { x: 100, y: 100, version: 2, versionNonce: 2, isDeleted: true },
          { x: 200, y: 200, version: 3, versionNonce: 3, isDeleted: false },
        ),
      );
      expect(elementsDelta.removed.id2).toEqual(
        Delta.create(
          { x: 100, y: 100, version: 2, versionNonce: 2, isDeleted: false },
          { x: 200, y: 200, version: 3, versionNonce: 3, isDeleted: true },
        ),
      );
      expect(elementsDelta.updated.id3).toEqual(
        Delta.create(
          { x: 100, y: 100, version: 2, versionNonce: 2 },
          { x: 200, y: 200, version: 3, versionNonce: 3 },
        ),
      );
    });

    it("should squash different delta types ", () => {
      // id1: added   -> updated => added
      // id2: removed -> added   => added
      // id3: updated -> removed => removed
      const elementsDelta1 = ElementsDelta.create(
        {
          id1: Delta.create(
            { x: 100, version: 1, versionNonce: 1, isDeleted: true },
            { x: 101, version: 2, versionNonce: 2, isDeleted: false },
          ),
        },
        {
          id2: Delta.create(
            { x: 200, version: 1, versionNonce: 1, isDeleted: false },
            { x: 201, version: 2, versionNonce: 2, isDeleted: true },
          ),
        },
        {
          id3: Delta.create(
            { x: 300, version: 1, versionNonce: 1 },
            { x: 301, version: 2, versionNonce: 2 },
          ),
        },
      );

      const elementsDelta2 = ElementsDelta.create(
        {
          id2: Delta.create(
            { y: 200, version: 2, versionNonce: 2, isDeleted: true },
            { y: 201, version: 3, versionNonce: 3, isDeleted: false },
          ),
        },
        {
          id3: Delta.create(
            { y: 300, version: 2, versionNonce: 2, isDeleted: false },
            { y: 301, version: 3, versionNonce: 3, isDeleted: true },
          ),
        },
        {
          id1: Delta.create(
            { y: 100, version: 2, versionNonce: 2 },
            { y: 101, version: 3, versionNonce: 3 },
          ),
        },
      );

      const elementsDelta = elementsDelta1.squash(elementsDelta2);

      expect(elementsDelta.isEmpty()).toBeFalsy();
      expect(elementsDelta).toBe(elementsDelta1);
      expect(elementsDelta.added).toEqual({
        id1: Delta.create(
          { x: 100, y: 100, version: 2, versionNonce: 2, isDeleted: true },
          { x: 101, y: 101, version: 3, versionNonce: 3, isDeleted: false },
        ),
        id2: Delta.create(
          { x: 200, y: 200, version: 2, versionNonce: 2, isDeleted: true },
          { x: 201, y: 201, version: 3, versionNonce: 3, isDeleted: false },
        ),
      });
      expect(elementsDelta.removed).toEqual({
        id3: Delta.create(
          { x: 300, y: 300, version: 2, versionNonce: 2, isDeleted: false },
          { x: 301, y: 301, version: 3, versionNonce: 3, isDeleted: true },
        ),
      });
      expect(elementsDelta.updated).toEqual({});
    });

    it("should squash bound elements", () => {
      const elementsDelta1 = ElementsDelta.create(
        {},
        {},
        {
          id1: Delta.create(
            {
              version: 1,
              versionNonce: 1,
              boundElements: [{ id: "t1", type: "text" }],
            },
            {
              version: 2,
              versionNonce: 2,
              boundElements: [{ id: "t2", type: "text" }],
            },
          ),
        },
      );

      const elementsDelta2 = ElementsDelta.create(
        {},
        {},
        {
          id1: Delta.create(
            {
              version: 2,
              versionNonce: 2,
              boundElements: [{ id: "a1", type: "arrow" }],
            },
            {
              version: 3,
              versionNonce: 3,
              boundElements: [{ id: "a2", type: "arrow" }],
            },
          ),
        },
      );

      const elementsDelta = elementsDelta1.squash(elementsDelta2);

      expect(elementsDelta.updated.id1.deleted.boundElements).toEqual([
        { id: "t1", type: "text" },
        { id: "a1", type: "arrow" },
      ]);
      expect(elementsDelta.updated.id1.inserted.boundElements).toEqual([
        { id: "t2", type: "text" },
        { id: "a2", type: "arrow" },
      ]);
    });
  });
});

