};

const BUCKET_FILL_KEYBOARD_COLOR_PICKS = BUCKET_FILL_BACKGROUND_PICKS.filter(
  (color) => color !== COLOR_PALETTE.white,
);

/** Owns bucket-fill interaction and App-bound scene mutations. */
export class AppBucketFill {
  constructor(private app: App) {}

  private temporaryEyeDropper: EyeDropperProperties | null = null;

  /**
   * The click armed on pointer down, committed on pointer up. Deferring the
   * scene mutation to pointer up is what lets a pinch/pan second finger, a
   * long-press context menu, or a pointercancel abort the fill — on pointer
   * down the editor cannot yet know the gesture will stay a single-pointer
   * click.
   */
  private pending: ScenePoint | null = null;

  /** Arm a fill at the pointer-down position; nothing mutates yet. */
  handlePointerDown = (scenePointer: ScenePoint) => {
    this.pending = scenePointer;
  };

  /**
   * Commit the armed fill, at the pointer-DOWN position (what the user
   * aimed at). No-op when the gesture was aborted in the meantime.
   */
  handlePointerUp = () => {
    const scenePointer = this.pending;
    this.pending = null;
    if (scenePointer) {
      this.fill(scenePointer);
    }
  };

  /** Abort the armed fill (second finger, context menu, pointercancel). */
  cancel = () => {
    this.pending = null;
  };

  cycleBackgroundColor = () => {
    const currentColor = this.getBucketFillBackgroundColor(
      this.app.state.currentItemBackgroundColor,
    );
    const currentIndex = BUCKET_FILL_KEYBOARD_COLOR_PICKS.indexOf(currentColor);
    const nextColor =
      BUCKET_FILL_KEYBOARD_COLOR_PICKS[
        (currentIndex + 1) % BUCKET_FILL_KEYBOARD_COLOR_PICKS.length
      ];

    this.app.actionManager.executeAction(
      actionChangeBucketFillBackgroundColor,
      "keyboard",
      { currentItemBackgroundColor: nextColor },
    );
  };

  openTemporaryEyeDropper = () => {
    if (editorJotaiStore.get(activeEyeDropperAtom)) {
      return;
    }

    const eyeDropper: EyeDropperProperties = {
      colorPickerType: "elementBackground",
      keepOpenOnAlt: true,
      onSelect: (color) => {
        this.app.actionManager.executeAction(
          actionChangeBucketFillBackgroundColor,
          "ui",
          { currentItemBackgroundColor: color },
        );
      },
    };
    this.temporaryEyeDropper = eyeDropper;
    this.app.updateEditorAtom(activeEyeDropperAtom, eyeDropper);
  };

  closeTemporaryEyeDropper = () => {
    const eyeDropper = this.temporaryEyeDropper;
    this.temporaryEyeDropper = null;
    if (
      eyeDropper &&
      editorJotaiStore.get(activeEyeDropperAtom) === eyeDropper
    ) {
      this.app.updateEditorAtom(activeEyeDropperAtom, null);
    }
  };

  /**
   * Apply the current bucket fill settings to an existing fill-compatible
   * element (no-op when nothing would change). One undoable step.
   */
  private restyle = (element: NonDeletedExcalidrawElement) => {
    const backgroundColor = this.getBucketFillBackgroundColor(
      this.app.state.currentItemBackgroundColor,
    );
    if (
      element.backgroundColor === backgroundColor &&
      element.fillStyle === this.app.state.currentItemFillStyle &&
      element.opacity === this.app.state.currentItemOpacity
    ) {
      return;
    }
    this.app.scene.mutateElement(element, {
      backgroundColor,
      fillStyle: this.app.state.currentItemFillStyle,
      opacity: this.app.state.currentItemOpacity,
    });
    // the roughjs drawable is cached by element reference; in-place
    // mutation keeps the reference, so evict it or the canvas won't
    // reflect the new style
    ShapeCache.delete(element);
    this.app.scheduleCapture();
  };

  private fill = (scenePointer: ScenePoint) => {
    // shared with the generic shape background, but a transparent fill would
    // be invisible, so fall back to a real color (appState is not mutated)
    const backgroundColor = this.getBucketFillBackgroundColor(
      this.app.state.currentItemBackgroundColor,
    );

    const elements = this.app.scene.getNonDeletedElements();
    const elementsMap = this.app.scene.getNonDeletedElementsMap();
    const point = pointFrom<GlobalPoint>(scenePointer.x, scenePointer.y);

    const hitElement = this.app.getElementAtPosition(point[0], point[1]);

    // gap bridging is covered by the default gapTolerance (a bucket-specific
    // constant): connector edges close visual gaps without distorting the
    // shape, so no zoom-dependent tuning is needed
    const result = computeBucketFillPolygon({ point, elements, elementsMap });

    if (!result.ok) {
      // no region could be derived, but the click still landed on existing
      // paint (e.g. an orphaned fill whose boundaries were deleted, or a
      // hand-drawn strokeless bg polygon on empty canvas) — restyling it is
      // the sensible outcome, and beats a toast
      if (hitElement && isBucketFillCompatible(hitElement)) {
        this.restyle(hitElement);
        return;
      }
      if (result.reason === "too_complex") {
        this.app.setToast({
          message: t("bucketfill.tooComplex"),
          duration: 3000,
        });
      } else if (
        result.reason === "open_region" ||
        result.reason === "too_small" ||
        result.reason === "invalid_polygon"
      ) {
        this.app.setToast({
          message: t("bucketfill.noRegion"),
          duration: 3000,
        });
      }
      // "no_owner" stays silent — clicking empty canvas shouldn't nag
      return;
    }

    // re-clicking an already-filled region shouldn't stack a duplicate:
    // restyle the existing fill with the current settings, or no-op when
    // nothing would change
    if (
      hitElement &&
      isRestylableFill({
        hitElement,
        scenePoints: result.scenePoints,
        elementsMap,
      })
    ) {
      this.restyle(hitElement);
      return;
    }

    const { width, height } = getSizeFromPoints(result.scenePoints);
    // linear elements are normalized so points[0] must be [0, 0]; use the
    // first scene point as the element origin
    const [originX, originY] = result.scenePoints[0];
    const points = result.scenePoints.map((p) =>
      pointFrom<LocalPoint>(p[0] - originX, p[1] - originY),
    );

    const owner = result.ownerId ? elementsMap.get(result.ownerId) : null;
    // owner-less fills (regions formed by open lines) take their frame from
    // the click position and only inherit a group shared by every boundary
    const frameId = owner
      ? isFrameLikeElement(owner)
        ? owner.id
        : owner.frameId
      : this.app.getTopLayerFrameAtSceneCoords(scenePointer)?.id ?? null;
    const groupIds = owner
      ? owner.groupIds
      : result.boundaryElementIds
          .map((id) => elementsMap.get(id)?.groupIds)
          .filter((groupIds): groupIds is string[] => !!groupIds)
          .reduce(
            (common, groupIds) =>
              common === null
                ? groupIds
                : common.filter((groupId) => groupIds.includes(groupId)),
            null as string[] | null,
          ) ?? [];

    const fill = newLinearElement({
      type: "line",
      x: originX,
      y: originY,
      width,
      height,
      points,
      polygon: true,
      strokeColor: "transparent",
      backgroundColor,
      fillStyle: this.app.state.currentItemFillStyle,
      strokeWidth: 1,
      strokeStyle: "solid",
      roughness: 0,
      roundness: null,
      opacity: this.app.state.currentItemOpacity,
      frameId,
      groupIds,
      // no marker: fills are recognized by shape (`isBucketFillCompatible`),
      // since metadata would go stale the moment the user restyles the fill
    });

    // resolve the geometry's relative placement against the
    // deleted-inclusive array that `insertElementsAtIndex` operates on
    const anchorIndex = this.app.scene
      .getElementsIncludingDeleted()
      .findIndex((el) => el.id === result.insertion.elementId);
    this.app.scene.insertElementsAtIndex(
      [fill],
      anchorIndex < 0
        ? null
        : result.insertion.placement === "above"
        ? anchorIndex + 1
        : anchorIndex,
    );

    // Keep the bucket fill tool active and do NOT select the new fill, so the
    // user can keep filling regions back-to-back without re-selecting the tool
    // (even when the tool isn't locked).
    this.app.scheduleCapture();
  };

  /**
   * The color the bucket fill tool actually fills with: the shared
   * `currentItemBackgroundColor`, falling back to green when that is
   * transparent (the tool's picker doesn't offer transparent, but the shared
   * state can hold it from the generic shape picker).
   */
  public getBucketFillBackgroundColor = (
    backgroundColor: string,
    /** supply only for display purposes such as when applying to the cursor */
    theme?: Theme,
  ) =>
    isTransparent(backgroundColor)
      ? COLOR_PALETTE.green[DEFAULT_ELEMENT_BACKGROUND_COLOR_INDEX]
      : applyDarkModeFilter(backgroundColor, theme === THEME.DARK);
}

import { flushSync } from "react-dom";

import {
  DEFAULT_TEXT_ALIGN,
  DEFAULT_VERTICAL_ALIGN,
  getFontString,
  getLineHeight,
  isWritableElement,
  normalizeEOL,
  normalizeLink,
  viewportCoordsToSceneCoords,
} from "@excalidraw/common";

import {
  convertToExcalidrawElements,
  embeddableURLValidator,
  getCommonBounds,
  getEmbedLink,
  getLineHeightInPx,
  makeNextSelectedElementIds,
  maybeParseEmbedSrc,
  measureText,
  newElementWith,
  newTextElement,
  normalizeText,
  wrapText,
} from "@excalidraw/element";

import type { ExcalidrawElementSkeleton } from "@excalidraw/element";
import type {
  ExcalidrawElement,
  ExcalidrawEmbeddableElement,
  ExcalidrawTextElement,
  NonDeleted,
} from "@excalidraw/element/types";

import { actionCopy, actionCut } from "../actions";
import { tryParseSpreadsheet } from "../charts";
import { parseClipboard, parseDataTransferEvent } from "../clipboard";
import { ImageURLToFile, SVGStringToFile } from "../data/blob";
import { t } from "../i18n";
import { isMaybeMermaidDefinition } from "../mermaid";
import { withBatchedUpdates } from "../reactUtils";
import { getShortcutKey } from "../shortcut";
import { scrollBoundsIntoView } from "../viewport";

import type React from "react";

import type {
  ClipboardData,
  ParsedDataTransferFile,
  PastedMixedContent,
} from "../clipboard";
import type App from "./App";
import type { Offsets } from "../types";

let IS_PLAIN_PASTE = false;
let IS_PLAIN_PASTE_TIMER = 0;
let PLAIN_PASTE_TOAST_SHOWN = false;

type AppClipboardDependencies = {
  getContainer: () => HTMLDivElement | null;
};

/**
 * The clipboard: cut and copy (through their actions), and paste — the
 * pasted data parsed (`pasteFromClipboard`) and inserted as whatever it is
 * (`insertClipboardContent`): images or SVG code, elements, a Mermaid
 * definition, embeddable URLs, a spreadsheet (as a chart), mixed content,
 * or text. Pasted elements go in through `app.addElementsFromPasteOrLibrary`,
 * as a library item or a drop does.
 */
export class AppClipboard {
  constructor(
    private app: App,
    private dependencies: AppClipboardDependencies,
  ) {}

  // Copy/paste

  public onCut = withBatchedUpdates((event: ClipboardEvent) => {
    if (!this.app.isInteractionEnabled()) {
      return;
    }
    const isExcalidrawActive = this.dependencies
      .getContainer()
      ?.contains(this.app.ownerDocument.activeElement);
    if (!isExcalidrawActive || isWritableElement(event.target)) {
      return;
    }
    this.app.actionManager.executeAction(actionCut, "keyboard", event);
    event.preventDefault();
    event.stopPropagation();
  });

  public onCopy = withBatchedUpdates((event: ClipboardEvent) => {
    if (!this.app.isInteractionEnabled()) {
      return;
    }
    const isExcalidrawActive = this.dependencies
      .getContainer()
      ?.contains(this.app.ownerDocument.activeElement);
    if (!isExcalidrawActive || isWritableElement(event.target)) {
      return;
    }
    this.app.actionManager.executeAction(actionCopy, "keyboard", event);
    event.preventDefault();
    event.stopPropagation();
  });

  // TODO: Cover with tests
  private async insertClipboardContent(
    data: ClipboardData,
    dataTransferFiles: ParsedDataTransferFile[],
    isPlainPaste: boolean,
  ) {
    const { x: sceneX, y: sceneY } = viewportCoordsToSceneCoords(
      {
        clientX: this.app.viewport.lastPosition.x,
        clientY: this.app.viewport.lastPosition.y,
      },
      this.app.state,
    );

    // ------------------- Error -------------------
    if (data.errorMessage) {
      this.app.setState({ errorMessage: data.errorMessage });
      return;
    }

    // ------------------- Mixed content with no files -------------------
    if (dataTransferFiles.length === 0 && !isPlainPaste && data.mixedContent) {
      await this.addElementsFromMixedContentPaste(data.mixedContent, {
        isPlainPaste,
        sceneX,
        sceneY,
      });
      return;
    }

    // ------------------- Spreadsheet -------------------

    if (!isPlainPaste && data.text) {
      const result = tryParseSpreadsheet(data.text);
      if (result.ok) {
        this.app.setState({
          openDialog: {
            name: "charts",
            data: result.data,
            rawText: data.text,
          },
        });
        return;
      }
    }

    // ------------------- Images or SVG code -------------------
    const imageFiles = dataTransferFiles.map((data) => data.file);

    if (imageFiles.length === 0 && data.text && !isPlainPaste) {
      const trimmedText = data.text.trim();
      if (trimmedText.startsWith("<svg") && trimmedText.endsWith("</svg>")) {
        // ignore SVG validation/normalization which will be done during image
        // initialization
        imageFiles.push(SVGStringToFile(trimmedText));
      }
    }

    if (imageFiles.length > 0) {
      if (this.app.isToolSupported("image")) {
        await this.app.insertImages(imageFiles, sceneX, sceneY);
      } else {
        this.app.setState({ errorMessage: t("errors.imageToolNotSupported") });
      }
      return;
    }

    // ------------------- Elements -------------------
    if (data.elements) {
      const elements = (
        data.programmaticAPI
          ? convertToExcalidrawElements(
              data.elements as ExcalidrawElementSkeleton[],
            )
          : data.elements
      ) as readonly ExcalidrawElement[];
      // TODO: remove formatting from elements if isPlainPaste
      this.app.addElementsFromPasteOrLibrary({
        elements,
        files: data.files || null,
        position:
          this.app.editorInterface.formFactor === "desktop"
            ? "cursor"
            : "center",
        retainSeed: isPlainPaste,
        preserveFrameChildrenOrder: true,
      });
      return;
    }

    // ------------------- Only textual stuff remaining -------------------
    if (!data.text) {
      return;
    }

    // ------------------- Successful Mermaid -------------------
    if (!isPlainPaste && isMaybeMermaidDefinition(data.text)) {
      const api = await import("@excalidraw/mermaid-to-excalidraw");
      try {
        const { elements: skeletonElements, files = {} } =
          await api.parseMermaidToExcalidraw(data.text);

        const elements = convertToExcalidrawElements(skeletonElements, {
          regenerateIds: true,
        });

        this.app.addElementsFromPasteOrLibrary({
          elements,
          files,
          position:
            this.app.editorInterface.formFactor === "desktop"
              ? "cursor"
              : "center",
        });

        return;
      } catch (err: any) {
        console.warn(
          `parsing pasted text as mermaid definition failed: ${err.message}`,
        );
      }
    }

    // ------------------- Pure embeddable URLs -------------------
    const nonEmptyLines = normalizeEOL(data.text)
      .split(/\n+/)
      .map((s) => s.trim())
      .filter(Boolean);
    const embbeddableUrls = nonEmptyLines
      .map((str) => maybeParseEmbedSrc(str))
      .filter(
        (string) =>
          embeddableURLValidator(string, this.app.props.validateEmbeddable) &&
          (/^(http|https):\/\/[^\s/$.?#].[^\s]*$/.test(string) ||
            getEmbedLink(string)?.type === "video"),
      );

    if (
      !isPlainPaste &&
      embbeddableUrls.length > 0 &&
      embbeddableUrls.length === nonEmptyLines.length
    ) {
      const embeddables: NonDeleted<ExcalidrawEmbeddableElement>[] = [];
      for (const url of embbeddableUrls) {
        const prevEmbeddable: ExcalidrawEmbeddableElement | undefined =
          embeddables[embeddables.length - 1];
        const embeddable = this.app.insertEmbeddableElement({
          sceneX: prevEmbeddable
            ? prevEmbeddable.x + prevEmbeddable.width + 20
            : sceneX,
          sceneY,
          link: normalizeLink(url),
        });
        if (embeddable) {
          embeddables.push(embeddable);
        }
      }
      if (embeddables.length) {
        this.app.store.scheduleCapture();
        this.app.setState({
          selectedElementIds: Object.fromEntries(
            embeddables.map((embeddable) => [embeddable.id, true]),
          ),
        });
      }
      return;
    }

    // ------------------- Text -------------------
    this.addTextFromPaste(data.text, isPlainPaste);
  }

  /**
   * Ctrl/Cmd+V: whether the paste event that follows is a plain one (with
   * Shift)
   */
  public onPasteShortcut = (event: React.KeyboardEvent | KeyboardEvent) => {
    IS_PLAIN_PASTE = event.shiftKey;
    clearTimeout(IS_PLAIN_PASTE_TIMER);
    // reset (100ms to be safe that we it runs after the ensuing
    // paste event). Though, technically unnecessary to reset since we
    // (re)set the flag before each paste event.
    IS_PLAIN_PASTE_TIMER = this.app.ownerWindow.setTimeout(() => {
      IS_PLAIN_PASTE = false;
    }, 100);
  };

  public clearPlainPaste = () => {
    clearTimeout(IS_PLAIN_PASTE_TIMER);
    IS_PLAIN_PASTE_TIMER = 0;
    IS_PLAIN_PASTE = false;
  };

  public pasteFromClipboard = withBatchedUpdates(
    async (event: ClipboardEvent) => {
      if (!this.app.isInteractionEnabled()) {
        return;
      }

      const isPlainPaste = !!IS_PLAIN_PASTE;

      // #686
      const target = this.app.ownerDocument.activeElement;
      const isExcalidrawActive = this.dependencies
        .getContainer()
        ?.contains(target);
      if (event && !isExcalidrawActive) {
        return;
      }

      const elementUnderCursor = this.app.ownerDocument.elementFromPoint(
        this.app.viewport.lastPosition.x,
        this.app.viewport.lastPosition.y,
      );
      if (
        event &&
        (!(
          elementUnderCursor instanceof this.app.ownerWindow.HTMLCanvasElement
        ) ||
          isWritableElement(target))
      ) {
        return;
      }

      // must be called in the same frame (thus before any awaits) as the paste
      // event else some browsers (FF...) will clear the clipboardData
      // (something something security)
      const dataTransferList = await parseDataTransferEvent(event);

      const filesList = dataTransferList.getFiles();

      const data = await parseClipboard(dataTransferList, isPlainPaste);

      if (this.app.props.onPaste) {
        try {
          if ((await this.app.props.onPaste(data, event)) === false) {
            return;
          }
        } catch (error: any) {
          console.error(error);
        }
      }

      await this.insertClipboardContent(data, filesList, isPlainPaste);

      this.app.setActiveTool(
        { type: this.app.state.preferredSelectionTool.type },
        { keepSelection: true },
      );
      event?.preventDefault();
    },
  );

  // TODO rewrite this to paste both text & images at the same time if
  // pasted data contains both
  private async addElementsFromMixedContentPaste(
    mixedContent: PastedMixedContent,
    {
      isPlainPaste,
      sceneX,
      sceneY,
    }: { isPlainPaste: boolean; sceneX: number; sceneY: number },
  ) {
    if (
      !isPlainPaste &&
      mixedContent.some((node) => node.type === "imageUrl") &&
      this.app.isToolSupported("image")
    ) {
      const imageURLs = mixedContent
        .filter((node) => node.type === "imageUrl")
        .map((node) => node.value);
      const responses = await Promise.all(
        imageURLs.map(async (url) => {
          try {
            return { file: await ImageURLToFile(url) };
          } catch (error: any) {
            let errorMessage = error.message;
            if (error.cause === "FETCH_ERROR") {
              errorMessage = t("errors.failedToFetchImage");
            } else if (error.cause === "UNSUPPORTED") {
              errorMessage = t("errors.unsupportedFileType");
            }
            return { errorMessage };
          }
        }),
      );

      const imageFiles = responses
        .filter((response): response is { file: File } => !!response.file)
        .map((response) => response.file);
      await this.app.insertImages(imageFiles, sceneX, sceneY);
      const error = responses.find((response) => !!response.errorMessage);
      if (error && error.errorMessage) {
        this.app.setState({ errorMessage: error.errorMessage });
      }
    } else {
      const textNodes = mixedContent.filter((node) => node.type === "text");
      if (textNodes.length) {
        this.addTextFromPaste(
          textNodes.map((node) => node.value).join("\n\n"),
          isPlainPaste,
        );
      }
    }
  }

  private addTextFromPaste(text: string, isPlainPaste = false) {
    const { x, y } = viewportCoordsToSceneCoords(
      {
        clientX: this.app.viewport.lastPosition.x,
        clientY: this.app.viewport.lastPosition.y,
      },
      this.app.state,
    );

    const textElementProps = {
      x,
      y,
      strokeColor: this.app.state.currentItemStrokeColor,
      backgroundColor: this.app.state.currentItemBackgroundColor,
      fillStyle: this.app.state.currentItemFillStyle,
      strokeWidth: this.app.getCurrentItemStrokeWidth("text"),
      strokeStyle: this.app.state.currentItemStrokeStyle,
      roundness: null,
      roughness: this.app.state.currentItemRoughness,
      opacity: this.app.state.currentItemOpacity,
      text,
      fontSize: this.app.state.currentItemFontSize,
      fontFamily: this.app.state.currentItemFontFamily,
      textAlign: DEFAULT_TEXT_ALIGN,
      verticalAlign: DEFAULT_VERTICAL_ALIGN,
      locked: false,
    };
    const fontString = getFontString({
      fontSize: textElementProps.fontSize,
      fontFamily: textElementProps.fontFamily,
    });
    const lineHeight = getLineHeight(textElementProps.fontFamily);
    const LINE_GAP = 10;

    const lines = isPlainPaste ? [text] : text.split("\n");
    const createTextElements = (maxTextWidth: number) => {
      let currentY = y;
      return lines.reduce((acc: ExcalidrawTextElement[], line, idx) => {
        const originalText = normalizeText(line).trim();
        if (originalText.length) {
          const topLayerFrame = this.app.getTopLayerFrameAtSceneCoords({
            x,
            y: currentY,
          });

          let metrics = measureText(originalText, fontString, lineHeight);
          const isTextUnwrapped = metrics.width > maxTextWidth;

          const text = isTextUnwrapped
            ? wrapText(originalText, fontString, maxTextWidth)
            : originalText;

          metrics = isTextUnwrapped
            ? measureText(text, fontString, lineHeight)
            : metrics;

          const startX = x - metrics.width / 2;
          const startY = currentY - metrics.height / 2;

          const element = newTextElement({
            ...textElementProps,
            x: startX,
            y: startY,
            text,
            originalText,
            lineHeight,
            autoResize: !isTextUnwrapped,
            frameId: topLayerFrame ? topLayerFrame.id : null,
          });
          acc.push(element);
          currentY += element.height + LINE_GAP;
        } else {
          const prevLine = lines[idx - 1]?.trim();
          // add paragraph only if previous line was not empty, IOW don't add
          // more than one empty line
          if (prevLine) {
            currentY +=
              getLineHeightInPx(textElementProps.fontSize, lineHeight) +
              LINE_GAP;
          }
        }

        return acc;
      }, []);
    };

    // long texts wrap as a typed one does; wrapped to fit the view, all of
    // it is brought in view, too — by moving it there (as far as the view
    // would have to scroll), not the view
    const pasteWithin = (offsets: Required<Offsets>) => {
      const textElements = createTextElements(
        this.app.text.getMaxTextWidth(offsets),
      );
      const scroll =
        textElements.length && textElements.some((el) => !el.autoResize)
          ? scrollBoundsIntoView({
              bounds: getCommonBounds(textElements),
              appState: this.app.state,
              offsets,
            })
          : null;
      if (!scroll) {
        return textElements;
      }
      const dx = scroll.scrollX - this.app.state.scrollX;
      const dy = scroll.scrollY - this.app.state.scrollY;
      return textElements.map((element) => {
        const nextX = element.x + dx;
        const nextY = element.y + dy;
        // at the point it's pasted at: its center
        const topLayerFrame = this.app.getTopLayerFrameAtSceneCoords({
          x: nextX + element.width / 2,
          y: nextY + element.height / 2,
        });
        return newElementWith(element, {
          x: nextX,
          y: nextY,
          frameId: topLayerFrame ? topLayerFrame.id : null,
        });
      });
    };
    // laid out as if the stats panel weren't there, to see where it lands:
    // it counts only beside it
    const offsets = this.app.text.getTextViewportOffsets();
    let textElements = pasteWithin(offsets);
    if (textElements.length === 0) {
      return;
    }
    const getSelectedElementIds = () =>
      makeNextSelectedElementIds(
        Object.fromEntries(textElements.map((el) => [el.id, true])),
        this.app.state,
      );

    if (this.app.viewport.getSideUIRect("stats")) {
      // selected, it's in the stats panel, which grows to show its
      // properties: rendered so (not captured yet), the panels are measured
      // as they'll be — the styles panel, too, shown then, not reserved
      flushSync(() => {
        this.app.insertNewElements(textElements);
        this.app.setState({ selectedElementIds: getSelectedElementIds() });
      });
      const besideOffsets = this.app.text.getTextViewportOffsets(
        getCommonBounds(textElements),
      );
      if (
        besideOffsets.left !== offsets.left ||
        besideOffsets.right !== offsets.right
      ) {
        // beside the stats panel, or the styles panel's not as reserved:
        // laid out again, as the same elements (for anyone who's seen them
        // rendered already)
        const relaid = pasteWithin(besideOffsets);
        const pastedIds = new Set(textElements.map((element) => element.id));
        textElements = textElements.map((element, index) => {
          const { x, y, width, height, text, autoResize, frameId } =
            relaid[index];
          return newElementWith(element, {
            x,
            y,
            width,
            height,
            text,
            autoResize,
            frameId,
          });
        });
        this.app.scene.replaceAllElements(
          this.app.scene
            .getElementsIncludingDeleted()
            .filter((element) => !pastedIds.has(element.id)),
        );
        this.app.insertNewElements(textElements);
      }
    } else {
      this.app.insertNewElements(textElements);
    }
    this.app.store.scheduleCapture();
    this.app.setState({ selectedElementIds: getSelectedElementIds() });

    if (
      !isPlainPaste &&
      textElements.length > 1 &&
      PLAIN_PASTE_TOAST_SHOWN === false &&
      this.app.editorInterface.formFactor !== "phone"
    ) {
      this.app.setToast({
        message: t("toast.pasteAsSingleElement", {
          shortcut: getShortcutKey("CtrlOrCmd+Shift+V"),
        }),
        duration: 5000,
      });
      PLAIN_PASTE_TOAST_SHOWN = true;
    }
  }
}

import { CURSOR_TYPE, KEYS, MIME_TYPES, THEME } from "@excalidraw/common";

import { isHandToolActive, isEraserActive } from "../appState";

import { bucketFillIconSvgPaths } from "./icons";

import type { AppState, DataURL } from "../types";
import type App from "./App";

const laserPointerCursorSVG_tag = `<svg viewBox="0 0 24 24" stroke-width="1" width="28" height="28" xmlns="http://www.w3.org/2000/svg">`;
const laserPointerCursorBackgroundSVG = `<path d="M6.164 11.755a5.314 5.314 0 0 1-4.932-5.298 5.314 5.314 0 0 1 5.311-5.311 5.314 5.314 0 0 1 5.307 5.113l8.773 8.773a3.322 3.322 0 0 1 0 4.696l-.895.895a3.322 3.322 0 0 1-4.696 0l-8.868-8.868Z" style="fill:#fff"/>`;
const laserPointerCursorIconSVG = `<path stroke="#1b1b1f" fill="#fff" d="m7.868 11.113 7.773 7.774a2.359 2.359 0 0 0 1.667.691 2.368 2.368 0 0 0 2.357-2.358c0-.625-.248-1.225-.69-1.667L11.201 7.78 9.558 9.469l-1.69 1.643v.001Zm10.273 3.606-3.333 3.333m-3.25-6.583 2 2m-7-7 3 3M3.664 3.625l1 1M2.529 6.922l1.407-.144m5.735-2.932-1.118.866M4.285 9.823l.758-1.194m1.863-6.207-.13 1.408"/>`;

const laserPointerCursorDataURL_lightMode = `data:${
  MIME_TYPES.svg
},${encodeURIComponent(
  `${laserPointerCursorSVG_tag}${laserPointerCursorIconSVG}</svg>`,
)}`;
const laserPointerCursorDataURL_darkMode = `data:${
  MIME_TYPES.svg
},${encodeURIComponent(
  `${laserPointerCursorSVG_tag}${laserPointerCursorBackgroundSVG}${laserPointerCursorIconSVG}</svg>`,
)}`;

const createBucketFillCursorDataURL = (color: string) => {
  const paths = bucketFillIconSvgPaths
    .map(
      (path, index) =>
        `<path d="${path}" ${index < 2 ? `fill="${color}"` : ""} />`,
    )
    .join("");

  return `data:${MIME_TYPES.svg},${encodeURIComponent(
    `<svg viewBox="0 0 24 24" width="24" height="24" fill="none" xmlns="http://www.w3.org/2000/svg" stroke-linecap="round" stroke-linejoin="round"><g stroke="#fff" fill="#fff" stroke-width="5">${paths}</g><g stroke="#1b1b1f" stroke-width="1.25">${paths}</g></svg>`,
  )}`;
};

/**
 * Captures all cursor management for the interactive canvas.
 *
 * The canvas cursor is set exclusively imperatively, through this class —
 * never via inline styles or React-rendered `style.cursor`, which React
 * would rewrite on rerender whenever the computed value changes, clobbering
 * cursors set here.
 */
export class AppCursor {
  private toolCursorMemo: {
    canvas: HTMLCanvasElement;
    type: AppState["activeTool"]["type"];
    bucketFillColor?: string;
    theme?: AppState["theme"];
  } | null = null;

  private eraserCanvasCache:
    | (HTMLCanvasElement & { theme?: AppState["theme"] })
    | null = null;
  private eraserPreviewDataURL: DataURL | null = null;

  constructor(private app: App) {}

  private get canvas() {
    return this.app.interactiveCanvas;
  }

  set = (cursor: string) => {
    // Hover and interaction cursors override the resting tool cursor. The
    // next applyForTool() must restore it even if the tool itself is unchanged.
    this.toolCursorMemo = null;
    if (this.canvas) {
      this.canvas.style.cursor = cursor;
    }
  };

  /**
   * Resets to the resting cursor — the cursor shown when no interaction or
   * hover affordance overrides it: the view-mode grab cursor when
   * drag-to-pan applies, the active tool's cursor otherwise.
   */
  reset = () => {
    if (
      this.app.state.viewModeEnabled &&
      !this.app.isActiveToolPointerCapturing()
    ) {
      if (this.app.isNavigationEnabled()) {
        this.set(CURSOR_TYPE.GRAB);
      } else {
        this.clear();
      }
    } else {
      this.applyForTool();
    }
  };

  /** applies the given tool's cursor (defaults to the active tool) */
  applyForTool = (
    activeTool: AppState["activeTool"] = this.app.state.activeTool,
  ) => {
    const canvas = this.canvas;
    if (!canvas) {
      return;
    }

    const theme =
      activeTool.type === "eraser" ||
      activeTool.type === "laser" ||
      activeTool.type === "bucketfill"
        ? this.app.state.theme
        : undefined;

    const bucketFillColor =
      activeTool.type === "bucketfill"
        ? this.app.bucketFill.getBucketFillBackgroundColor(
            this.app.state.currentItemBackgroundColor,
            theme,
          )
        : undefined;
    const memo = this.toolCursorMemo;
    if (
      memo?.canvas === canvas &&
      memo.type === activeTool.type &&
      memo.bucketFillColor === bucketFillColor &&
      memo.theme === theme
    ) {
      return;
    }

    if (activeTool.type === "selection") {
      this.clear();
    } else if (isHandToolActive({ activeTool })) {
      this.set(CURSOR_TYPE.GRAB);
    } else if (isEraserActive({ activeTool })) {
      this.applyEraser();
    } else if (activeTool.type === "autoshape") {
      this.set(CURSOR_TYPE.CROSSHAIR);
    } else if (activeTool.type === "bucketfill") {
      // The hotspot is the center of the paint droplet in the icon.
      this.set(
        `url(${createBucketFillCursorDataURL(bucketFillColor!)}) 5 18, auto`,
      );
    } else if (activeTool.type === "laser") {
      const url =
        this.app.state.theme === THEME.LIGHT
          ? laserPointerCursorDataURL_lightMode
          : laserPointerCursorDataURL_darkMode;
      this.set(`url(${url}), auto`);
    } else if (!["image", "custom"].includes(activeTool.type)) {
      this.set(CURSOR_TYPE.CROSSHAIR);
      // do nothing if image tool is selected which suggests there's
      // an image-preview set as the cursor
      // Ignore custom type as well and let host decide
    } else if (activeTool.type !== "image") {
      this.set(CURSOR_TYPE.AUTO);
    }

    this.toolCursorMemo = {
      canvas,
      type: activeTool.type,
      bucketFillColor,
      theme,
    };
  };

  /**
   * Re-runs the hover cursor logic at the last known pointer position by
   * re-dispatching a synthetic pointermove — for state changes that alter
   * what hovering means without the pointer moving (e.g. the tool reverting
   * to selection after an element is created). Mouse only: touch and pen
   * have no resting hover to restore.
   */
  refreshHover = () => {
    const lastEvent =
      this.app.lastPointerMoveEvent ?? this.app.lastPointerUpEvent;

    if (!lastEvent || !this.canvas) {
      return;
    }

    const pointerType = (lastEvent as PointerEvent).pointerType;
    if (pointerType && pointerType !== "mouse") {
      return;
    }

    // jsdom has no PointerEvent; a MouseEvent of type "pointermove" walks
    // the identical dispatch path
    const EventConstructor =
      typeof PointerEvent !== "undefined" ? PointerEvent : MouseEvent;

    // with the modifiers held now, which the move would otherwise release
    const modifiers = this.app.modifiers.get();
    this.canvas.dispatchEvent(
      new EventConstructor("pointermove", {
        bubbles: true,
        cancelable: true,
        clientX: lastEvent.clientX,
        clientY: lastEvent.clientY,
        altKey: modifiers.alt,
        shiftKey: modifiers.shift,
        [KEYS.CTRL_OR_CMD]: modifiers.ctrlOrCmd,
      }),
    );
  };

  /** clears the inline cursor so the environment default (CSS) applies */
  private clear = () => {
    this.set("");
  };

  private applyEraser = () => {
    const cursorImageSizePx = 20;
    const theme = this.app.state.theme;

    if (!this.eraserCanvasCache || this.eraserCanvasCache.theme !== theme) {
      const isDarkTheme = theme === THEME.DARK;
      this.eraserCanvasCache = document.createElement("canvas");
      this.eraserCanvasCache.theme = theme;
      this.eraserCanvasCache.height = cursorImageSizePx;
      this.eraserCanvasCache.width = cursorImageSizePx;
      const context = this.eraserCanvasCache.getContext("2d")!;
      context.lineWidth = 1;
      context.beginPath();
      context.arc(
        this.eraserCanvasCache.width / 2,
        this.eraserCanvasCache.height / 2,
        5,
        0,
        2 * Math.PI,
      );
      context.fillStyle = isDarkTheme ? "#000" : "#fff";
      context.fill();
      context.strokeStyle = isDarkTheme ? "#fff" : "#000";
      context.stroke();
      this.eraserPreviewDataURL = this.eraserCanvasCache.toDataURL(
        MIME_TYPES.svg,
      ) as DataURL;
    }

    this.set(
      `url(${this.eraserPreviewDataURL}) ${cursorImageSizePx / 2} ${
        cursorImageSizePx / 2
      }, auto`,
    );
  };
}

import { randomInteger } from "@excalidraw/common";

import {
  bindBindingElement,
  convertToShape,
  convertToShapeHandlePointerMoveFromPointerDown,
  getHoveredElementForBinding,
  isBindingElement,
  isLineElement,
  LinearElementEditor,
  newArrowElement,
  updateBoundPoint,
} from "@excalidraw/element";

import type {
  ExcalidrawArrowElement,
  ExcalidrawLineElement,
  NonDeleted,
  NonDeletedExcalidrawElement,
  PointsPositionUpdates,
} from "@excalidraw/element/types";

import { actionFinalize } from "../actions";
import { DrawShapeTrail } from "../drawShapeTrail";

import type App from "./App";
import type { PointerDownState } from "../types";

/**
 * Captures the App state management for the drawShape tool (free-form
 * sketch converted into a recognized excalidraw element). Pointer events
 * are piped here from App.
 *
 * The gesture is committed by `finalize()` — recognize → (maybe upgrade
 * line to arrow) → insert → bind endpoints — which is invoked from within
 * `actionFinalize`, the editor's single finalization funnel. Whatever
 * triggers a finalize (the gesture's own pointerup, a mid-gesture paste
 * switching tools, …), the pending sketch resolves there exactly once.
 */
export class AppDrawShape {
  public trail: DrawShapeTrail;

  /** a pointerdown started a sketch that `finalize()` hasn't resolved yet */
  private gestureInProgress = false;

  constructor(private app: App) {
    this.trail = new DrawShapeTrail(app);
  }

  stop = () => {
    this.trail.stop();
  };

  hasPendingGesture = () => {
    return this.gestureInProgress;
  };

  handlePointerDown = (pointerDownState: PointerDownState) => {
    if (this.gestureInProgress) {
      // a stale gesture (e.g. after a missed pointerup) — resolve it before
      // starting a new one
      this.app.actionManager.executeAction(actionFinalize);
    }
    this.gestureInProgress = true;
    this.trail.startPath(
      pointerDownState.lastCoords.x,
      pointerDownState.lastCoords.y,
    );
  };

  /** returns true when the pointermove was consumed by the shape preview */
  handlePointerMove = (pointerCoords: { x: number; y: number }): boolean => {
    return convertToShapeHandlePointerMoveFromPointerDown(
      this.app,
      pointerCoords,
    );
  };

  /**
   * Binds both endpoints of a freshly inserted drawShape arrow to the
   * bindable elements they hover, if any.
   *
   * Endpoints bind in "orbit" mode — the arrow starts/ends at the target's
   * outline — even when the stroke was started or released inside the shape
   * (a sketched connector aims at the shape, not at a point inside it). The
   * exception is a sketch contained in a single shape: both ends then bind
   * "inside" and stay where they were drawn, like the interactive
   * inside→inside flow.
   */
  private bindRecognizedArrow = (arrow: NonDeleted<ExcalidrawArrowElement>) => {
    const { app } = this;
    const elementsMap = app.scene.getNonDeletedElementsMap();
    const elements = app.scene.getNonDeletedElements();

    const endpoints = (["start", "end"] as const).map((startOrEnd) => {
      const globalPoint = LinearElementEditor.getPointAtIndexGlobalCoordinates(
        arrow,
        startOrEnd === "start" ? 0 : -1,
        elementsMap,
      );
      return {
        startOrEnd,
        globalPoint,
        target: getHoveredElementForBinding(
          globalPoint,
          elements,
          elementsMap,
          app.state.zoom,
        ),
      };
    });

    const sameTarget =
      !!endpoints[0].target && endpoints[0].target === endpoints[1].target;
    const isMidpointSnappingEnabled =
      app.state.isMidpointSnappingEnabled && !app.state.gridModeEnabled;

    for (const { startOrEnd, globalPoint, target } of endpoints) {
      if (target) {
        bindBindingElement(
          arrow,
          target,
          sameTarget ? "inside" : "orbit",
          startOrEnd,
          app.scene,
          app.state.zoom,
          globalPoint,
          app.state.isBindingEnabled,
          isMidpointSnappingEnabled,
        );
      }
    }

    if (sameTarget) {
      return;
    }

    // pull the orbit-bound endpoints onto the target outlines; both bindings
    // exist by now, so each endpoint clips the segment between the two focus
    // points (mirrors the focusPoint branch of bindOrUnbindBindingElement)
    const updates: PointsPositionUpdates = new Map();
    for (const { startOrEnd, target } of endpoints) {
      if (!target) {
        continue;
      }
      const point = updateBoundPoint(
        arrow,
        startOrEnd === "start" ? "startBinding" : "endBinding",
        startOrEnd === "start" ? arrow.startBinding : arrow.endBinding,
        target,
        elementsMap,
      );
      if (point) {
        updates.set(startOrEnd === "start" ? 0 : arrow.points.length - 1, {
          point,
        });
      }
    }
    if (updates.size) {
      LinearElementEditor.movePoints(arrow, app.scene, updates);
    }
  };

  /**
   * A sketched line that connects a bindable element with something else —
   * another element or blank canvas — was meant as a connector: upgrade it
   * to an arrow (called before insertion). A line touching no shape, or
   * contained in a single shape (an annotation, not a connector), stays a
   * line.
   */
  private maybeUpgradeLineToArrow = (
    line: NonDeleted<ExcalidrawLineElement>,
  ): NonDeleted<ExcalidrawArrowElement> | null => {
    const { app } = this;
    const elementsMap = app.scene.getNonDeletedElementsMap();
    const elements = app.scene.getNonDeletedElements();

    const [startTarget, endTarget] = ([0, -1] as const).map((index) =>
      getHoveredElementForBinding(
        LinearElementEditor.getPointAtIndexGlobalCoordinates(
          line,
          index,
          elementsMap,
        ),
        elements,
        elementsMap,
        app.state.zoom,
      ),
    );
    if ((!startTarget && !endTarget) || startTarget === endTarget) {
      return null;
    }

    return newArrowElement({
      type: "arrow",
      x: line.x,
      y: line.y,
      width: line.width,
      height: line.height,
      startArrowhead: null,
      endArrowhead: app.state.currentItemEndArrowhead,
      points: line.points,
      groupIds: line.groupIds,
      frameId: line.frameId,
      locked: false,
      angle: line.angle,
      strokeColor: line.strokeColor,
      backgroundColor: line.backgroundColor,
      fillStyle: line.fillStyle,
      roughness: line.roughness,
      opacity: line.opacity,
      strokeStyle: line.strokeStyle,
      strokeWidth: line.strokeWidth,
    });
  };

  /**
   * Commits the pending sketch, if any, and clears the trail. Invoked from
   * within `actionFinalize` — never call directly, execute `actionFinalize`
   * instead so element insertion flows into the action's returned elements.
   */
  finalize = () => {
    const { app } = this;

    // when no gesture is in progress this only clears residual trail state
    const points = this.gestureInProgress ? this.trail.getCurrentPoints() : [];
    this.gestureInProgress = false;
    this.trail.endPath();

    // note: size gate inside recognizeShape
    if (points.length >= 3) {
      const detectedElement =
        app.state.newElement ||
        convertToShape(
          points,
          app.state,
          app.scene.getNonDeletedElementsMap(),
          app.state.newElement,
          app.scene.getNonDeletedFramesLikes(),
        );

      if (detectedElement) {
        let element: NonDeletedExcalidrawElement = {
          ...detectedElement,
          seed: randomInteger(),
          opacity: app.state.currentItemOpacity,
        };

        if (app.state.isBindingEnabled && isLineElement(element)) {
          element = this.maybeUpgradeLineToArrow(element) ?? element;
        }

        app.insertNewElement(element);

        if (app.state.isBindingEnabled && isBindingElement(element)) {
          this.bindRecognizedArrow(element);
        }
      }
    }

    this.trail.clearTrails();
  };
}

import { flushSync } from "react-dom";

import {
  arrayToMap,
  distance,
  getGridPoint,
  randomInteger,
  viewportCoordsToSceneCoords,
} from "@excalidraw/common";

import {
  addElementsToFrame,
  advanceDuplicatedListMarkers,
  applyListMarkerAdvances,
  deepCopyElement,
  duplicateElements,
  filterElementsEligibleAsFrameChildren,
  getCommonBounds,
  isBindableElement,
  isLinearElement,
  isTextElement,
  LinearElementEditor,
  newElementWith,
  reconcileDuplicatedElements,
  syncMovedIndices,
  updateBoundElements,
} from "@excalidraw/element";

import type { ListMarkerAdvance } from "@excalidraw/element";
import type {
  ExcalidrawElement,
  ExcalidrawTextElement,
} from "@excalidraw/element/types";

import { getSelectionStateForElements } from "./App.selection";

import type { PointerDownState } from "../types";

import type App from "./App";

type Duplication = Pick<
  ReturnType<typeof duplicateElements>,
  | "duplicatedElements"
  | "duplicateElementsMap"
  | "origElementsMap"
  | "origIdToDuplicateId"
  | "duplicateIdToOrigId"
>;

/**
 * Owns the duplication paths which involve the host (`props.onDuplicate`):
 * duplicating elements into the scene (paste, library insert etc.), and
 * duplicating the dragged selection (alt-drag). The duplicate action shares
 * `runOnDuplicate()`.
 */
export class AppDuplicate {
  constructor(
    private app: App,
    private dependencies: {
      /** pointers currently down */
      getPointerCount: () => number;
    },
  ) {}

  /**
   * Hands the duplication over to the host's `props.onDuplicate` (if any),
   * and reconciles what it returned with the duplicates.
   *
   * @returns next elements, and the duplicates that weren't vetoed
   */
  runOnDuplicate = (
    duplication: Duplication,
    nextElements: ExcalidrawElement[],
    /** excludes the duplicated elements */
    prevElements: readonly ExcalidrawElement[],
  ) => {
    return reconcileDuplicatedElements(
      this.app.props.onDuplicate?.(nextElements, prevElements, {
        duplicateElements: duplication.duplicateElementsMap,
        originalElements: duplication.origElementsMap,
        origIdToDuplicateId: duplication.origIdToDuplicateId,
        duplicateIdToOrigId: duplication.duplicateIdToOrigId,
      }),
      nextElements,
      duplication.duplicatedElements,
    );
  };

  /**
   * Runs `update` once what's pending is committed, capturing what it changes
   * (if it returns `true`) as a separate undo step.
   */
  private afterCommit(update: () => boolean) {
    // (setState callbacks run after componentDidUpdate, which commits)
    this.app.setState({}, () => {
      if (update()) {
        this.app.store.scheduleCapture();
      }
    });
  }

  /**
   * Advances the list markers of the duplicated texts (`1.` -> `2.`) once
   * the duplication is committed, as a separate undo step, so that undo
   * reverts the markers first.
   */
  advanceListMarkers = (duplicatedElements: readonly ExcalidrawElement[]) => {
    this.afterCommit(() => {
      const duplicates = duplicatedElements.flatMap(
        (element) => this.app.scene.getNonDeletedElement(element.id) ?? [],
      );

      return (
        advanceDuplicatedListMarkers(duplicates, this.app.scene).length > 0
      );
    });
  };

  /**
   * The text whose editing an alt-press on it ended, while the press is
   * handed over to the canvas (see `handOverTextEditorPress()`).
   */
  handedOverTextId: ExcalidrawTextElement["id"] | null = null;

  /**
   * An alt-press on the text being edited, once it ended the editing, is
   * handed over to the canvas, for the text to be alt-dragged (duplicated) as
   * on the canvas — its duplicate is then edited on drop.
   */
  handOverTextEditorPress = (
    event: PointerEvent,
    textElementId: ExcalidrawTextElement["id"],
  ) => {
    this.handedOverTextId = textElementId;
    try {
      this.app.interactiveCanvas?.dispatchEvent(
        new this.app.ownerWindow.PointerEvent(event.type, event),
      );
    } finally {
      this.handedOverTextId = null;
    }
  };

  /**
   * The pointer down a handed-over press is replayed as (see
   * `handOverTextEditorPress()`) moves what was edited — the text, or its
   * container — and nothing beneath the editor, which reaches past the text:
   * no resize handle, nor an arrow's point, midpoint or label.
   *
   * @returns `false` if the pointer down isn't a handed-over press
   */
  hitEditedElement = (pointerDownState: PointerDownState): boolean => {
    const { editedTextId } = pointerDownState.hit;
    const elementsMap = this.app.scene.getNonDeletedElementsMap();
    const text = editedTextId && this.app.scene.getElement(editedTextId);
    // (the text is gone if emptied)
    const element =
      text && isTextElement(text)
        ? elementsMap.get(text.containerId ?? text.id)
        : null;
    if (!element) {
      return false;
    }

    pointerDownState.hit.element = element;
    pointerDownState.hit.allHitElements = [element];

    // a fresh arrow editor, as the last press' (on a point, the midpoint or
    // the label) would drive the drag
    if (this.app.state.selectedLinearElement) {
      this.app.setState({
        selectedLinearElement: isLinearElement(element)
          ? new LinearElementEditor(element, elementsMap)
          : null,
      });
    }

    return true;
  };

  /**
   * On alt-drag drop: the list markers advanced along with the drag go back,
   * for the drag to be committed as is, and forth again once it is, as
   * a separate undo step (before the browser gets to paint either).
   *
   * A duplicate is then edited (once the drop is committed): a single list
   * item with text after its marker, with that text selected (`1. |foo|`),
   * as it's likely to differ from the original's — or else the duplicate of
   * the text the drag ended the editing of, with all of it selected.
   */
  commitDraggedDuplicates = (
    { hit }: PointerDownState,
    {
      editText,
    }: {
      /** `false` if the drag didn't end with a genuine pointerup */
      editText: boolean;
    },
  ) => {
    const advances = hit.advancedListMarkers;
    const [advance] = advances;
    const listItem =
      advances.length === 1 &&
      advance.contentStart < advance.nextOriginalText.length
        ? advance
        : null;
    const textToEditId = !editText
      ? null
      : listItem
      ? listItem.elementId
      : hit.editedTextId;

    const editTextOnceCommitted = () => {
      if (textToEditId) {
        this.afterCommit(() => {
          this.editDuplicatedText(textToEditId, listItem);
          return false;
        });
      }
    };

    if (!advances.length) {
      editTextOnceCommitted();
      return;
    }

    applyListMarkerAdvances(advances, "prev", this.app.scene);

    this.afterCommit(() => {
      applyListMarkerAdvances(advances, "next", this.app.scene);
      editTextOnceCommitted();
      return true;
    });
  };

  private editDuplicatedText(
    elementId: ExcalidrawTextElement["id"],
    /** to select the item's text only */
    listItem: ListMarkerAdvance | null,
  ) {
    const element = this.app.scene.getNonDeletedElement(elementId);
    if (
      !element ||
      !isTextElement(element) ||
      (listItem && element.originalText !== listItem.nextOriginalText) ||
      // another interaction has started
      this.dependencies.getPointerCount() > 0
    ) {
      return;
    }

    this.app.text.startTextEditing({
      sceneX: element.x,
      sceneY: element.y,
      insertAtParentCenter: false,
      textElement: element,
      initialSelection: {
        start: listItem?.contentStart ?? 0,
        end: element.originalText.length,
      },
    });
  }

  /**
   * Duplicates elements so that they end up centered at the scene coords
   * (and in the frame at that point, if any). Doesn't update the scene.
   *
   * @returns `null` if the host vetoed the duplication
   */
  duplicateAtSceneCoords = (
    elements: readonly ExcalidrawElement[],
    { x, y }: { x: number; y: number },
    opts?: {
      retainSeed?: boolean;
      preserveFrameChildrenOrder?: boolean;
    },
  ) => {
    const [minX, minY, maxX, maxY] = getCommonBounds(elements);

    const elementsCenterX = distance(minX, maxX) / 2;
    const elementsCenterY = distance(minY, maxY) / 2;

    const dx = x - elementsCenterX;
    const dy = y - elementsCenterY;

    const [gridX, gridY] = getGridPoint(
      dx,
      dy,
      this.app.getEffectiveGridSize(),
    );

    const duplication = duplicateElements({
      type: "everything",
      elements: elements.map((element) => {
        return newElementWith(element, {
          x: element.x + gridX - minX,
          y: element.y + gridY - minY,
        });
      }),
      randomizeSeed: !opts?.retainSeed,
      preserveFrameChildrenOrder: opts?.preserveFrameChildrenOrder,
    });
    let { duplicatedElements } = duplication;

    const prevElements = this.app.scene.getElementsIncludingDeleted();
    let nextElements: ExcalidrawElement[] = [
      ...prevElements,
      ...duplicatedElements,
    ];

    syncMovedIndices(nextElements, arrayToMap(duplicatedElements));

    // resolved ahead of `onDuplicate` so that the host sees the duplicates
    // the way they end up in the scene
    const topLayerFrame = this.app.getTopLayerFrameAtSceneCoords({ x, y });

    if (topLayerFrame) {
      const eligibleElements = filterElementsEligibleAsFrameChildren(
        duplicatedElements,
        topLayerFrame,
      );
      nextElements = addElementsToFrame(
        nextElements,
        eligibleElements,
        topLayerFrame,
      );
    }

    if (this.app.props.onDuplicate) {
      ({ elements: nextElements, duplicatedElements } = this.runOnDuplicate(
        duplication,
        nextElements,
        prevElements,
      ));

      // host vetoed the duplication
      if (!duplicatedElements.length) {
        return null;
      }

      // host may have reordered the elements
      syncMovedIndices(nextElements, arrayToMap(duplicatedElements));
    }

    return { nextElements, duplicatedElements };
  };

  /**
   * Duplicates the selection being dragged: the originals go back to where
   * the drag started, and the drag continues with the duplicates.
   *
   * If the host vetoes the duplication, the originals keep being dragged.
   */
  duplicateDraggedSelection = (
    pointerDownState: PointerDownState,
    event: PointerEvent,
  ) => {
    // Move the currently selected elements to the top of the z index stack, and
    // put the duplicates where the selected elements used to be.
    // (the origin point where the dragging started)

    pointerDownState.hit.hasBeenDuplicated = true;

    const elements = this.app.scene.getElementsIncludingDeleted();
    const hitElement = pointerDownState.hit.element;
    const selectedElements = this.app.scene.getSelectedElements({
      selectedElementIds: this.app.state.selectedElementIds,
      includeBoundTextElement: true,
      includeElementsInFrames: true,
    });
    if (
      hitElement &&
      // hit element may not end up being selected
      // if we're alt-dragging a common bounding box
      // over the hit element
      pointerDownState.hit.wasAddedToSelection &&
      !selectedElements.find((el) => el.id === hitElement.id)
    ) {
      selectedElements.push(hitElement);
    }

    const idsOfElementsToDuplicate = new Map(
      selectedElements.map((el) => [el.id, el]),
    );

    const duplication = duplicateElements({
      type: "in-place",
      elements,
      appState: this.app.state,
      randomizeSeed: true,
      idsOfElementsToDuplicate,
      overrides: ({ duplicateElement, origElement }) => {
        return {
          // reset to the original element's frameId (unless we've
          // duplicated alongside a frame in which case we need to
          // keep the duplicate frame's id) so that the element
          // frame membership is refreshed on pointerup
          // NOTE this is a hacky solution and should be done
          // differently
          frameId: duplicateElement.frameId ?? origElement.frameId,
          seed: randomInteger(),
        };
      },
    });
    const { origElementsMap, origIdToDuplicateId } = duplication;

    const mappedClonedElements = duplication.elementsWithDuplicates.map(
      (el) => {
        if (idsOfElementsToDuplicate.has(el.id)) {
          const origEl = pointerDownState.originalElements.get(el.id);

          if (origEl) {
            const resetElement = newElementWith(el, {
              x: origEl.x,
              y: origEl.y,
            });
            // so that the host gets the originals as they are in the
            // next elements
            if (origElementsMap.has(el.id)) {
              origElementsMap.set(el.id, resetElement);
            }
            return resetElement;
          }
        }
        return el;
      },
    );

    const { elements: nextElements, duplicatedElements } = this.runOnDuplicate(
      duplication,
      mappedClonedElements,
      elements,
    );

    // host vetoed the duplication, so we keep dragging the originals
    if (!duplicatedElements.length) {
      pointerDownState.hit.editedTextId = null;
      return;
    }

    // (originals whose duplicates were vetoed are left behind)
    const duplicateElementsMap = arrayToMap(duplicatedElements);

    const elementsWithIndices = syncMovedIndices(
      nextElements,
      duplicateElementsMap,
    );

    // we need to update synchronously so as to keep pointerDownState,
    // appState, and scene elements in sync
    flushSync(() => {
      // swap hit element with the duplicated one
      if (pointerDownState.hit.element) {
        const cloneId = origIdToDuplicateId.get(
          pointerDownState.hit.element.id,
        );
        const clonedElement = cloneId && duplicateElementsMap.get(cloneId);
        pointerDownState.hit.element = clonedElement || null;
      }
      // swap the edited text with its duplicate
      if (pointerDownState.hit.editedTextId) {
        const cloneId = origIdToDuplicateId.get(
          pointerDownState.hit.editedTextId,
        );
        pointerDownState.hit.editedTextId =
          (cloneId && duplicateElementsMap.get(cloneId)?.id) || null;
      }
      // swap hit elements with the duplicated ones
      pointerDownState.hit.allHitElements =
        pointerDownState.hit.allHitElements.reduce(
          (acc: typeof pointerDownState.hit.allHitElements, origHitElement) => {
            const cloneId = origIdToDuplicateId.get(origHitElement.id);
            const clonedElement = cloneId && duplicateElementsMap.get(cloneId);
            if (clonedElement) {
              acc.push(clonedElement);
            }

            return acc;
          },
          [],
        );

      // update drag origin to the position at which we started
      // the duplication so that the drag offset is correct
      pointerDownState.drag.origin = viewportCoordsToSceneCoords(
        event,
        this.app.state,
      );

      // switch selected elements to the duplicated ones
      this.app.setState((prevState) => ({
        ...getSelectionStateForElements(
          duplicatedElements,
          this.app.scene.getNonDeletedElements(),
          prevState,
        ),
      }));

      this.app.scene.replaceAllElements(elementsWithIndices);

      // visible from the start of the drag, captured on drop (see
      // `commitDraggedDuplicates()`)
      pointerDownState.hit.advancedListMarkers = advanceDuplicatedListMarkers(
        duplicatedElements,
        this.app.scene,
      );

      // (after advancing the list markers, which may resize the duplicates)
      duplicatedElements.forEach((element) => {
        pointerDownState.originalElements.set(
          element.id,
          deepCopyElement(element),
        );
      });

      selectedElements.forEach((element) => {
        if (
          isBindableElement(element) &&
          element.boundElements?.some((other) => other.type === "arrow")
        ) {
          updateBoundElements(element, this.app.scene);
        }
      });

      this.app.maybeCacheVisibleGaps(event, selectedElements, true);
      this.app.maybeCacheReferenceSnapPoints(event, selectedElements, true);
    });
  };
}

import { isArrowKey, KEYS } from "@excalidraw/common";

import {
  makeNextSelectedElementIds,
  CaptureUpdateAction,
  FlowChartCreator,
  FlowChartNavigator,
  getSelectedElements,
  isFlowchartNodeElement,
  type LinkDirection,
} from "@excalidraw/element";

import type {
  ExcalidrawElement,
  NonDeletedExcalidrawElement,
} from "@excalidraw/element/types";

import type React from "react";
import type App from "./App";
import type { PendingExcalidrawElements } from "../types";

type FlowchartOperation =
  | { type: "none" }
  | { type: "canceled" }
  | { type: "creating"; pending: PendingExcalidrawElements }
  | { type: "navigating"; nodeId: ExcalidrawElement["id"] | null }
  | { type: "committed"; nodes: PendingExcalidrawElements }
  | { type: "navigationEnded" };

/**
 * Captures the App state management for the flowchart functionality.
 */
export class AppFlowchart {
  private creator = new FlowChartCreator();
  private navigator = new FlowChartNavigator();

  constructor(private app: App) {}

  get pendingNodes() {
    return this.creator.pendingNodes;
  }

  get isCreatingChart() {
    return this.creator.isCreatingChart;
  }

  /** ends any in-progress flowchart creation/navigation session */
  clear = () => {
    this.creator.clear();
    this.navigator.clear();
  };

  handleKeyEvent = (event: React.KeyboardEvent | KeyboardEvent): boolean => {
    const operation = this.resolveKeyboardEventToOperation(event);

    switch (operation.type) {
      case "none":
        return false;
      case "canceled":
        this.app.triggerRender(true);
        return true;
      case "creating":
        event.preventDefault();
        if (operation.pending.length) {
          this.app.revealIfHidden(operation.pending);
        }
        return true;
      case "navigating": {
        event.preventDefault();
        const node =
          operation.nodeId &&
          this.app.scene.getNonDeletedElementsMap().get(operation.nodeId);
        if (node) {
          this.selectAndReveal(node);
        }
        return true;
      }
      case "committed": {
        if (operation.nodes.length) {
          this.app.insertNewElements(operation.nodes);
        }

        const firstNode = operation.nodes[0];
        if (firstNode) {
          this.selectAndReveal(firstNode);
        }

        this.captureUpdate();
        return true;
      }
      case "navigationEnded":
        this.captureUpdate();
        return true;
    }
  };

  private resolveKeyboardEventToOperation(
    event: React.KeyboardEvent | KeyboardEvent,
  ): FlowchartOperation {
    const { creator, navigator, app } = this;

    if (event.type === "keydown") {
      if (event.key === KEYS.ESCAPE && creator.isCreatingChart) {
        creator.clear();
        return { type: "canceled" };
      }

      if (!isArrowKey(event.key)) {
        return { type: "none" };
      }

      if (event[KEYS.CTRL_OR_CMD] && !event.shiftKey) {
        const selectedElements = getSelectedElements(
          app.scene.getNonDeletedElementsMap(),
          app.state,
        );

        if (
          selectedElements.length === 1 &&
          isFlowchartNodeElement(selectedElements[0])
        ) {
          creator.createNodes(
            selectedElements[0],
            app.state,
            AppFlowchart.getLinkDirectionFromKey(event.key),
            app.scene,
          );
        }

        return { type: "creating", pending: creator.pendingNodes ?? [] };
      }

      if (event.altKey) {
        const elementsMap = app.scene.getNonDeletedElementsMap();
        const selectedElements = getSelectedElements(elementsMap, app.state);

        if (selectedElements.length === 1) {
          return {
            type: "navigating",
            nodeId: navigator.exploreByDirection(
              selectedElements[0],
              elementsMap,
              AppFlowchart.getLinkDirectionFromKey(event.key),
            ),
          };
        }
      }

      return { type: "none" };
    }

    // keyup: releasing a modifier finalizes the workflow it was driving;
    // both can finalize on the same event
    const navigationEnded = !event.altKey && navigator.isExploring;
    if (navigationEnded) {
      navigator.clear();
    }

    if (!event[KEYS.CTRL_OR_CMD] && creator.isCreatingChart) {
      const nodes = creator.pendingNodes ?? [];
      creator.clear();
      return { type: "committed", nodes };
    }

    return navigationEnded ? { type: "navigationEnded" } : { type: "none" };
  }

  private selectAndReveal(node: NonDeletedExcalidrawElement) {
    this.app.setState((prevState) => ({
      selectedElementIds: makeNextSelectedElementIds(
        { [node.id]: true },
        prevState,
      ),
    }));
    this.app.revealIfHidden([node]);
  }

  private captureUpdate() {
    this.app.syncActionResult({
      captureUpdate: CaptureUpdateAction.IMMEDIATELY,
    });
  }

  private static getLinkDirectionFromKey(key: string): LinkDirection {
    switch (key) {
      case KEYS.ARROW_UP:
        return "up";
      case KEYS.ARROW_DOWN:
        return "down";
      case KEYS.ARROW_RIGHT:
        return "right";
      case KEYS.ARROW_LEFT:
        return "left";
      default:
        return "right";
    }
  }
}

import { useEffect, useState } from "react";

import { Emitter, KEYS } from "@excalidraw/common";

export type HeldModifiers = Readonly<{
  alt: boolean;
  shift: boolean;
  /** Ctrl, or Cmd on macOS */
  ctrlOrCmd: boolean;
}>;

const NONE_HELD: HeldModifiers = {
  alt: false,
  shift: false,
  ctrlOrCmd: false,
};

const pick = (held: HeldModifiers, modifier?: keyof HeldModifiers) =>
  modifier ? held[modifier] : held;

/**
 * The modifier keys held over the editor, synced from the flags of its
 * keyboard and pointer events. Kept out of appState so that pressing one
 * re-renders only its subscribers (e.g. the hint).
 */
export class AppModifiers {
  private held = NONE_HELD;
  /** fires with a new snapshot whenever a modifier is pressed or released */
  readonly onChange = new Emitter<[held: HeldModifiers]>();

  get = (): HeldModifiers => this.held;

  /* eslint-disable react-hooks/rules-of-hooks -- called from function
     components; the lint takes any class method for a class component */
  /**
   * A hook re-rendering on the held modifiers: all of them, or with
   * `modifier`, only on that one being pressed or released.
   */
  useHeld(): HeldModifiers;
  useHeld(modifier: keyof HeldModifiers): boolean;
  useHeld(modifier?: keyof HeldModifiers) {
    const [held, setHeld] = useState(() => pick(this.held, modifier));
    useEffect(() => {
      // (setting a boolean that didn't change doesn't re-render)
      const update = () => setHeld(pick(this.held, modifier));
      // catches a change between the render and subscribing
      update();
      return this.onChange.on(update);
    }, [modifier]);
    return held;
  }
  /* eslint-enable react-hooks/rules-of-hooks */

  sync = (event: {
    altKey: boolean;
    shiftKey: boolean;
    ctrlKey: boolean;
    metaKey: boolean;
  }) => {
    this.set({
      alt: event.altKey,
      shift: event.shiftKey,
      ctrlOrCmd: event[KEYS.CTRL_OR_CMD],
    });
  };

  /** releases them all — e.g. on blur, as Alt+Tab never delivers the keyup */
  reset = () => {
    this.set(NONE_HELD);
  };

  private set(held: HeldModifiers) {
    if (
      held.alt !== this.held.alt ||
      held.shift !== this.held.shift ||
      held.ctrlOrCmd !== this.held.ctrlOrCmd
    ) {
      this.held = held;
      this.onChange.trigger(held);
    }
  }
}

import { CURSOR_TYPE, EVENT, POINTER_BUTTON } from "@excalidraw/common";

import { isHandToolActive } from "../appState";
import { withBatchedUpdates, withBatchedUpdatesThrottled } from "../reactUtils";

import type React from "react";

import type App from "./App";

const SECONDARY_BUTTON_PAN_THRESHOLD = 5; // px

/**
 * The drag-pan: a pointer drag that moves the canvas — the wheel or the
 * secondary button, the main button while space is held or the hand tool
 * is active, or any button in view mode. One session at a time, owning its
 * window listeners and teardown; wheel input is gated on it (see
 * `AppWheel`).
 *
 * A secondary-button session is a pan only once the pointer travels past
 * the drag threshold; released before that, it is a right-click. The
 * platform's `contextmenu` event opens the menu for a right-click where it
 * follows the release (Windows), as it always has; where it comes with the
 * press (macOS, Linux) it is swallowed — a drag cannot be told from a
 * click yet — and the session opens the menu on release instead.
 */
export class AppPan {
  /** space held down turns a main-button drag into a pan */
  private spaceHeld = false;
  private active = false;
  /** the secondary-button session, while one is active */
  private secondary: { engaged: boolean; nativeMenuSeen: boolean } | null =
    null;
  /** the platform fires `contextmenu` on mouseup (Windows) or on mousedown
   * (macOS, Linux); the one belonging to a secondary-button session is not a
   * new click, whichever side of the session it lands on */
  private suppressNextContextMenu = false;
  /** applies the pointer move the session is holding back for its next
   * frame, if any */
  private pendingMoveFlush: (() => void) | null = null;
  private teardown: (() => void) | null = null;

  constructor(
    private app: App,
    private dependencies: {
      /** pointers currently down (a two-finger gesture is not a pan) */
      getPointerCount: () => number;
      /** a scrollbar being dragged (App's own drag, not a pan session) */
      isDraggingScrollBar: () => boolean;
    },
  ) {}

  isActive = () => this.active;

  isSpaceHeld = () => this.spaceHeld;

  setSpaceHeld = (held: boolean) => {
    this.spaceHeld = held;
  };

  /**
   * Whether the pointer is navigating the viewport rather than acting on the
   * scene — space held to pan, a pan in progress, a scrollbar drag, or the
   * hand tool. Hover and cursor then belong to the navigation.
   */
  isNavigating = () =>
    this.spaceHeld ||
    this.active ||
    this.dependencies.isDraggingScrollBar() ||
    isHandToolActive(this.app.state);

  /** applies the pointer move still waiting for its frame, if any */
  flushMove = () => {
    this.pendingMoveFlush?.();
  };

  /** ends the active session, if any — pointerup may never arrive (the user
   * tabs away, a new pointerdown lands first) */
  end = () => {
    this.teardown?.();
  };

  /**
   * Whether a `contextmenu` event belongs to a secondary-button session and
   * must not open the menu: it came with the press (the session decides on
   * release), or it follows a release that turned out to be a drag.
   */
  consumesContextMenuEvent = () => {
    if (this.secondary) {
      this.secondary.nativeMenuSeen = true;
      return true;
    }
    if (this.suppressNextContextMenu) {
      this.suppressNextContextMenu = false;
      return true;
    }
    return false;
  };

  /** starts a session for the pointerdown if it qualifies; returns whether
   * it did */
  start = (event: React.PointerEvent<HTMLElement> | MouseEvent): boolean => {
    const { app } = this;
    // a new press supersedes whatever the previous session left pending
    this.suppressNextContextMenu = false;
    const isSecondary = event.button === POINTER_BUTTON.SECONDARY;
    if (
      !(
        this.dependencies.getPointerCount() <= 1 &&
        (((event.button === POINTER_BUTTON.WHEEL ||
          isSecondary ||
          (event.button === POINTER_BUTTON.MAIN && this.spaceHeld) ||
          isHandToolActive(app.state)) &&
          // reachable while non-interactive when the active tool is allowed
          // via `interaction.enabled.tools` — panning must remain gated on
          // `navigation` then
          (app.isInteractionEnabled() || app.isNavigationEnabled())) ||
          (app.state.viewModeEnabled && !app.isActiveToolPointerCapturing()))
      )
    ) {
      return false;
    }
    this.active = true;
    this.secondary = isSecondary
      ? { engaged: false, nativeMenuSeen: false }
      : null;

    // due to event.preventDefault below, container wouldn't get focus
    // automatically
    app.focusContainer();

    // preventing defualt while text editing messes with cursor/focus
    if (!app.state.editingTextElement) {
      // necessary to prevent browser from scrolling the page if excalidraw
      // not full-page #4489
      //
      // as such, the above is broken when panning canvas while in wysiwyg
      event.preventDefault();
    }

    let nextPastePrevented = false;
    const isLinux = /Linux/.test(app.ownerWindow.navigator.platform);

    if (!this.secondary) {
      app.cursor.set(CURSOR_TYPE.GRABBING);
    }
    const { clientX: startX, clientY: startY } = event;
    let { clientX: lastX, clientY: lastY } = event;
    const onPointerMove = withBatchedUpdatesThrottled((event: PointerEvent) => {
      if (this.secondary && !this.secondary.engaged) {
        // a right-click until the pointer travels far enough for a drag
        if (
          Math.hypot(event.clientX - startX, event.clientY - startY) <=
          SECONDARY_BUTTON_PAN_THRESHOLD
        ) {
          return;
        }
        this.secondary.engaged = true;
        app.cursor.set(CURSOR_TYPE.GRABBING);
        // pans from here on; the threshold distance is not caught up
        lastX = event.clientX;
        lastY = event.clientY;
        return;
      }

      const deltaX = lastX - event.clientX;
      const deltaY = lastY - event.clientY;
      lastX = event.clientX;
      lastY = event.clientY;

      /*
       * Prevent paste event if we move while middle clicking on Linux.
       * See issue #1383.
       */
      if (
        isLinux &&
        !nextPastePrevented &&
        (Math.abs(deltaX) > 1 || Math.abs(deltaY) > 1)
      ) {
        nextPastePrevented = true;

        /* Prevent the next paste event */
        const preventNextPaste = (event: ClipboardEvent) => {
          app.ownerDocument.body.removeEventListener(
            EVENT.PASTE,
            preventNextPaste,
          );
          event.stopPropagation();
        };

        /*
         * Reenable next paste in case of disabled middle click paste for
         * any reason:
         * - right click paste
         * - empty clipboard
         */
        const enableNextPaste = () => {
          setTimeout(() => {
            app.ownerDocument.body.removeEventListener(
              EVENT.PASTE,
              preventNextPaste,
            );
            app.ownerWindow.removeEventListener(
              EVENT.POINTER_UP,
              enableNextPaste,
            );
          }, 100);
        };

        app.ownerDocument.body.addEventListener(EVENT.PASTE, preventNextPaste);
        app.ownerWindow.addEventListener(EVENT.POINTER_UP, enableNextPaste);
      }

      // an updater, not a snapshot of `app.state`: a wheel zoom queued in
      // the same React flush would otherwise be overwritten by a pan
      // computed from the pre-zoom state
      app.viewport.translate((state) => ({
        scrollX: state.scrollX - deltaX / state.zoom.value,
        scrollY: state.scrollY - deltaY / state.zoom.value,
      }));
    });
    this.pendingMoveFlush = onPointerMove.flush;
    const teardown = withBatchedUpdates(
      (upEvent?: PointerEvent | FocusEvent) => {
        const { secondary } = this;
        this.teardown = null;
        this.pendingMoveFlush = null;
        this.active = false;
        this.secondary = null;
        if (secondary?.engaged && !secondary.nativeMenuSeen) {
          // a drag: the platform's `contextmenu` still to come is no click
          this.suppressNextContextMenu = true;
        }
        if (!this.spaceHeld) {
          app.cursor.reset();
        }
        app.setState(
          {
            cursorButton: "up",
          },
          // Wait for the trailing pan move to commit before converting the
          // pointer to scene coordinates or starting the snap-back.
          () => {
            // Missing-pointerup cleanup can run during a new press. Don't
            // overwrite the newer button state with this pan's release.
            if (app.state.cursorButton === "up") {
              const pointer =
                upEvent && "clientX" in upEvent
                  ? upEvent
                  : { clientX: lastX, clientY: lastY };
              app.savePointer(pointer.clientX, pointer.clientY, "up");
            }
            app.viewport.releaseOverscroll();
          },
        );
        app.ownerWindow.removeEventListener(EVENT.POINTER_MOVE, onPointerMove);
        app.ownerWindow.removeEventListener(EVENT.POINTER_UP, teardown);
        app.ownerWindow.removeEventListener(EVENT.BLUR, teardown);
        onPointerMove.flush();

        // released without a drag: a right-click. Where the platform's
        // `contextmenu` came with the press it was swallowed, so the menu
        // opens here, at the release point; where it is still to come it
        // opens the menu itself, as it always has
        if (
          secondary &&
          !secondary.engaged &&
          secondary.nativeMenuSeen &&
          upEvent &&
          "clientX" in upEvent
        ) {
          app.openContextMenu({
            clientX: upEvent.clientX,
            clientY: upEvent.clientY,
            button: upEvent.button,
            pointerType: upEvent.pointerType,
          });
        }
      },
    );
    this.teardown = teardown;
    app.ownerWindow.addEventListener(EVENT.BLUR, teardown);
    app.ownerWindow.addEventListener(EVENT.POINTER_MOVE, onPointerMove, {
      passive: true,
    });
    app.ownerWindow.addEventListener(EVENT.POINTER_UP, teardown);
    return true;
  };
}

import {
  arrayToMap,
  DEFAULT_COLLISION_THRESHOLD,
  DEFAULT_TRANSFORM_HANDLE_SPACING,
  isReadonlyArray,
} from "@excalidraw/common";
import {
  getCommonBounds,
  getSelectedElements,
  getSelectedGroupForElement,
  isBoundToContainer,
  isEmbeddableElement,
  isFrameLikeElement,
  isLinearElement,
  LinearElementEditor,
  makeNextSelectedElementIds,
} from "@excalidraw/element";

import type {
  ExcalidrawElement,
  GroupId,
  NonDeletedExcalidrawElement,
} from "@excalidraw/element/types";

import type { Mutable } from "@excalidraw/common/utility-types";
import type { CaptureUpdateActionType } from "@excalidraw/element";

import type {
  AppClassProperties,
  AppState,
  InteractiveCanvasAppState,
} from "../types";
import type App from "./App";

export const selectGroupsForSelectedElements = (function () {
  type SelectGroupsReturnType = Pick<
    InteractiveCanvasAppState,
    "selectedGroupIds" | "editingGroupId" | "selectedElementIds"
  >;

  let lastSelectedElements: readonly NonDeletedExcalidrawElement[] | null =
    null;
  let lastElements: readonly NonDeletedExcalidrawElement[] | null = null;
  let lastReturnValue: SelectGroupsReturnType | null = null;

  const _selectGroups = (
    selectedElements: readonly NonDeletedExcalidrawElement[],
    elements: readonly NonDeletedExcalidrawElement[],
    appState: Pick<AppState, "selectedElementIds" | "editingGroupId">,
    prevAppState: InteractiveCanvasAppState,
  ): SelectGroupsReturnType => {
    if (
      lastReturnValue !== undefined &&
      elements === lastElements &&
      selectedElements === lastSelectedElements &&
      appState.editingGroupId === lastReturnValue?.editingGroupId
    ) {
      return lastReturnValue;
    }

    const selectedGroupIds: Record<GroupId, boolean> = {};
    // Gather all the groups withing selected elements
    for (const selectedElement of selectedElements) {
      let groupIds = selectedElement.groupIds;
      if (appState.editingGroupId) {
        // handle the case where a group is nested within a group
        const indexOfEditingGroup = groupIds.indexOf(appState.editingGroupId);
        if (indexOfEditingGroup > -1) {
          groupIds = groupIds.slice(0, indexOfEditingGroup);
        }
      }
      if (groupIds.length > 0) {
        const lastSelectedGroup = groupIds[groupIds.length - 1];
        selectedGroupIds[lastSelectedGroup] = true;
      }
    }

    // Gather all the elements within selected groups
    const groupElementsIndex: Record<GroupId, string[]> = {};
    const selectedElementIdsInGroups = elements.reduce(
      (acc: Record<string, true>, element) => {
        if (element.isDeleted) {
          return acc;
        }

        const groupId = element.groupIds.find((id) => selectedGroupIds[id]);

        if (groupId) {
          acc[element.id] = true;

          // Populate the index
          if (!Array.isArray(groupElementsIndex[groupId])) {
            groupElementsIndex[groupId] = [element.id];
          } else {
            groupElementsIndex[groupId].push(element.id);
          }
        }
        return acc;
      },
      {},
    );

    for (const groupId of Object.keys(groupElementsIndex)) {
      // If there is one element in the group, and the group is selected or it's being edited, it's not a group
      if (groupElementsIndex[groupId].length < 2) {
        if (selectedGroupIds[groupId]) {
          selectedGroupIds[groupId] = false;
        }
      }
    }

    lastElements = elements;
    lastSelectedElements = selectedElements;

    lastReturnValue = {
      editingGroupId: appState.editingGroupId,
      selectedGroupIds,
      selectedElementIds: makeNextSelectedElementIds(
        {
          ...appState.selectedElementIds,
          ...selectedElementIdsInGroups,
        },
        prevAppState,
      ),
    };

    return lastReturnValue;
  };

  /**
   * When you select an element, you often want to actually select the whole group it's in, unless
   * you're currently editing that group.
   */
  const selectGroupsForSelectedElements = (
    appState: Pick<AppState, "selectedElementIds" | "editingGroupId">,
    elements: readonly NonDeletedExcalidrawElement[],
    prevAppState: InteractiveCanvasAppState,
    /**
     * supply null in cases where you don't have access to App instance and
     * you don't care about optimizing selectElements retrieval
     */
    app: AppClassProperties | null,
  ): Mutable<
    Pick<
      InteractiveCanvasAppState,
      "selectedGroupIds" | "editingGroupId" | "selectedElementIds"
    >
  > => {
    const selectedElements = app
      ? app.scene.getSelectedElements({
          selectedElementIds: appState.selectedElementIds,
          // supplying elements explicitly in case we're passed non-state elements
          elements,
        })
      : getSelectedElements(elements, appState);

    if (!selectedElements.length) {
      return {
        selectedGroupIds: {},
        editingGroupId: null,
        selectedElementIds: makeNextSelectedElementIds(
          appState.selectedElementIds,
          prevAppState,
        ),
      };
    }

    return _selectGroups(selectedElements, elements, appState, prevAppState);
  };

  selectGroupsForSelectedElements.clearCache = () => {
    lastElements = null;
    lastSelectedElements = null;
    lastReturnValue = null;
  };

  return selectGroupsForSelectedElements;
})();

/**
 * The line editor of a lone selected line or arrow (with its labels) —
 * the current one if it's already that element's.
 */
const getLinearElementEditor = (
  targetElements: readonly NonDeletedExcalidrawElement[],
  allElements: readonly NonDeletedExcalidrawElement[],
  appState: Pick<AppState, "selectedLinearElement">,
) => {
  const linears = targetElements.filter(isLinearElement);
  if (linears.length === 1) {
    const linear = linears[0];
    const boundElements = linear.boundElements?.map((def) => def.id) ?? [];
    const onlySingleLinearSelected = targetElements.every(
      (el) => el.id === linear.id || boundElements.includes(el.id),
    );

    if (onlySingleLinearSelected) {
      // keep the current one, e.g. not to reset its `hoverPointIndex`
      if (appState.selectedLinearElement?.elementId === linear.id) {
        return appState.selectedLinearElement;
      }
      return new LinearElementEditor(linear, arrayToMap(allElements));
    }
  }

  return null;
};

/**
 * The selection state with the line editor of what it selects: of a lone
 * selected line or arrow, once groups are expanded.
 */
const withLinearElementEditor = <
  T extends Pick<AppState, "selectedElementIds">,
>(
  selectionState: T,
  allElements: readonly NonDeletedExcalidrawElement[],
  appState: Pick<AppState, "selectedLinearElement">,
) => ({
  ...selectionState,
  selectedLinearElement: getLinearElementEditor(
    getSelectedElements(allElements, selectionState),
    allElements,
    appState,
  ),
});

/**
 * The frames that selecting the elements selects through their groups (those
 * selected along with them, within the edited group) — of the elements
 * neither frames nor in frames.
 */
const getFramesSelectedViaGroups = (
  elements: readonly ExcalidrawElement[],
  allElements: readonly NonDeletedExcalidrawElement[],
  editingGroupId: AppState["editingGroupId"],
) => {
  const groupIds = new Set<GroupId>();
  for (const element of elements) {
    if (isFrameLikeElement(element) || element.frameId) {
      continue;
    }
    const editingGroupIndex = editingGroupId
      ? element.groupIds.indexOf(editingGroupId)
      : -1;
    const elementGroupIds =
      editingGroupIndex > -1
        ? element.groupIds.slice(0, editingGroupIndex)
        : element.groupIds;
    if (elementGroupIds.length) {
      groupIds.add(elementGroupIds[elementGroupIds.length - 1]);
    }
  }

  const frameIds = new Set<ExcalidrawElement["id"]>();
  if (groupIds.size) {
    for (const element of allElements) {
      if (
        isFrameLikeElement(element) &&
        element.groupIds.some((groupId) => groupIds.has(groupId))
      ) {
        frameIds.add(element.id);
      }
    }
  }
  return frameIds;
};

/**
 * The selection of the given elements alone, with their groups (within the
 * edited group): a frame wins over its children, bound text is left to its
 * container, and a lone line or arrow gets its line editor.
 *
 * @param allElements the (non-deleted) elements the selection is in
 * @param deep select the elements themselves rather than their groups,
 *   editing their innermost group if they share it (and no group otherwise)
 *   — as Ctrl+click does
 */
export const getSelectionStateForElements = (
  targetElements: readonly NonDeletedExcalidrawElement[],
  allElements: readonly NonDeletedExcalidrawElement[],
  appState: AppState,
  deep = false,
) => {
  const elements = targetElements.filter(
    (element) => !isBoundToContainer(element),
  );

  let editingGroupId = appState.editingGroupId;
  if (deep) {
    const innermostGroupIds = new Set(
      elements.map((element) => element.groupIds[0] ?? null),
    );
    editingGroupId =
      innermostGroupIds.size === 1 ? [...innermostGroupIds][0] : null;
  }

  // frames win over their children: frames selected, or selected through
  // the groups (not when deep, selecting no groups)
  const selectedFrameIds = deep
    ? new Set<ExcalidrawElement["id"]>()
    : getFramesSelectedViaGroups(elements, allElements, editingGroupId);
  for (const element of elements) {
    if (isFrameLikeElement(element)) {
      selectedFrameIds.add(element.id);
    }
  }
  const selectedElementIds: Record<ExcalidrawElement["id"], true> = {};
  for (const element of elements) {
    if (!element.frameId || !selectedFrameIds.has(element.frameId)) {
      selectedElementIds[element.id] = true;
    }
  }

  return withLinearElementEditor(
    deep
      ? {
          selectedElementIds: makeNextSelectedElementIds(
            selectedElementIds,
            appState,
          ),
          selectedGroupIds: {},
          editingGroupId,
        }
      : selectGroupsForSelectedElements(
          { editingGroupId, selectedElementIds },
          allElements,
          appState,
          null,
        ),
    allElements,
    appState,
  );
};

/**
 * The selection with the given elements added, with their groups (within the
 * edited group) — and the line editor of a lone selected line or arrow.
 *
 * A frame and its children aren't selected at the same time: an added frame
 * deselects its children, an added child of a selected (or added) frame is
 * left out, and adding elements grouped with frames deselects those frames'
 * children (and leaves the added ones out). In the element link selector, the
 * added elements replace the selection (unless one's group is selected).
 *
 * @param allElements the (non-deleted) elements the selection is in
 */
export const getSelectionStateAddingElements = (
  targetElements: readonly NonDeletedExcalidrawElement[],
  allElements: readonly NonDeletedExcalidrawElement[],
  appState: AppState,
) => {
  const elements = targetElements.filter(
    (element) => !isBoundToContainer(element),
  );

  let nextSelectedElementIds: Record<ExcalidrawElement["id"], true> = {
    ...appState.selectedElementIds,
  };
  for (const element of elements) {
    nextSelectedElementIds[element.id] = true;
  }

  // frames win over their children: the added frames, and the frames selected
  // through the groups of the added elements
  const addedFrameIds = new Set<ExcalidrawElement["id"]>();
  for (const element of elements) {
    if (isFrameLikeElement(element)) {
      addedFrameIds.add(element.id);
    }
  }
  const framesInAddedGroups = getFramesSelectedViaGroups(
    elements,
    allElements,
    appState.editingGroupId,
  );
  for (const element of elements) {
    if (
      !isFrameLikeElement(element) &&
      element.frameId &&
      (nextSelectedElementIds[element.frameId] ||
        framesInAddedGroups.has(element.frameId))
    ) {
      delete nextSelectedElementIds[element.id];
    }
  }

  // deselect the previously selected children of those frames (and their
  // groups)
  if (addedFrameIds.size || framesInAddedGroups.size) {
    const deselectedGroupIds = new Set<string>();
    for (const element of allElements) {
      const { frameId } = element;
      if (!frameId || !appState.selectedElementIds[element.id]) {
        continue;
      }
      if (addedFrameIds.has(frameId)) {
        delete nextSelectedElementIds[element.id];
      }
      if (framesInAddedGroups.has(frameId)) {
        delete nextSelectedElementIds[element.id];
        for (const groupId of element.groupIds) {
          deselectedGroupIds.add(groupId);
        }
      }
    }
    if (deselectedGroupIds.size) {
      for (const element of allElements) {
        if (
          element.groupIds.some((groupId) => deselectedGroupIds.has(groupId))
        ) {
          delete nextSelectedElementIds[element.id];
        }
      }
    }
  }

  // in the element link selector, keep only one shape or group selected at a
  // time: the added elements replace the selection unless one's group is
  // selected
  if (
    appState.openDialog?.name === "elementLinkSelector" &&
    !elements.some((element) =>
      element.groupIds.some((groupId) => appState.selectedGroupIds[groupId]),
    )
  ) {
    nextSelectedElementIds = {};
    for (const element of elements) {
      nextSelectedElementIds[element.id] = true;
    }
  }

  return withLinearElementEditor(
    selectGroupsForSelectedElements(
      {
        editingGroupId: appState.editingGroupId,
        selectedElementIds: nextSelectedElementIds,
      },
      allElements,
      appState,
      null,
    ),
    allElements,
    appState,
  );
};

/**
 * The selection with the given elements removed — with the group they're
 * selected via (if any) — and a lone remaining line or arrow getting its
 * line editor.
 *
 * @param allElements the (non-deleted) elements the selection is in
 */
export const getSelectionStateRemovingElements = (
  targetElements: readonly NonDeletedExcalidrawElement[],
  allElements: readonly NonDeletedExcalidrawElement[],
  appState: AppState,
) => {
  const nextSelectedElementIds = { ...appState.selectedElementIds };
  const removedGroupIds = new Set<string>();
  for (const element of targetElements) {
    delete nextSelectedElementIds[element.id];
    const groupId = getSelectedGroupForElement(appState, element);
    if (groupId) {
      removedGroupIds.add(groupId);
    }
  }
  if (removedGroupIds.size) {
    for (const element of allElements) {
      if (element.groupIds.some((groupId) => removedGroupIds.has(groupId))) {
        delete nextSelectedElementIds[element.id];
      }
    }
  }

  return withLinearElementEditor(
    selectGroupsForSelectedElements(
      {
        editingGroupId: appState.editingGroupId,
        selectedElementIds: nextSelectedElementIds,
      },
      allElements,
      appState,
      null,
    ),
    allElements,
    appState,
  );
};

/** elements, or their ids — one or many */
export type ElementsOrIds =
  | ExcalidrawElement
  | ExcalidrawElement["id"]
  | readonly (ExcalidrawElement | ExcalidrawElement["id"])[];

type SelectionChangeOptions = {
  /**
   * how the change is recorded for undo (see `updateScene()`) — by default,
   * along with the next undoable change
   */
  captureUpdate?: CaptureUpdateActionType;
};

type AddOptions = SelectionChangeOptions & {
  /**
   * select locked elements too — e.g. for the context menu to offer unlocking
   * them
   */
  includeLocked?: boolean;
};

type SelectOptions = AddOptions & {
  /**
   * select the elements themselves rather than their groups, editing their
   * innermost group (if they share it) — as Ctrl+click does
   */
  deep?: boolean;
};

/**
 * The selection: selecting elements, adding them to or removing them from
 * the selection, and clearing it — keeping its rules: an element is selected
 * with its group (but within the edited group), a frame and its children
 * aren't selected at the same time, locked elements aren't selected, and a
 * lone line or arrow gets its line editor (see the `getSelectionState*()`
 * functions above).
 *
 * What hangs on the selection follows it: the link popup shows for a lone
 * selected element with a link (or an embeddable), an embed stays active only
 * while selected, cropping ends (unless the cropped image is selected again),
 * and selecting (or adding) anything but the edited text ends text editing,
 * submitting the text. The line editor ends once its line is deselected (see
 * `componentDidUpdate()`).
 *
 * Elements are taken by id from the scene: missing and deleted ones are
 * skipped.
 */
export class AppSelection {
  constructor(private app: App) {}

  /**
   * Selects the elements alone (with their groups, unless `deep`).
   */
  select = (elementsOrIds: ElementsOrIds, opts: SelectOptions = {}) => {
    const elements = this.resolve(elementsOrIds, opts.includeLocked);
    this.beforeChange(
      // (a click inside the image in the crop editor selects it again)
      elements.length === 1 &&
        elements[0].id === this.app.state.croppingElementId,
      opts,
      elements,
    );
    this.app.setState((prevState) =>
      this.withFollowingState(
        prevState,
        getSelectionStateForElements(
          elements,
          this.app.scene.getNonDeletedElements(),
          prevState,
          opts.deep,
        ),
      ),
    );
  };

  /**
   * Adds the elements (with their groups) to the selection.
   */
  add = (elementsOrIds: ElementsOrIds, opts: AddOptions = {}) => {
    const elements = this.resolve(elementsOrIds, opts.includeLocked);
    this.beforeChange(false, opts, elements);
    this.app.setState((prevState) =>
      this.withFollowingState(
        prevState,
        getSelectionStateAddingElements(
          elements,
          this.app.scene.getNonDeletedElements(),
          prevState,
        ),
      ),
    );
  };

  /**
   * Removes the elements from the selection — with the group they're
   * selected via.
   */
  remove = (
    elementsOrIds: ElementsOrIds,
    opts: SelectionChangeOptions = {},
  ) => {
    const elements = this.resolve(elementsOrIds, true);
    this.beforeChange(false, opts);
    this.app.setState((prevState) =>
      this.withFollowingState(
        prevState,
        getSelectionStateRemovingElements(
          elements,
          this.app.scene.getNonDeletedElements(),
          prevState,
        ),
      ),
    );
  };

  /**
   * Clears the selection, leaving the edited group and ending cropping.
   *
   * (Doesn't end text editing: starting it clears the selection.)
   */
  clear = (opts: SelectionChangeOptions = {}) => {
    this.app.finishImageCropping();
    if (opts.captureUpdate) {
      this.app.store.scheduleAction(opts.captureUpdate);
    }
    this.app.setState({
      selectedElementIds: makeNextSelectedElementIds({}, this.app.state),
      selectedGroupIds: {},
      editingGroupId: null,
      activeEmbeddable: null,
      showHyperlinkPopup: false,
    });
  };

  /**
   * Ends what changing the selection ends — cropping (unless
   * `keepsCroppedImage`), and text editing (unless selecting the edited text,
   * or its container) — and records the change for undo as asked.
   *
   * @param elements the elements being selected (or added) — none for a
   *   change that leaves text editing be
   */
  private beforeChange(
    keepsCroppedImage: boolean,
    { captureUpdate }: SelectionChangeOptions,
    elements?: readonly NonDeletedExcalidrawElement[],
  ) {
    const { editingTextElement } = this.app.state;
    if (
      elements &&
      editingTextElement &&
      !elements.some(
        (element) =>
          element.id === editingTextElement.id ||
          element.id === editingTextElement.containerId,
      )
    ) {
      // after the current event, as the editor submits with a flushSync (and
      // a pointer event's own blur would end it then anyway) — unless another
      // editing session started meanwhile
      const submit = this.app.text.textWysiwygSubmitHandler;
      queueMicrotask(() => {
        if (submit && this.app.text.textWysiwygSubmitHandler === submit) {
          submit();
        }
      });
    }
    if (!keepsCroppedImage) {
      this.app.finishImageCropping();
    }
    if (captureUpdate) {
      this.app.store.scheduleAction(captureUpdate);
    }
  }

  /**
   * The next selection state with what follows it: the link popup — shown for
   * a lone selected element with a link (or an embeddable), the link editor
   * staying open if it's the same element, and hidden otherwise — and the
   * active embed, which stays active only while selected.
   */
  private withFollowingState<T extends Pick<AppState, "selectedElementIds">>(
    prevState: AppState,
    nextState: T,
  ): T & Pick<AppState, "showHyperlinkPopup" | "activeEmbeddable"> {
    const activeEmbeddable =
      prevState.activeEmbeddable &&
      nextState.selectedElementIds[prevState.activeEmbeddable.element.id]
        ? prevState.activeEmbeddable
        : null;

    const ids = Object.keys(nextState.selectedElementIds);
    const element =
      ids.length === 1
        ? this.app.scene.getNonDeletedElementsMap().get(ids[0])
        : undefined;
    if (!element || !(element.link || isEmbeddableElement(element))) {
      return { ...nextState, activeEmbeddable, showHyperlinkPopup: false };
    }
    const prevIds = Object.keys(prevState.selectedElementIds);
    return {
      ...nextState,
      activeEmbeddable,
      showHyperlinkPopup:
        prevState.showHyperlinkPopup === "editor" &&
        prevIds.length === 1 &&
        prevIds[0] === element.id
          ? "editor"
          : "info",
    };
  }

  isASelectedElement(hitElement: ExcalidrawElement | null): boolean {
    return (
      hitElement != null && this.app.state.selectedElementIds[hitElement.id]
    );
  }

  isHittingCommonBoundingBoxOfSelectedElements(
    point: Readonly<{ x: number; y: number }>,
    selectedElements: readonly ExcalidrawElement[],
  ): boolean {
    if (selectedElements.length < 2) {
      return false;
    }

    // How many pixels off the shape boundary we still consider a hit
    const threshold = Math.max(
      DEFAULT_COLLISION_THRESHOLD / this.app.state.zoom.value,
      1,
    );
    const boundsPadding =
      (DEFAULT_TRANSFORM_HANDLE_SPACING * 2) / this.app.state.zoom.value;
    const [x1, y1, x2, y2] = getCommonBounds(selectedElements);
    return (
      point.x > x1 - boundsPadding - threshold &&
      point.x < x2 + boundsPadding + threshold &&
      point.y > y1 - boundsPadding - threshold &&
      point.y < y2 + boundsPadding + threshold
    );
  }

  /**
   * The scene's (non-deleted) elements, by id, once each — but locked ones,
   * unless `includeLocked`
   */
  private resolve(elementsOrIds: ElementsOrIds, includeLocked = false) {
    const elementsMap = this.app.scene.getNonDeletedElementsMap();
    const elements = new Map<
      ExcalidrawElement["id"],
      NonDeletedExcalidrawElement
    >();
    for (const elementOrId of (isReadonlyArray(elementsOrIds)
      ? elementsOrIds
      : [elementsOrIds]) as readonly (ExcalidrawElement | string)[]) {
      const id = typeof elementOrId === "string" ? elementOrId : elementOrId.id;
      const element = elementsMap.get(id);
      if (element && (includeLocked || !element.locked)) {
        elements.set(id, element);
      }
    }
    return [...elements.values()];
  }
}

