import {
  debounce,
  easeOut,
  isBounds,
  type Bounds,
  type StylesPanelMode,
} from "@excalidraw/common";
import { clamp } from "@excalidraw/math";

import {
  getCommonBounds,
  getElementsInGroup,
  isElementLink,
  isExcalidrawElement,
  parseElementLinkFromURL,
} from "@excalidraw/element";

import type {
  ExcalidrawElement,
  NonDeleted,
  NonDeletedSceneElementsMap,
} from "@excalidraw/element/types";

import { getLanguage, t } from "../i18n";
import { AnimationController } from "../renderer/animation";
import {
  constrainScrollState,
  DEFAULT_OVERSCROLL,
  type SetViewportOptions,
  type SetViewportRect,
  zoomToFitBounds,
} from "../viewport";

import type {
  AppProps,
  AppState,
  NormalizedZoomValue,
  Offsets,
  ScrollConstraints,
  ViewportOffsets,
  ViewportOffsetsOptions,
  ViewportUIDock,
  ViewportUIName,
} from "../types";
import type App from "./App";

export const SCROLL_TO_CONTENT_ANIMATION_KEY = "animateScrollToContent";
export const SCROLL_CONSTRAINTS_SNAP_BACK_ANIMATION_KEY =
  "animateScrollConstraintsSnapBack";

const DEFAULT_SCROLL_ANIMATION_DURATION = 500;

/** rubberband snap-back animation duration, in ms — kept snappier than the
 * default scroll animation so releasing an overscroll feels responsive */
const SNAP_BACK_ANIMATION_DURATION = 250;

/** how long after the last pan/zoom we animate the rubberband back into the
 * scroll constraints box */
const SCROLL_CONSTRAINTS_SNAP_BACK_DELAY = 200;

/** single source of truth for the `--right-sidebar-width` CSS variable */
export const RIGHT_SIDEBAR_WIDTH = 302;

/**
 * Approximate styles panel footprints (panel width + editor edge inset),
 * used by `getOffsets` to reserve space for the panel before it was ever
 * rendered (= measured). Keep roughly in sync with the CSS
 * (`.App-menu__left` width / `.compact-shape-actions-island` min-width +
 * `--editor-container-padding`).
 */
const STYLES_PANEL_APPROX_WIDTH = { full: 216, compact: 64 };

type Viewport = Pick<AppState, "scrollX" | "scrollY" | "zoom">;

const isSetViewportRect = (target: unknown): target is SetViewportRect => {
  if (!target || typeof target !== "object" || Array.isArray(target)) {
    return false;
  }

  const rect = target as Partial<SetViewportRect>;
  return (
    typeof rect.x === "number" &&
    typeof rect.y === "number" &&
    (rect.width == null || typeof rect.width === "number") &&
    (rect.height == null || typeof rect.height === "number")
  );
};

const getElementsFromId = (
  id: string,
  elementsMap: NonDeletedSceneElementsMap,
) => {
  const element = elementsMap.get(id);
  if (element) {
    return [element];
  }

  return getElementsInGroup(elementsMap, id);
};

type ResolvedViewportTarget = {
  /** null when the target couldn't be resolved (unknown id/link, or all
   * supplied elements deleted) */
  bounds: Bounds | null;
  /** how the target was specified, so callers can react to unresolved
   * targets themselves (e.g. toast on a broken element link) */
  type: "element" | "area" | "link";
};

/** Resolves a `setViewport` target to a scene-coordinate box. */
const resolveViewportTarget = (
  target: SetViewportOptions["target"],
  elementsMap: NonDeletedSceneElementsMap,
  appState: Pick<AppState, "width" | "height">,
): ResolvedViewportTarget => {
  if (typeof target === "string") {
    const isLink = isElementLink(target);
    const type = isLink ? ("link" as const) : ("element" as const);
    const id = isLink ? parseElementLinkFromURL(target) : target;
    const resolved = id ? getElementsFromId(id, elementsMap) : [];

    if (!resolved.length) {
      return { bounds: null, type };
    }

    return { bounds: getCommonBounds(resolved, elementsMap), type };
  }

  if (isBounds(target)) {
    return { bounds: target, type: "area" };
  }

  if (isSetViewportRect(target) && !isExcalidrawElement(target)) {
    const width = target.width ?? appState.width;
    const height = target.height ?? appState.height;
    return {
      bounds: [target.x, target.y, target.x + width, target.y + height],
      type: "area",
    };
  }

  // widening to null values in case the host app doesn't have
  // noUncheckedIndexedAccess enabled
  const targetElements: (ExcalidrawElement | undefined | null)[] =
    Array.isArray(target) ? target : [target];
  const elements = targetElements.reduce<NonDeleted<ExcalidrawElement>[]>(
    (acc, element) => {
      if (element && !element.isDeleted) {
        const sceneElement = elementsMap.get(element.id);
        if (sceneElement) {
          acc.push(sceneElement);
        }
      }
      return acc;
    },
    [],
  );

  const hasNoElements = !elements.length;
  if (elements.length !== targetElements.length || hasNoElements) {
    console.warn(
      "supplied element target(s) for setViewport contain deleted or non-existent elements which have been filtered out",
    );
  }

  if (hasNoElements) {
    return { bounds: null, type: "element" };
  }

  return { bounds: getCommonBounds(elements, elementsMap), type: "element" };
};

const resolveOverscroll = (
  overscroll: boolean | number | undefined,
): number => {
  if (overscroll === false) {
    return 0;
  }
  if (overscroll === true || overscroll == null) {
    return DEFAULT_OVERSCROLL;
  }
  return Math.max(overscroll, 0);
};

/** Computes the viewport (scroll + zoom) that brings the target box into view,
 * based on the requested fit behavior. */
const getTargetViewport = (
  state: AppState,
  bounds: Bounds,
  fit: SetViewportOptions["fit"] = "scale-down",
  offsets?: Offsets,
): Viewport => {
  const { appState } = zoomToFitBounds({
    bounds,
    appState: state,
    fit,
    canvasOffsets: offsets,
    steppedZoom: false,
  });

  return {
    scrollX: appState.scrollX,
    scrollY: appState.scrollY,
    zoom: appState.zoom,
  };
};

/** Computes the viewport patch for landing on `bounds`: the target
 * scroll/zoom, plus the scroll lock to install — or `scrollConstraints: null`
 * to clear a previous lock when none is requested. */
const getConstrainedTargetViewport = (
  appState: AppState,
  bounds: Bounds,
  // NOTE offsets must be resolved (see `AppViewport.resolveOffsets`)
  {
    fit,
    offsets,
    lock,
  }: Pick<SetViewportOptions, "fit" | "lock"> & { offsets?: Offsets },
): Viewport & { scrollConstraints: ScrollConstraints | null } => {
  const viewport = getTargetViewport(appState, bounds, fit, offsets);

  if (!lock?.scroll && !lock?.zoom) {
    return { ...viewport, scrollConstraints: null };
  }

  const [x1, y1, x2, y2] = bounds;
  const scrollConstraints: ScrollConstraints = {
    x: x1,
    y: y1,
    width: x2 - x1,
    height: y2 - y1,
    lockScroll: !!lock.scroll,
    lockZoom: !!lock.zoom,
    zoom: viewport.zoom.value,
    overscroll: resolveOverscroll(lock.overscroll),
    offsets,
  };

  return {
    ...constrainScrollState({ ...appState, ...viewport, scrollConstraints }),
    scrollConstraints,
  };
};

/**
 * Interpolates the viewport from `from` to `target` at the (already-eased)
 * blend amount `factor` (0 = `from`, 1 = `target`).
 *
 * Zoom is interpolated geometrically (so it feels uniform), but the pan can't
 * simply lerp alongside it: pairing a geometric zoom with a linear scroll (or
 * a linearly-tweened focal point) makes scene points swoop along curved,
 * non-monotone screen paths once the zoom ratio exceeds ~e (the destination
 * visibly drifts away before converging). Instead we interpolate the view
 * transform affinely — a scene point maps to screen as
 * `(scenePt + scroll) * zoom`, and requiring every point to travel a straight
 * screen line forces `zoom` to be a convex blend `(1-m)*z0 + m*z1` with
 * `scroll * zoom` lerped by that same weight. Deriving `m` from the geometric
 * zoom keeps its pacing while making all screen trajectories straight and
 * monotone.
 */
const interpolateViewport = ({
  from,
  target,
  factor,
}: {
  from: Viewport;
  target: Viewport;
  factor: number;
}): Viewport => {
  if (factor >= 1) {
    // land bit-exactly on the target (`z0 * (z1/z0)^1` can be off by an ulp)
    return { ...target };
  }

  const zoom = (from.zoom.value *
    Math.pow(
      target.zoom.value / from.zoom.value,
      factor,
    )) as NormalizedZoomValue;

  // pan blend weight derived from the zoom blend (0/0 for pure pans, hence
  // the `factor` fallback; near-equal zooms are fine — the ratio limits to
  // `factor` smoothly)
  const m =
    target.zoom.value === from.zoom.value
      ? factor
      : (zoom - from.zoom.value) / (target.zoom.value - from.zoom.value);

  return {
    scrollX:
      ((1 - m) * from.scrollX * from.zoom.value +
        m * target.scrollX * target.zoom.value) /
      zoom,
    scrollY:
      ((1 - m) * from.scrollY * from.zoom.value +
        m * target.scrollY * target.zoom.value) /
      zoom,
    zoom: { value: zoom },
  };
};

type AppViewportDependencies = {
  getContainer: () => HTMLDivElement | null;
  getStylesPanelMode: () => StylesPanelMode;
  isGestureActive: () => boolean;
};

const resolveAnimationDuration = (
  animation: SetViewportOptions["animation"],
): number | null => {
  if (animation === false) {
    return null;
  }
  if (animation === true || animation == null) {
    return DEFAULT_SCROLL_ANIMATION_DURATION;
  }
  return animation.duration ?? DEFAULT_SCROLL_ANIMATION_DURATION;
};

/** Eases the viewport from its current position to `target` over `duration`,
 * driving the transition through the shared AnimationController so it doesn't
 * slow down other processes. */
const animateToViewport = (
  from: Viewport,
  target: Viewport,
  duration: number,
  onFrame: (
    state: Pick<
      AppState,
      "scrollX" | "scrollY" | "zoom" | "shouldCacheIgnoreZoom"
    >,
  ) => void,
  onComplete: () => void,
) => {
  AnimationController.start<{ elapsed: number }>(
    SCROLL_TO_CONTENT_ANIMATION_KEY,
    ({ deltaTime, state }) => {
      const elapsed = (state?.elapsed ?? 0) + deltaTime;
      const progress = Math.min(elapsed / duration, 1);
      const factor = easeOut(clamp(progress, 0, 1));

      if (progress < 1) {
        onFrame({
          ...interpolateViewport({ from, target, factor }),
          shouldCacheIgnoreZoom: true,
        });
        return { elapsed };
      }

      onComplete();

      return null;
    },
  );
};

/**
 * Rubberband snap-back: animates the viewport from its current (possibly
 * overscrolled) position back inside the lock box via the shared
 * AnimationController. No-op when already within the hard bounds (or when
 * there is no lock).
 */
export const snapBackToConstraints = (
  state: Pick<
    AppState,
    "scrollX" | "scrollY" | "zoom" | "width" | "height" | "scrollConstraints"
  >,
  onFrame: (
    updater: (
      state: Pick<
        AppState,
        | "scrollX"
        | "scrollY"
        | "zoom"
        | "width"
        | "height"
        | "scrollConstraints"
      >,
    ) => Viewport | null,
  ) => void,
  duration = SNAP_BACK_ANIMATION_DURATION,
) => {
  const target = constrainScrollState(state);

  if (
    target.scrollX === state.scrollX &&
    target.scrollY === state.scrollY &&
    target.zoom.value === state.zoom.value
  ) {
    return;
  }

  // A programmatic navigation owns the viewport until it settles. A stale
  // rubberband debounce must not supersede it.
  if (AnimationController.running(SCROLL_TO_CONTENT_ANIMATION_KEY)) {
    return;
  }

  // Keep the displacement zoom-independent. Each animation frame resolves
  // the resting viewport from the latest state, allowing zoom to update the
  // underlying viewport while the same on-screen rubberband distance decays.
  const overscrollX = (state.scrollX - target.scrollX) * state.zoom.value;
  const overscrollY = (state.scrollY - target.scrollY) * state.zoom.value;

  AnimationController.start<{ elapsed: number }>(
    SCROLL_CONSTRAINTS_SNAP_BACK_ANIMATION_KEY,
    ({ deltaTime, state: animationState }) => {
      const elapsed = (animationState?.elapsed ?? 0) + deltaTime;
      const progress = Math.min(elapsed / duration, 1);
      const remaining = 1 - easeOut(clamp(progress, 0, 1));

      onFrame((currentState) => {
        if (!currentState.scrollConstraints) {
          return null;
        }

        const restingViewport = constrainScrollState(currentState);
        const zoom = restingViewport.zoom.value;
        return {
          scrollX: restingViewport.scrollX + (overscrollX * remaining) / zoom,
          scrollY: restingViewport.scrollY + (overscrollY * remaining) / zoom,
          zoom: restingViewport.zoom,
        };
      });

      return progress < 1 ? { elapsed } : null;
    },
  );
};

/**
 * Owns viewport state transitions and App-bound viewport concerns. Pure
 * viewport geometry remains in `viewport.ts` so actions and public helpers can
 * calculate state without an App instance.
 */
export class AppViewport {
  public lastPosition = { x: 0, y: 0 };

  private activeTransition: {
    target: Viewport & Pick<AppState, "scrollConstraints">;
  } | null = null;

  private uiLastMeasured = new Map<
    ViewportUIName,
    { side: "left" | "right"; offset: number }
  >();

  constructor(
    private app: App,
    private dependencies: AppViewportDependencies,
  ) {}

  get isAnimating() {
    return (
      AnimationController.running(SCROLL_TO_CONTENT_ANIMATION_KEY) ||
      AnimationController.running(SCROLL_CONSTRAINTS_SNAP_BACK_ANIMATION_KEY)
    );
  }

  /** Whether a programmatic transition into a locked viewport currently owns
   * user pan/zoom input. */
  get isLockedTransitionPending() {
    return !!this.activeTransition?.target.scrollConstraints;
  }

  invalidateUIOffset = (name: ViewportUIName) => {
    this.uiLastMeasured.delete(name);
  };

  /**
   * The side a rendered side UI (`data-viewport-ui="side"`) docks to, and
   * how far it reaches into the canvas from it, in screen px.
   */
  private measureSide = (node: HTMLElement, containerRect: DOMRect) => {
    const domRect = node.getBoundingClientRect();
    const left = domRect.left - containerRect.left;
    const right = domRect.right - containerRect.left;
    return left + domRect.width / 2 < this.app.state.width / 2
      ? { side: "left" as const, offset: right }
      : { side: "right" as const, offset: this.app.state.width - left };
  };

  /**
   * The side a named surface docks to while it's hidden, and how far it
   * reaches into the canvas from it: as last measured, else approximately.
   */
  private getReservedSide = (
    name: keyof NonNullable<ViewportOffsetsOptions["reserve"]>,
  ) => {
    const isRTL = getLanguage().rtl;
    return (
      this.uiLastMeasured.get(name) ??
      (name === "stylesPanel"
        ? {
            side: isRTL ? ("right" as const) : ("left" as const),
            offset:
              this.dependencies.getStylesPanelMode() === "compact"
                ? STYLES_PANEL_APPROX_WIDTH.compact
                : STYLES_PANEL_APPROX_WIDTH.full,
          }
        : {
            side: isRTL ? ("left" as const) : ("right" as const),
            offset: RIGHT_SIDEBAR_WIDTH,
          })
    );
  };

  private querySideUI = (container: HTMLElement, name: ViewportUIName) =>
    container.querySelector<HTMLElement>(
      `[data-viewport-ui="side"][data-viewport-ui-name="${name}"]`,
    );

  /**
   * Where a rendered side UI is, relative to the editor's container, in
   * screen px; null when it isn't rendered.
   */
  getSideUIRect = (name: ViewportUIName) => {
    const container = this.dependencies.getContainer();
    const node = container && this.querySideUI(container, name);
    if (!container || !node) {
      return null;
    }
    const containerRect = container.getBoundingClientRect();
    const rect = node.getBoundingClientRect();
    return {
      left: rect.left - containerRect.left,
      right: rect.right - containerRect.left,
      top: rect.top - containerRect.top,
      bottom: rect.bottom - containerRect.top,
    };
  };

  /**
   * How far the named side UIs reach into the canvas, in screen px, from
   * the left and the right: the part of the canvas they cover. Zero at a
   * side none of them is rendered at — e.g. with the sidebar closed, or on
   * phones, where it's an overlay that doesn't count as viewport UI — unless
   * a hidden one is reserved (see `ViewportOffsetsOptions.reserve`).
   */
  getSideInsets = (
    names: readonly ViewportUIName[],
    opts?: Pick<ViewportOffsetsOptions, "reserve">,
  ) => {
    const insets = { left: 0, right: 0 };
    const container = this.dependencies.getContainer();
    if (!container) {
      return insets;
    }
    const containerRect = container.getBoundingClientRect();
    for (const name of names) {
      const node = this.querySideUI(container, name);
      let footprint: { side: "left" | "right"; offset: number } | null = null;
      if (node) {
        footprint = this.measureSide(node, containerRect);
        if (footprint.offset > 0) {
          this.uiLastMeasured.set(name, footprint);
        }
      } else if (
        name !== "stats" &&
        opts?.reserve?.[name] &&
        this.app.editorInterface.formFactor !== "phone"
      ) {
        footprint = this.getReservedSide(name);
      }
      if (footprint) {
        insets[footprint.side] = Math.max(
          insets[footprint.side],
          footprint.offset,
        );
      }
    }
    return insets;
  };

  /** How far the sidebar reaches into the canvas (see `getSideInsets`). */
  getSidebarInsets = () => this.getSideInsets(["sidebar"]);

  /**
   * Resolves user-supplied viewport offsets into concrete per-side pixel
   * values. Static sides take precedence over UI-derived sides.
   */
  resolveOffsets = (
    offsets: ViewportOffsets | undefined,
  ): Offsets | undefined => {
    if (!offsets) {
      return offsets;
    }

    const { ui, ...staticOffsets } = offsets;

    if (!ui) {
      return staticOffsets;
    }

    const uiOffsets = this.getOffsets(ui === true ? undefined : ui);

    return {
      top: staticOffsets.top ?? uiOffsets.top,
      right: staticOffsets.right ?? uiOffsets.right,
      bottom: staticOffsets.bottom ?? uiOffsets.bottom,
      left: staticOffsets.left ?? uiOffsets.left,
    };
  };

  /**
   * Measures the currently rendered editor UI and returns the usable viewport
   * offsets, including optional padding and reserved hidden surfaces.
   */
  getOffsets = (opts?: ViewportOffsetsOptions): Offsets => {
    const excalidrawContainer = this.dependencies.getContainer();
    const excalidrawContainerRect =
      excalidrawContainer?.getBoundingClientRect();
    const isRTL = getLanguage().rtl;

    const measuredOffsets = { top: 0, right: 0, bottom: 0, left: 0 };
    const renderedSurfaces = new Set<ViewportUIName>();

    if (excalidrawContainer && excalidrawContainerRect) {
      for (const node of excalidrawContainer.querySelectorAll<HTMLElement>(
        "[data-viewport-ui]",
      )) {
        const domRect = node.getBoundingClientRect();
        const rect = {
          top: domRect.top - excalidrawContainerRect.top,
          right: domRect.right - excalidrawContainerRect.left,
          bottom: domRect.bottom - excalidrawContainerRect.top,
          left: domRect.left - excalidrawContainerRect.left,
          width: domRect.width,
        };

        switch (node.dataset.viewportUi as ViewportUIDock) {
          case "top":
            measuredOffsets.top = Math.max(measuredOffsets.top, rect.bottom);
            break;
          case "bottom":
            measuredOffsets.bottom = Math.max(
              measuredOffsets.bottom,
              this.app.state.height - rect.top,
            );
            break;
          case "side": {
            const { side, offset } = this.measureSide(
              node,
              excalidrawContainerRect,
            );

            measuredOffsets[side] = Math.max(measuredOffsets[side], offset);

            const name = node.dataset.viewportUiName as
              | ViewportUIName
              | undefined;
            if (name) {
              renderedSurfaces.add(name);
              if (offset > 0) {
                this.uiLastMeasured.set(name, { side, offset });
              }
            }
            break;
          }
        }
      }
    }

    if (opts?.reserve && this.app.editorInterface.formFactor !== "phone") {
      for (const name of ["stylesPanel", "sidebar"] as const) {
        if (opts.reserve[name] && !renderedSurfaces.has(name)) {
          const { side, offset } = this.getReservedSide(name);
          measuredOffsets[side] = Math.max(measuredOffsets[side], offset);
        }
      }
    }

    const padding = opts?.padding ?? 24;
    const topPadding = opts?.paddingTop ?? padding;
    const rightPadding =
      (isRTL ? opts?.paddingLeft : opts?.paddingRight) ?? padding;
    const bottomPadding = opts?.paddingBottom ?? padding;
    const leftPadding =
      (isRTL ? opts?.paddingRight : opts?.paddingLeft) ?? padding;

    const editorOffsets = {
      top: measuredOffsets.top + topPadding,
      right: measuredOffsets.right + rightPadding,
      bottom: measuredOffsets.bottom + bottomPadding,
      left: measuredOffsets.left + leftPadding,
    };

    return {
      top: opts?.top ?? editorOffsets.top,
      right: (isRTL ? opts?.left : opts?.right) ?? editorOffsets.right,
      bottom: opts?.bottom ?? editorOffsets.bottom,
      left: (isRTL ? opts?.right : opts?.left) ?? editorOffsets.left,
    };
  };

  /** Resolves the host-supplied initial viewport against restored scene data. */
  resolveInitialViewport = (
    opts: Omit<SetViewportOptions, "animation">,
    elementsMap: NonDeletedSceneElementsMap,
    appState: AppState,
  ) => {
    const { bounds } = resolveViewportTarget(
      opts.target,
      elementsMap,
      appState,
    );

    if (!bounds) {
      return null;
    }

    return getConstrainedTargetViewport(appState, bounds, {
      ...opts,
      // Initial state is resolved post-mount so UI-derived offsets measure
      // the actually-rendered editor UI.
      offsets: this.resolveOffsets(opts.offsets),
    });
  };

  /**
   * Navigates to a target and optionally installs scroll/zoom constraints.
   * Navigating stops following a collaborator, as a user's pan does.
   */
  setViewport = (opts: SetViewportOptions | null) => {
    if (opts === null) {
      this.cancelTransition();
      AnimationController.cancel(SCROLL_CONSTRAINTS_SNAP_BACK_ANIMATION_KEY);
      this.snapBackDebounced.cancel();
      this.app.setState({
        scrollConstraints: null,
        shouldCacheIgnoreZoom: false,
      });
      return;
    }

    const { target, fit, lock, animation } = opts;
    const offsets = this.resolveOffsets(opts.offsets);
    const { bounds, type } = resolveViewportTarget(
      target,
      this.app.scene.getNonDeletedElementsMap(),
      this.app.state,
    );

    if (!bounds) {
      if (type === "link") {
        this.app.setState({
          toast: {
            message: t("elementLink.notFound"),
            duration: 3000,
            closable: true,
          },
        });
      }
      return;
    }

    // the view is about to show something other than what the followed
    // user sees
    this.app.requestUnfollow();

    const viewportUpdate = getConstrainedTargetViewport(
      this.app.state,
      bounds,
      { fit, offsets, lock },
    );
    const duration = resolveAnimationDuration(animation);
    const from = {
      scrollX: this.app.state.scrollX,
      scrollY: this.app.state.scrollY,
      zoom: this.app.state.zoom,
    };

    // A new programmatic navigation supersedes the previous one and starts
    // from whatever viewport its last rendered frame reached.
    this.cancelTransition();
    AnimationController.cancel(SCROLL_CONSTRAINTS_SNAP_BACK_ANIMATION_KEY);
    this.snapBackDebounced.cancel();

    if (duration === null) {
      this.app.setState({
        ...viewportUpdate,
        shouldCacheIgnoreZoom: false,
      });
      return;
    }

    const transition = {
      target: viewportUpdate,
    };
    this.activeTransition = transition;

    // The old lock has been superseded. Keep the new lock pending outside
    // AppState so it cannot constrain animation frames back toward either
    // endpoint, and install it together with the final viewport.
    if (this.app.state.scrollConstraints) {
      this.app.setState({ scrollConstraints: null });
    }

    animateToViewport(
      from,
      viewportUpdate,
      duration,
      (state) => {
        if (this.activeTransition === transition) {
          this.app.setState(state);
        }
      },
      () => {
        if (this.activeTransition !== transition) {
          return;
        }

        this.activeTransition = null;
        this.app.setState({
          ...transition.target,
          shouldCacheIgnoreZoom: false,
        });
      },
    );
  };

  /** Use when changing scrollX/scrollY/zoom based on user interaction. */
  translate = <K extends keyof AppState>(
    state:
      | AppState
      | Pick<AppState, K>
      | null
      | ((
          prevState: Readonly<AppState>,
          props: Readonly<AppProps>,
        ) => AppState | Pick<AppState, K> | null),
    opts?: {
      zoomPreConstrained?: boolean;
      preserveScrollConstraintsSnapBack?: boolean;
    },
  ) => {
    if (this.isLockedTransitionPending) {
      return false;
    }

    // a user gesture interrupting an animated `setViewport` takes over from
    // frames that draw from zoom-scaled bitmaps, and the completion handler
    // that would switch back to crisp ones no longer runs. Otherwise the
    // flag is left alone: wheel and touch zoom set it and clear it on a
    // debounce once the gesture is over, and a pan frame landing between two
    // zoom ticks must not force every element to be re-rasterized at the
    // in-progress zoom
    if (this.activeTransition) {
      this.app.setState({ shouldCacheIgnoreZoom: false });
    }
    this.cancelTransition();
    if (!opts?.preserveScrollConstraintsSnapBack) {
      AnimationController.cancel(SCROLL_CONSTRAINTS_SNAP_BACK_ANIMATION_KEY);
    }
    this.app.requestUnfollow();

    this.app.setState((prevState, props) => {
      const update =
        typeof state === "function" ? state(prevState, props) : state;
      if (!update) {
        return null;
      }
      const nextState = { ...prevState, ...update };
      if (!nextState.scrollConstraints) {
        return update;
      }
      const zoomed =
        !opts?.zoomPreConstrained &&
        nextState.zoom.value !== prevState.zoom.value;
      const overscroll = zoomed ? 0 : nextState.scrollConstraints.overscroll;
      if (overscroll > 0) {
        this.snapBackDebounced();
      }
      return { ...nextState, ...constrainScrollState(nextState, overscroll) };
    });

    return true;
  };

  /** Clamps the viewport into the active scroll constraints. */
  constrain = (overscroll = 0) => {
    this.app.setState((prevState) =>
      prevState.scrollConstraints
        ? constrainScrollState(prevState, overscroll)
        : null,
    );
  };

  /** Releases a held rubberband overscroll. */
  releaseOverscroll = () => {
    if (!this.app.state.scrollConstraints) {
      return;
    }
    this.snapBackDebounced.cancel();
    this.snapBack();
  };

  private snapBack = () => {
    if (this.app.unmounted || this.dependencies.isGestureActive()) {
      return;
    }
    snapBackToConstraints(this.app.state, (updater) =>
      this.app.setState((state) => updater(state)),
    );
  };

  private snapBackDebounced = debounce(
    this.snapBack,
    SCROLL_CONSTRAINTS_SNAP_BACK_DELAY,
  );

  private cancelTransition = () => {
    this.activeTransition = null;
    AnimationController.cancel(SCROLL_TO_CONTENT_ANIMATION_KEY);
  };

  destroy = () => {
    this.cancelTransition();
    AnimationController.cancel(SCROLL_CONSTRAINTS_SNAP_BACK_ANIMATION_KEY);
    this.snapBackDebounced.cancel();
  };
}

import { CLASSES, KEYS, MIN_ZOOM, ZOOM_STEP } from "@excalidraw/common";

import { resolveInputDevice } from "../appState";
import { withBatchedUpdates } from "../reactUtils";
import { getNormalizedZoom } from "../scene";
import { getViewportForZoomWithScrollConstraints } from "../viewport";

import type App from "./App";

/** `MouseEvent.buttons` bit of the wheel (middle) button */
const WHEEL_BUTTON_MASK = 4;

/**
 * Wheel input over the editor: pans the canvas, or zooms it around the
 * pointer (`viewport.lastPosition`) — on ctrl/cmd+wheel (which is also how
 * a trackpad pinch is delivered), while the wheel button itself is held
 * down, or on a plain wheel when the input device is a mouse
 * (`appState.inputDevice`). Shift+wheel pans horizontally;
 * ctrl/cmd+shift+wheel pans vertically.
 */
export class AppWheel {
  constructor(private app: App) {}

  /** the editor surfaces whose wheel input the editor consumes; everywhere
   * else (menus, sidebars, …) the DOM keeps scrolling. The frame-name labels
   * are DOM, but sit inside the container this listener is attached to */
  private isOverEditorSurface = (event: WheelEvent) => {
    const { ownerWindow } = this.app;
    return (
      event.target instanceof ownerWindow.HTMLCanvasElement ||
      event.target instanceof ownerWindow.HTMLTextAreaElement ||
      event.target instanceof ownerWindow.HTMLIFrameElement ||
      (event.target instanceof ownerWindow.HTMLElement &&
        event.target.classList.contains(CLASSES.FRAME_NAME))
    );
  };

  handle = withBatchedUpdates((event: WheelEvent) => {
    // NOTE no preventDefault so the page can scroll over the editor
    if (!this.app.isNavigationEnabled()) {
      return;
    }
    if (!this.isOverEditorSurface(event)) {
      // prevent zooming the browser (but allow scrolling DOM)
      if (event[KEYS.CTRL_OR_CMD]) {
        event.preventDefault();
      }

      return;
    }

    event.preventDefault();

    // scrolling with the wheel button held down zooms: the wheel sits under
    // the same finger, so a wheel-button pan can be zoomed without reaching
    // for a modifier — hence it wins over any modifier, and over the
    // drag-pan the button itself started
    const isWheelButtonHeld = !!(event.buttons & WHEEL_BUTTON_MASK);

    // a drag-pan (wheel button, space+drag, hand tool) in progress owns the
    // viewport; wheel input is ignored meanwhile — except for the wheel
    // button's own zoom
    if (this.app.pan.isActive()) {
      if (!isWheelButtonHeld) {
        return;
      }
      // the drag-pan applies pointer movement once per frame; a move still
      // waiting for its frame has to land before the zoom, or it lands after
      // it — at the new zoom, on a viewport the zoom anchored without it —
      // and the point grabbed by the pan drifts from under the cursor a
      // little on every tick
      this.app.pan.flushMove();
    }

    const { deltaX, deltaY } = event;
    if (!deltaX && !deltaY) {
      return;
    }
    // note that event.ctrlKey is necessary to handle pinch zooming
    const hasZoomModifier = event.metaKey || event.ctrlKey;
    const shouldZoom =
      // a horizontal-only wheel (tilt wheel, sideways two-finger scroll)
      // has nothing to zoom by; it follows the pan mappings below instead
      deltaY !== 0 &&
      (isWheelButtonHeld ||
        (!event.shiftKey &&
          (hasZoomModifier ||
            resolveInputDevice(this.app.state.inputDevice) === "mouse")));
    if (shouldZoom) {
      this.zoomBy(deltaY);
      return;
    }

    // Shift pans horizontally; ctrl/cmd+shift pans vertically.
    if (event.shiftKey) {
      // on Mac, shift+wheel tends to result in deltaX
      const delta = deltaY || deltaX;
      this.app.viewport.translate(({ zoom, scrollX, scrollY }) => ({
        scrollX: hasZoomModifier ? scrollX : scrollX - delta / zoom.value,
        scrollY: hasZoomModifier ? scrollY - delta / zoom.value : scrollY,
      }));
      return;
    }

    this.app.viewport.translate(({ zoom, scrollX, scrollY }) => ({
      scrollX: scrollX - deltaX / zoom.value,
      scrollY: scrollY - deltaY / zoom.value,
    }));
  });

  /**
   * Prevents the browser's own zoom over the non-interactive editor while
   * letting regular scroll through (trackpad pinch is delivered as
   * ctrl+wheel).
   */
  preventBrowserZoom = (event: WheelEvent) => {
    if (event[KEYS.CTRL_OR_CMD]) {
      event.preventDefault();
    }
  };

  /** zooms around the pointer by a wheel delta (positive = zoom out) */
  private zoomBy = (deltaY: number) => {
    const { viewport } = this.app;

    const sign = Math.sign(deltaY);
    const MAX_STEP = ZOOM_STEP * 100;
    const absDelta = Math.abs(deltaY);
    let delta = deltaY;
    if (absDelta > MAX_STEP) {
      delta = MAX_STEP * sign;
    }

    // where the pointer is now — the updater below runs when React flushes,
    // by which time the pointer may have moved on (`lastPosition` is live)
    const { x: viewportX, y: viewportY } = viewport.lastPosition;

    const didTranslate = viewport.translate(
      // computed from the state the zoom applies to, not `app.state`: wheel
      // ticks arriving before React has flushed the previous one would
      // otherwise all start from the same zoom and collapse into one step
      (state) => {
        let newZoom = state.zoom.value - delta / 100;
        // increase zoom steps the more zoomed-in we are (applies to >100% only)
        newZoom +=
          Math.log10(Math.max(1, state.zoom.value)) *
          -sign *
          // reduced amplification for small deltas (small movements on a trackpad)
          Math.min(1, absDelta / 20);

        const minZoom = state.scrollConstraints?.lockZoom
          ? state.scrollConstraints.zoom
          : MIN_ZOOM;
        const nextZoom = getNormalizedZoom(Math.max(newZoom, minZoom));
        if (nextZoom === state.zoom.value) {
          // at a zoom limit there is nothing to do; flipping the bitmap-cache
          // flag would only redraw the scene on every tick
          return null;
        }

        return {
          ...getViewportForZoomWithScrollConstraints(
            { viewportX, viewportY, nextZoom },
            state,
          ),
          shouldCacheIgnoreZoom: true,
        };
      },
      {
        zoomPreConstrained: true,
        preserveScrollConstraintsSnapBack: true,
      },
    );
    if (didTranslate) {
      this.app.resetShouldCacheIgnoreZoomDebounced();
    }
  };
}

import {
  BoundElement,
  CaptureUpdateAction,
  fixBindingsAfterDeletion,
  getBoundTextElement,
  getNonDeletedElements,
  hasBoundTextElement,
  isArrowElement,
  isBoundToContainer,
  isFrameLikeElement,
  isTextBindableContainer,
  isTextElement,
  normalizeStickyNoteFontSize,
  redrawTextBoundingBox,
  updateBoundElements,
} from "@excalidraw/element";

import type {
  ExcalidrawArrowElement,
  ExcalidrawElement,
  ExcalidrawTextContainer,
  ExcalidrawTextElement,
  FixedPointBinding,
  NonDeletedExcalidrawElement,
} from "@excalidraw/element/types";

import type { Radians } from "@excalidraw/math";

import {
  bindTextToContainer,
  getStickyNoteInk,
  pushContainerBelowText,
  unbindTextFromContainer,
  wrapTextsInContainers,
} from "../actions/actionBoundText";
import {
  getFrameToUnwrap,
  unwrapFrame,
  wrapInFrame,
} from "../actions/actionFrame";

import { getSelectionStateForElements } from "./App.selection";

import type { ActionResult } from "../actions/types";
import type { AppState } from "../types";
import type App from "./App";

/** a container unwrapping removed, and how its text sat in it */
type UnwrappedContainer = {
  containerId: ExcalidrawTextContainer["id"];
  textId: ExcalidrawTextElement["id"];
  baseFontSize: ExcalidrawTextElement["baseFontSize"];
  labelPosition: ExcalidrawTextElement["labelPosition"];
  autoResize: ExcalidrawTextElement["autoResize"];
  /**
   * the freed text as it landed, to tell how far it moved since (it doesn't
   * auto-resize, so a font size change doesn't move it) and whether it was
   * resized
   */
  text: Pick<ExcalidrawTextElement, "x" | "y" | "fontSize">;
  /** the arrows bound to the container, as they were bound */
  arrows: Pick<ExcalidrawArrowElement, "id" | "startBinding" | "endBinding">[];
};

const rebind = (
  binding: FixedPointBinding | null,
  fromId: ExcalidrawElement["id"],
  toId: ExcalidrawElement["id"],
) =>
  binding?.elementId === fromId ? { ...binding, elementId: toId } : binding;

/**
 * Wraps the selection in what fits it, or unwraps it, preferring containers
 * over frames:
 *
 * 1. a text and a container without one: binds the text to the container
 * 2. texts, with any labeled containers: wraps each text in a container
 * 3. labeled containers: unwraps their texts, removing the containers
 * 4. a frame with any of its children, or all of a frame's children: removes
 *    the frame
 * 5. anything else without a frame: wraps it in a frame
 *
 * The containers (3) removed come back in place of new ones while the
 * selection it left stands, so diamonds, notes and arrows survive a toggle.
 */
export class AppWrap {
  private unwrapped: {
    selectedElementIds: AppState["selectedElementIds"];
    containers: readonly UnwrappedContainer[];
  } | null = null;

  constructor(private app: App) {}

  toggle = (
    elements: readonly ExcalidrawElement[],
    appState: Readonly<AppState>,
  ): ActionResult => {
    const unwrapped =
      this.unwrapped?.selectedElementIds === appState.selectedElementIds
        ? this.unwrapped
        : null;
    this.unwrapped = null;

    const selectedElements = this.app.scene
      .getSelectedElements(appState)
      .filter((element) => !isBoundToContainer(element));
    const texts = selectedElements.filter(
      (
        element,
      ): element is NonDeletedExcalidrawElement & ExcalidrawTextElement =>
        isTextElement(element),
    );
    const labeledContainers = selectedElements.filter((element) =>
      hasBoundTextElement(element),
    );

    if (selectedElements.length === 2 && texts.length === 1) {
      const container = selectedElements.find(
        (element) => element !== texts[0],
      )!;
      if (
        isTextBindableContainer(container) &&
        !hasBoundTextElement(container)
      ) {
        return bindTextToContainer(
          elements,
          appState,
          texts[0],
          container,
          this.app,
        );
      }
    }

    if (
      texts.length &&
      texts.length + labeledContainers.length === selectedElements.length
    ) {
      const rewrapped =
        unwrapped && this.rewrap(elements, appState, unwrapped.containers);
      if (rewrapped) {
        return rewrapped;
      }

      const result = wrapTextsInContainers(elements, appState, texts, this.app);
      return (
        result && {
          ...result,
          appState: {
            ...result.appState,
            // the labeled containers stay selected, to unwrap next along
            // with the new ones
            selectedElementIds: {
              ...result.appState?.selectedElementIds,
              ...Object.fromEntries(
                labeledContainers.map((element) => [element.id, true] as const),
              ),
            },
          },
        }
      );
    }

    if (labeledContainers.length === selectedElements.length) {
      return this.unwrap(elements, appState, labeledContainers);
    }

    const frameToUnwrap = getFrameToUnwrap(
      selectedElements,
      this.app.scene.getNonDeletedElementsMap(),
    );
    if (frameToUnwrap) {
      return unwrapFrame(elements, appState, frameToUnwrap, this.app);
    }

    if (
      selectedElements.length &&
      !selectedElements.some((element) => isFrameLikeElement(element))
    ) {
      return wrapInFrame(elements, appState, selectedElements, this.app);
    }

    return false;
  };

  /** frees the containers' texts, moving the containers' arrows onto them */
  private unwrap(
    elements: readonly ExcalidrawElement[],
    appState: Readonly<AppState>,
    containers: readonly ExcalidrawElement[],
  ): ActionResult {
    const { scene } = this.app;
    const elementsMap = scene.getNonDeletedElementsMap();
    const texts: NonDeletedExcalidrawElement[] = [];
    const unwrapped: UnwrappedContainer[] = [];

    for (const container of containers) {
      const text = getBoundTextElement(container, elementsMap);
      if (!text) {
        continue;
      }
      const arrows = (container.boundElements ?? []).flatMap(({ id }) => {
        const arrow = elementsMap.get(id);
        return arrow && isArrowElement(arrow) ? [arrow] : [];
      });

      const { baseFontSize, labelPosition, autoResize } = text;
      unbindTextFromContainer(container, text, scene);
      unwrapped.push({
        containerId: container.id,
        textId: text.id,
        baseFontSize,
        labelPosition,
        autoResize,
        text: { x: text.x, y: text.y, fontSize: text.fontSize },
        arrows: arrows.map(({ id, startBinding, endBinding }) => ({
          id,
          startBinding,
          endBinding,
        })),
      });

      if (arrows.length) {
        for (const arrow of arrows) {
          scene.mutateElement(arrow, {
            startBinding: rebind(arrow.startBinding, container.id, text.id),
            endBinding: rebind(arrow.endBinding, container.id, text.id),
          });
        }
        scene.mutateElement(text, {
          boundElements: [
            ...(text.boundElements ?? []),
            ...arrows.map(({ id }) => ({ id, type: "arrow" as const })),
          ],
        });
      }
      scene.mutateElement(container, {
        isDeleted: true,
        boundElements: container.boundElements?.filter(
          ({ id }) => !arrows.some((arrow) => arrow.id === id),
        ),
      });
      updateBoundElements(text, scene);

      texts.push(text);
    }

    fixBindingsAfterDeletion(
      elements,
      containers.filter((container) => container.isDeleted),
    );

    // also drops the line editor of an unwrapped arrow
    const selection = getSelectionStateForElements(
      texts,
      getNonDeletedElements(elements),
      appState,
    );
    this.unwrapped = {
      selectedElementIds: selection.selectedElementIds,
      containers: unwrapped,
    };

    return {
      elements,
      appState: { ...appState, ...selection },
      captureUpdate: CaptureUpdateAction.IMMEDIATELY,
    };
  }

  /**
   * puts the unwrapped texts back into their containers, along with the
   * containers' arrows — `null` when any of them is gone
   */
  private rewrap(
    elements: readonly ExcalidrawElement[],
    appState: Readonly<AppState>,
    unwrapped: readonly UnwrappedContainer[],
  ): ActionResult | null {
    const { scene } = this.app;
    const allElementsMap = scene.getElementsMapIncludingDeleted();

    const pairs = [];
    for (const entry of unwrapped) {
      const container = allElementsMap.get(entry.containerId);
      const text = allElementsMap.get(entry.textId);
      if (
        !container?.isDeleted ||
        !isTextBindableContainer(container) ||
        !text ||
        text.isDeleted ||
        !isTextElement(text) ||
        text.containerId
      ) {
        return null;
      }
      pairs.push({ entry, deletedContainer: container, text });
    }

    for (const { deletedContainer } of pairs) {
      scene.mutateElement(deletedContainer, { isDeleted: false });
    }
    // so that the restored containers resolve as bindings again
    scene.replaceAllElements(scene.getElementsIncludingDeleted());

    const elementsMap = scene.getNonDeletedElementsMap();
    const containers: NonDeletedExcalidrawElement[] = [];

    let nextElements: readonly ExcalidrawElement[] =
      scene.getElementsIncludingDeleted();

    for (const { entry, text } of pairs) {
      const container = elementsMap.get(entry.containerId)!;
      const isArrowContainer = isArrowElement(container);
      // the container comes back wherever its text went in the meantime,
      // except an arrow anchored to the elements it connects
      const isAnchored =
        isArrowContainer && !!(container.startBinding || container.endBinding);
      const [dx, dy] = isAnchored
        ? [0, 0]
        : [text.x - entry.text.x, text.y - entry.text.y];
      const stickyInk = getStickyNoteInk(text, container);
      scene.mutateElement(container, {
        frameId: text.frameId,
        x: container.x + dx,
        y: container.y + dy,
        ...(stickyInk ? { strokeColor: stickyInk } : null),
        ...(isArrowContainer ? null : { angle: text.angle }),
      });
      // an arrow container rejoins the elements it connects
      BoundElement.rebindAffected(elementsMap, container, (element, updates) =>
        scene.mutateElement(element, updates),
      );

      const arrowIds = new Set<ExcalidrawElement["id"]>();
      for (const { id, startBinding, endBinding } of entry.arrows) {
        const arrow = elementsMap.get(id);
        if (!arrow || !isArrowElement(arrow)) {
          continue;
        }
        const isStartOnText = arrow.startBinding?.elementId === text.id;
        const isEndOnText = arrow.endBinding?.elementId === text.id;
        if (isStartOnText || isEndOnText) {
          scene.mutateElement(arrow, {
            startBinding: isStartOnText ? startBinding : arrow.startBinding,
            endBinding: isEndOnText ? endBinding : arrow.endBinding,
          });
          arrowIds.add(id);
        }
      }

      scene.mutateElement(container, {
        boundElements: [
          ...(container.boundElements ?? []),
          { id: text.id, type: "text" as const },
          ...Array.from(arrowIds, (id) => ({ id, type: "arrow" as const })),
        ],
      });
      scene.mutateElement(text, {
        containerId: container.id,
        // a note's label keeps the size picked while it was unwrapped
        baseFontSize:
          entry.baseFontSize !== null && text.fontSize !== entry.text.fontSize
            ? normalizeStickyNoteFontSize(text.fontSize)
            : entry.baseFontSize,
        labelPosition: entry.labelPosition,
        autoResize: entry.autoResize,
        ...(stickyInk ? { strokeColor: stickyInk } : null),
        // a label carries no arrows of its own
        boundElements: null,
        ...(isArrowContainer ? { angle: 0 as Radians } : null),
      });
      redrawTextBoundingBox(text, container, scene);
      updateBoundElements(container, scene);
      // the text may have changed layers since
      nextElements = pushContainerBelowText(nextElements, container, text);

      containers.push(container);
    }

    return {
      elements: nextElements,
      appState: {
        ...appState,
        // with the line editor of a restored arrow
        ...getSelectionStateForElements(
          containers,
          getNonDeletedElements(nextElements),
          appState,
        ),
      },
      captureUpdate: CaptureUpdateAction.IMMEDIATELY,
    };
  }
}

import type { AppState, UnsubscribeCallback } from "../types";

type StateChangeSelector =
  | keyof AppState
  | (keyof AppState)[]
  | ((appState: AppState) => unknown);

type StateChangePredicateOptions = {
  predicate: (appState: AppState) => boolean;
  callback?: (appState: AppState) => void;
  once?: boolean;
};

type StateChangeArg = StateChangeSelector | StateChangePredicateOptions;

type StateChangeListener = {
  predicate: (appState: AppState, prevState: AppState) => boolean;
  getValue: (appState: AppState) => unknown;
  callback: (value: any, appState: AppState) => void;
  once: boolean;
};

type NormalizedStateChange = {
  predicate: StateChangeListener["predicate"];
  getValue: StateChangeListener["getValue"];
  callback?: StateChangeListener["callback"];
  once: boolean;
  matchesImmediately: boolean;
};

export type OnStateChange = {
  <K extends keyof AppState>(
    prop: K,
    callback: (value: AppState[K], appState: AppState) => void,
    opts?: { once: boolean },
  ): UnsubscribeCallback;
  <K extends keyof AppState>(prop: K): Promise<AppState[K]>;
  (
    prop: (keyof AppState)[],
    callback: (appState: AppState, appState2: AppState) => void,
    opts?: { once: boolean },
  ): UnsubscribeCallback;
  (prop: (keyof AppState)[]): Promise<AppState>;
  <T>(
    prop: (appState: AppState) => T,
    callback: (value: T, appState: AppState) => void,
    opts?: { once: boolean },
  ): UnsubscribeCallback;
  <T>(prop: (appState: AppState) => T): Promise<T>;
  (opts: {
    predicate: (appState: AppState) => boolean;
    callback: (appState: AppState) => void;
    once?: boolean;
  }): UnsubscribeCallback;
  (opts: { predicate: (appState: AppState) => boolean }): Promise<AppState>;
  (
    selector: StateChangeSelector,
    callback: (value: any, appState: AppState) => void,
  ): any;
};

export class AppStateObserver {
  private listeners: StateChangeListener[] = [];

  constructor(private readonly getState: () => AppState) {}

  private isStateChangePredicateOptions(
    propOrOpts: StateChangeArg,
  ): propOrOpts is StateChangePredicateOptions {
    return (
      typeof propOrOpts === "object" &&
      !Array.isArray(propOrOpts) &&
      "predicate" in propOrOpts
    );
  }

  private subscribe(listener: StateChangeListener): UnsubscribeCallback {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(
        (existingListener) => existingListener !== listener,
      );
    };
  }

  private normalize(
    propOrOpts: StateChangeArg,
    callback?: (value: any, appState: AppState) => void,
    opts?: { once: boolean },
  ): NormalizedStateChange {
    let predicate: StateChangeListener["predicate"];
    let getValue: StateChangeListener["getValue"];
    let normalizedCallback = callback;
    let once = opts?.once ?? false;
    let matchesImmediately = false;

    if (this.isStateChangePredicateOptions(propOrOpts)) {
      const {
        predicate: predicateFn,
        callback: callbackFromOpts,
        once: onceFromOpts,
      } = propOrOpts;

      predicate = predicateFn;
      getValue = (appState: AppState) => appState;
      normalizedCallback = callbackFromOpts
        ? (_value: AppState, appState: AppState) => callbackFromOpts(appState)
        : undefined;
      once = onceFromOpts ?? false;
      matchesImmediately = predicateFn(this.getState());
    } else if (typeof propOrOpts === "function") {
      const selector = propOrOpts;
      predicate = (appState: AppState, prevState: AppState) =>
        selector(appState) !== selector(prevState);
      getValue = (appState: AppState) => selector(appState);
    } else if (Array.isArray(propOrOpts)) {
      const keys = propOrOpts;
      predicate = (appState: AppState, prevState: AppState) =>
        keys.some((key) => appState[key] !== prevState[key]);
      getValue = (appState: AppState) => appState;
    } else {
      const key = propOrOpts;
      predicate = (appState: AppState, prevState: AppState) =>
        appState[key] !== prevState[key];
      getValue = (appState: AppState) => appState[key];
    }

    return {
      predicate,
      getValue,
      callback: normalizedCallback,
      once,
      matchesImmediately,
    };
  }

  public onStateChange: OnStateChange = ((
    propOrOpts: StateChangeArg,
    callback?: any,
    opts?: { once: boolean },
  ) => {
    const {
      predicate,
      getValue,
      callback: stateChangeCallback,
      once,
      matchesImmediately,
    } = this.normalize(propOrOpts, callback, opts);

    if (stateChangeCallback) {
      if (matchesImmediately) {
        queueMicrotask(() => {
          const state = this.getState();
          stateChangeCallback(getValue(state), state);
        });
        if (once) {
          return () => {};
        }
      }

      return this.subscribe({
        predicate,
        getValue,
        callback: stateChangeCallback,
        once,
      });
    }

    if (matchesImmediately) {
      return Promise.resolve(getValue(this.getState()));
    }

    return new Promise<any>((resolve) => {
      this.subscribe({
        predicate,
        getValue,
        callback: (value) => resolve(value),
        once: true,
      });
    });
  }) as OnStateChange;

  public flush(prevState: AppState) {
    if (!this.listeners.length) {
      return;
    }

    const state = this.getState();
    const listenersToKeep: StateChangeListener[] = [];

    for (const listener of this.listeners) {
      if (listener.predicate(state, prevState)) {
        listener.callback(listener.getValue(state), state);
        if (!listener.once) {
          listenersToKeep.push(listener);
        }
      } else {
        listenersToKeep.push(listener);
      }
    }

    this.listeners = listenersToKeep;
  }

  public clear() {
    this.listeners = [];
  }
}

import clsx from "clsx";
import React, { useState } from "react";

import { getNameInitial } from "../clients";

import "./Avatar.scss";

type AvatarProps = {
  onClick: (e: React.MouseEvent<HTMLDivElement, MouseEvent>) => void;
  color: string;
  name: string;
  src?: string;
  className?: string;
};

export const Avatar = ({
  color,
  onClick,
  name,
  src,
  className,
}: AvatarProps) => {
  const shortName = getNameInitial(name);
  const [error, setError] = useState(false);
  const loadImg = !error && src;
  const style = loadImg ? undefined : { background: color };
  return (
    <div className={clsx("Avatar", className)} style={style} onClick={onClick}>
      {loadImg ? (
        <img
          className="Avatar-img"
          src={src}
          alt={shortName}
          referrerPolicy="no-referrer"
          onError={() => setError(true)}
        />
      ) : (
        shortName
      )}
    </div>
  );
};

