  topPicks?: readonly string[];
  /** present when the strip is user-customizable — enables the right-click
   * context menu resetting the strip to its default picks */
  onReset?: () => void;
  /** whether custom picks are currently applied (enables the reset item) */
  isCustomized?: boolean;
}

export const TopPicks = ({
  theme,
  onChange,
  type,
  activeColor,
  topPicks,
  onReset,
  isCustomized,
}: TopPicksProps) => {
  const dnd = useColorPickerDnD();
  const dragState = dnd?.dragState ?? null;

  let colors;
  if (type === "elementStroke") {
    colors = DEFAULT_ELEMENT_STROKE_PICKS;
  }

  if (type === "elementBackground") {
    colors = DEFAULT_ELEMENT_BACKGROUND_PICKS;
  }

  if (type === "canvasBackground") {
    colors = DEFAULT_CANVAS_BACKGROUND_PICKS;
  }

  // this one can overwrite defaults
  if (topPicks) {
    colors = topPicks;
  }

  if (!colors) {
    console.error("Invalid type for TopPicks");
    return null;
  }

  return (
    <TopPicksContextMenu
      onReset={onReset}
      isCustomized={!!isCustomized}
      resetLabel={t("colorPicker.resetTopPicks")}
    >
      <div
        className={clsx("color-picker__top-picks top-picks-dnd", {
          "is-dnd-active": !!dragState,
        })}
        ref={dnd?.setStripEl}
      >
        {dragState && <TopPicksDnDOutline />}
        {colors.map((color: string, index: number) => {
          const reorderOffset = getTopPickReorderOffset(dragState, index);
          const displayColor = applyDarkModeFilter(color, theme === THEME.DARK);
          return (
            <button
              className={clsx("color-picker__button top-picks-dnd__pick", {
                active: color === activeColor,
                "is-transparent": color === "transparent" || !color,
                "has-outline": !isColorDark(
                  color,
                  COLOR_OUTLINE_CONTRAST_THRESHOLD,
                ),
                "is-dnd-source":
                  dragState?.origin.kind === "pick" &&
                  dragState.origin.index === index,
                "is-dnd-target":
                  dragState?.origin.kind === "source" &&
                  dragState.overIndex === index,
                "is-dnd-duplicate": dragState?.duplicateIndex === index,
              })}
              style={{
                "--swatch-color": displayColor,
                transform: reorderOffset
                  ? `translateX(${reorderOffset}px)`
                  : undefined,
              }}
              key={color}
              type="button"
              title={color}
              onClick={() => onChange(color)}
              onPointerDown={
                dnd
                  ? (event) => dnd.startPickDrag(event, index, color)
                  : undefined
              }
              data-testid={`color-top-pick-${color}`}
              data-top-pick-index={index}
            >
              <div className="color-picker__button-outline" />
            </button>
          );
        })}
      </div>
    </TopPicksContextMenu>
  );
};

import {
  isTransparent,
  MAX_CUSTOM_COLORS_USED_IN_CANVAS,
} from "@excalidraw/common";

import type { ExcalidrawElement } from "@excalidraw/element/types";

import type { ColorPickerColor, ColorPaletteCustom } from "@excalidraw/common";

import { atom } from "../../editor-jotai";

export const getColorNameAndShadeFromColor = ({
  palette,
  color,
}: {
  palette: ColorPaletteCustom;
  color: string | null;
}): {
  colorName: ColorPickerColor;
  shade: number | null;
} | null => {
  if (!color) {
    return null;
  }
  for (const [colorName, colorVal] of Object.entries(palette)) {
    if (Array.isArray(colorVal)) {
      const shade = colorVal.indexOf(color);
      if (shade > -1) {
        return { colorName: colorName as ColorPickerColor, shade };
      }
    } else if (colorVal === color) {
      return { colorName: colorName as ColorPickerColor, shade: null };
    }
  }
  return null;
};

export const colorPickerHotkeyBindings = [
  ["q", "w", "e", "r", "t"],
  ["a", "s", "d", "f", "g"],
  ["z", "x", "c", "v", "b"],
].flat();

export const isCustomColor = ({
  color,
  palette,
}: {
  color: string;
  palette: ColorPaletteCustom;
}) => {
  const paletteValues = Object.values(palette).flat();
  return !paletteValues.includes(color);
};

export const getMostUsedCustomColors = (
  elements: readonly ExcalidrawElement[],
  type: "elementBackground" | "elementStroke",
  palette: ColorPaletteCustom,
) => {
  const elementColorTypeMap = {
    elementBackground: "backgroundColor",
    elementStroke: "strokeColor",
  };

  const colors = elements.filter((element) => {
    if (element.isDeleted) {
      return false;
    }

    const color =
      element[elementColorTypeMap[type] as "backgroundColor" | "strokeColor"];

    // fully-transparent colors are "no color", not a reusable custom color
    // (matters for palettes that exclude `transparent`, e.g. bucket fill)
    return !isTransparent(color) && isCustomColor({ color, palette });
  });

  const colorCountMap = new Map<string, number>();
  colors.forEach((element) => {
    const color =
      element[elementColorTypeMap[type] as "backgroundColor" | "strokeColor"];
    if (colorCountMap.has(color)) {
      colorCountMap.set(color, colorCountMap.get(color)! + 1);
    } else {
      colorCountMap.set(color, 1);
    }
  });

  return [...colorCountMap.entries()]
    .sort((a, b) => b[1] - a[1])
    .map((c) => c[0])
    .slice(0, MAX_CUSTOM_COLORS_USED_IN_CANVAS);
};

export type ActiveColorPickerSectionAtomType =
