import React, { useState } from "react";

import { t } from "../i18n";

import { useExcalidrawContainer } from "./App";
import { Dialog } from "./Dialog";

export const ErrorDialog = ({
  children,
  onClose,
}: {
  children?: React.ReactNode;
  onClose?: () => void;
}) => {
  const [modalIsShown, setModalIsShown] = useState(!!children);
  const { container: excalidrawContainer } = useExcalidrawContainer();

  const handleClose = React.useCallback(() => {
    setModalIsShown(false);

    if (onClose) {
      onClose();
    }
    // TODO: Fix the A11y issues so this is never needed since we should always focus on last active element
    excalidrawContainer?.focus();
  }, [onClose, excalidrawContainer]);

  return (
    <>
      {modalIsShown && (
        <Dialog
          size="small"
          onCloseRequest={handleClose}
          title={t("errorDialog.title")}
        >
          <div style={{ whiteSpace: "pre-wrap" }}>{children}</div>
        </Dialog>
      )}
    </>
  );
};

import { useEffect, useLayoutEffect, useRef } from "react";
import { createPortal } from "react-dom";

import {
  EVENT,
  isColorDark,
  KEYS,
  MIME_TYPES,
  THEME,
  removeDarkModeFilter,
  rgbToHex,
} from "@excalidraw/common";

import type { ExcalidrawElement } from "@excalidraw/element/types";

import { useUIAppState } from "../context/ui-appState";
import { atom } from "../editor-jotai";
import { useCreatePortalContainer } from "../hooks/useCreatePortalContainer";
import { useOutsideClick } from "../hooks/useOutsideClick";
import { useStable } from "../hooks/useStable";
import { getSelectedElements } from "../scene";

import { useApp, useExcalidrawContainer, useExcalidrawElements } from "./App";
import { eyeDropperIconSvgPaths } from "./icons";
import { positionElementBesideCursor } from "./positionElementBesideCursor";

import "./EyeDropper.scss";

import type { ColorPickerType } from "./ColorPicker/colorPickerUtils";

const eyeDropperCursorPaths = eyeDropperIconSvgPaths
  .map((path, idx) => `<path fill="${idx === 0 ? `#fff` : ``}" d="${path}" />`)
  .join("");
const eyeDropperCursor = `url(data:${MIME_TYPES.svg},${encodeURIComponent(
  `<svg viewBox="0 0 24 24" width="24" height="24" fill="none" xmlns="http://www.w3.org/2000/svg" stroke-linecap="round" stroke-linejoin="round"><g stroke="#fff" stroke-width="5">${eyeDropperCursorPaths}</g><g stroke="#1b1b1f" stroke-width="1.25">${eyeDropperCursorPaths}</g></svg>`,
)}) 2 21, auto`;

export type EyeDropperProperties = {
  keepOpenOnAlt: boolean;
  swapPreviewOnAlt?: boolean;
  /** called when user picks color (on pointerup) */
  onSelect: (color: string, event: PointerEvent) => void;
  /**
   * property of selected elements to update live when alt-dragging.
   * Supply `null` if not applicable (e.g. updating the canvas bg instead of
   * elements)
   **/
  colorPickerType: ColorPickerType;
};

export const activeEyeDropperAtom = atom<null | EyeDropperProperties>(null);

export const EyeDropper: React.FC<{
  onCancel: () => void;
  onSelect: EyeDropperProperties["onSelect"];
  /** called when color changes, on pointerdown for preview */
  onChange: (
    type: ColorPickerType,
    color: string,
    selectedElements: ExcalidrawElement[],
    event: { altKey: boolean },
  ) => void;
  colorPickerType: EyeDropperProperties["colorPickerType"];
}> = ({ onCancel, onChange, onSelect, colorPickerType }) => {
  const eyeDropperContainer = useCreatePortalContainer({
    className: "excalidraw-eye-dropper-backdrop",
    parentSelector: ".excalidraw-eye-dropper-container",
  });
  const appState = useUIAppState();
  const elements = useExcalidrawElements();
  const app = useApp();
  const ownerWindow = app.ownerWindow;

  const selectedElements = getSelectedElements(elements, appState);

  const stableProps = useStable({
    app,
    onCancel,
    onChange,
    onSelect,
    selectedElements,
  });

  const { container: excalidrawContainer } = useExcalidrawContainer();

  useLayoutEffect(() => {
    if (!eyeDropperContainer) {
      return;
    }
    eyeDropperContainer.style.cursor = eyeDropperCursor;
    return () => {
      eyeDropperContainer.style.cursor = "";
    };
  }, [eyeDropperContainer]);

  useEffect(() => {
    const colorPreviewDiv = ref.current;

    if (!colorPreviewDiv || !app.canvas || !eyeDropperContainer) {
      return;
    }

    let isHoldingPointerDown = false;

    const ctx = app.canvas.getContext("2d")!;

    const getCurrentColor = ({
      clientX,
      clientY,
    }: {
      clientX: number;
      clientY: number;
    }) => {
      const pixel = ctx.getImageData(
        (clientX - appState.offsetLeft) * ownerWindow.devicePixelRatio,
        (clientY - appState.offsetTop) * ownerWindow.devicePixelRatio,
        1,
        1,
      ).data;

      return rgbToHex(pixel[0], pixel[1], pixel[2]);
    };

    const getColorToApply = (color: string) =>
      appState.theme === THEME.DARK ? removeDarkModeFilter(color) : color;

    const mouseMoveListener = ({
      clientX,
      clientY,
      altKey,
    }: {
      clientX: number;
      clientY: number;
      altKey: boolean;
    }) => {
      const { top, left } = positionElementBesideCursor({
        cursor: { x: clientX, y: clientY },
        element: {
          width: colorPreviewDiv.offsetWidth,
          height: colorPreviewDiv.offsetHeight,
        },
        container: eyeDropperContainer.getBoundingClientRect(),
        gap: 7,
      });

      colorPreviewDiv.style.top = `${top}px`;
      colorPreviewDiv.style.left = `${left}px`;

      const currentColor = getCurrentColor({ clientX, clientY });

      if (isHoldingPointerDown) {
        stableProps.onChange(
          colorPickerType,
          getColorToApply(currentColor),
          stableProps.selectedElements,
          { altKey },
        );
      }

      colorPreviewDiv.style.background = currentColor;
      colorPreviewDiv.style.setProperty(
        "--eye-dropper-preview-border-color",
        isColorDark(currentColor) ? "#fff" : "#222",
      );
    };

    const onCancel = () => {
      stableProps.onCancel();
    };

    const onSelect: Required<EyeDropperProperties>["onSelect"] = (
      color,
      event,
    ) => {
      stableProps.onSelect(color, event);
    };

    const pointerDownListener = (event: PointerEvent) => {
      isHoldingPointerDown = true;
      // NOTE we can't event.preventDefault() as that would stop
      // pointermove events
      event.stopImmediatePropagation();
    };

    const pointerUpListener = (event: PointerEvent) => {
      isHoldingPointerDown = false;

      // since we're not preventing default on pointerdown, the focus would
      // goes back to `body` so we want to refocus the editor container instead
      excalidrawContainer?.focus();

      event.stopImmediatePropagation();
      event.preventDefault();

      onSelect(getColorToApply(getCurrentColor(event)), event);
    };

    const keyDownListener = (event: KeyboardEvent) => {
      if (event.key === KEYS.ESCAPE) {
        event.preventDefault();
        event.stopImmediatePropagation();
        onCancel();
      }
    };

    // -------------------------------------------------------------------------

    eyeDropperContainer.tabIndex = -1;
    // focus container so we can listen on keydown events
    eyeDropperContainer.focus();

    // init color preview else it would show only after the first mouse move
    mouseMoveListener({
      clientX: stableProps.app.viewport.lastPosition.x,
      clientY: stableProps.app.viewport.lastPosition.y,
      altKey: false,
    });

    eyeDropperContainer.addEventListener(EVENT.KEYDOWN, keyDownListener);
    eyeDropperContainer.addEventListener(
      EVENT.POINTER_DOWN,
      pointerDownListener,
    );
    eyeDropperContainer.addEventListener(EVENT.POINTER_UP, pointerUpListener);
    ownerWindow.addEventListener("pointermove", mouseMoveListener, {
      passive: true,
    });
    ownerWindow.addEventListener(EVENT.BLUR, onCancel);

    return () => {
      isHoldingPointerDown = false;
      eyeDropperContainer.removeEventListener(EVENT.KEYDOWN, keyDownListener);
      eyeDropperContainer.removeEventListener(
        EVENT.POINTER_DOWN,
        pointerDownListener,
      );
      eyeDropperContainer.removeEventListener(
        EVENT.POINTER_UP,
        pointerUpListener,
      );
      ownerWindow.removeEventListener("pointermove", mouseMoveListener);
      ownerWindow.removeEventListener(EVENT.BLUR, onCancel);
    };
  }, [
    stableProps,
    app.canvas,
    eyeDropperContainer,
    colorPickerType,
    excalidrawContainer,
    appState.offsetLeft,
    appState.offsetTop,
    appState.theme,
    ownerWindow,
  ]);

  const ref = useRef<HTMLDivElement>(null);

  useOutsideClick(
    ref,
    () => {
      onCancel();
    },
    (event) => {
      if (
        event.target.closest(
          ".excalidraw-eye-dropper-trigger, .excalidraw-eye-dropper-backdrop",
        )
      ) {
        return true;
      }
      // consider all other clicks as outside
      return false;
    },
  );

  if (!eyeDropperContainer) {
    return null;
  }

  return createPortal(
    <div ref={ref} className="excalidraw-eye-dropper-preview" />,
    eyeDropperContainer,
  );
};

import { useEffect, useState } from "react";

import clsx from "clsx";

import { KEYS, MIME_TYPES } from "@excalidraw/common";

import { useI18n } from "../i18n";

import { useApp, useExcalidrawContainer } from "./App";
import Trans from "./Trans";

import "./FileDropOverlay.scss";

type FileDropState = {
  shiftKey: boolean;
  // "unknown": no MIME type, which is what OS-dragged .excalidraw and
  // .excalidrawlib files both report, so it can be either until dropped
  kind: "scene" | "library" | "unknown";
};

export const FileDropOverlay = () => {
  const app = useApp();
  const { container } = useExcalidrawContainer();
  const { t } = useI18n();
  const [dragState, setDragState] = useState<FileDropState | null>(null);

  useEffect(() => {
    if (!container) {
      return;
    }

    let dragDepth = 0;
    const reset = () => {
      dragDepth = 0;
      setDragState(null);
    };
    const isFileDrag = (event: DragEvent) =>
      Array.from(event.dataTransfer?.types ?? []).includes("Files");

    const update = (event: DragEvent) => {
      const files = Array.from(event.dataTransfer?.items ?? []).filter(
        (item) => item.kind === "file",
      );
      // Filenames are protected until drop, so .excalidraw.png/.svg exports
      // cannot be distinguished here. Keep the canvas visible for all images.
      if (files.some((file) => file.type.startsWith("image/"))) {
        setDragState(null);
        return;
      }

      const type = files[0]?.type;
      const kind: FileDropState["kind"] =
        type === MIME_TYPES.excalidrawlib
          ? "library"
          : type
          ? "scene"
          : "unknown";

      setDragState((previous) =>
        previous?.shiftKey === event.shiftKey && previous.kind === kind
          ? previous
          : { shiftKey: event.shiftKey, kind },
      );
    };
    const onDragEnter = (event: DragEvent) => {
      if (isFileDrag(event)) {
        dragDepth++;
        update(event);
      }
    };
    const onDragOver = (event: DragEvent) => {
      // App's own dragover listener already calls preventDefault()
      if (isFileDrag(event)) {
        // Shift defaults the drag to "move" (and its cursor), but we only
        // ever copy the file in
        if (event.dataTransfer) {
          event.dataTransfer.dropEffect = "copy";
        }
        dragDepth = Math.max(1, dragDepth);
        update(event);
      }
    };
    const onDragLeave = () => {
      dragDepth = Math.max(0, dragDepth - 1);
      if (!dragDepth) {
        reset();
      }
    };
    const onKeyChange = (event: KeyboardEvent) => {
      if (event.key === KEYS.ESCAPE) {
        reset();
      } else if (event.key === "Shift") {
        setDragState((previous) =>
          previous ? { ...previous, shiftKey: event.shiftKey } : previous,
        );
      }
    };

    container.addEventListener("dragenter", onDragEnter);
    container.addEventListener("dragover", onDragOver);
    container.addEventListener("dragleave", onDragLeave);
    app.ownerDocument.addEventListener("drop", reset, true);
    app.ownerDocument.addEventListener("dragend", reset, true);
    app.ownerDocument.addEventListener("keydown", onKeyChange, true);
    app.ownerDocument.addEventListener("keyup", onKeyChange, true);
    app.ownerWindow.addEventListener("blur", reset);

    return () => {
      container.removeEventListener("dragenter", onDragEnter);
      container.removeEventListener("dragover", onDragOver);
      container.removeEventListener("dragleave", onDragLeave);
      app.ownerDocument.removeEventListener("drop", reset, true);
      app.ownerDocument.removeEventListener("dragend", reset, true);
      app.ownerDocument.removeEventListener("keydown", onKeyChange, true);
      app.ownerDocument.removeEventListener("keyup", onKeyChange, true);
      app.ownerWindow.removeEventListener("blur", reset);
    };
  }, [app, container]);

  if (!dragState) {
    return null;
  }

  const keepsContent = dragState.shiftKey || dragState.kind === "library";

  return (
    <div
      className={clsx("file-drop-overlay", {
        "file-drop-overlay--keep": keepsContent,
      })}
    >
      <div className="file-drop-overlay__card">
        <div role="status" aria-live="polite" aria-atomic="true">
          <div className="file-drop-overlay__title">
            {t(
              dragState.kind === "library"
                ? "fileDrop.importLibrary"
                : dragState.shiftKey
                ? "fileDrop.add"
                : "fileDrop.replace",
            )}
          </div>
          <div className="file-drop-overlay__hint">
            {keepsContent ? (
              t("fileDrop.keepHint")
            ) : (
              <Trans
                i18nKey="fileDrop.replaceHint"
                shift={(children) => <kbd>{children}</kbd>}
              />
            )}
          </div>
          {dragState.kind === "unknown" && (
            <div className="file-drop-overlay__hint file-drop-overlay__hint--secondary">
              ({t("fileDrop.libraryHint")})
            </div>
          )}
        </div>
        <div className="file-drop-overlay__illustration" aria-hidden="true">
          {(["back", "front"] as const).map((position) => (
            <svg
              key={position}
              className={`file-drop-overlay__file file-drop-overlay__file--${position}`}
              viewBox="0 0 100 128"
              fill="none"
            >
              <path
                className="file-drop-overlay__paper"
                d="M16 3h43l28 28v81c0 7-4 12-12 12H16c-8 0-12-5-12-12V15C4 7 8 3 16 3Z"
              />
              <path d="M59 3v20c0 6 3 8 9 8h19" />
              <path
                className="file-drop-overlay__lines"
                d="M24 61h43M24 77h43M24 93h26"
              />
              {position === "back" && (
                <path
                  className="file-drop-overlay__cross"
                  d="M18 44l24 24M42 44L18 68"
                />
              )}
            </svg>
          ))}
        </div>
      </div>
    </div>
  );
};

import clsx from "clsx";
import React, { forwardRef, useState } from "react";

import { isPromiseLike } from "@excalidraw/common";

import { AbortError } from "../errors";

import Spinner from "./Spinner";
import { tablerCheckIcon } from "./icons";

import "./FilledButton.scss";

export type ButtonVariant = "filled" | "outlined" | "icon";
export type ButtonColor =
  | "primary"
  | "danger"
  | "warning"
  | "muted"
  | "success";
export type ButtonSize = "medium" | "large";

export type FilledButtonProps = {
  label?: string;

  children?: React.ReactNode;
  onClick?: (event: React.MouseEvent) => void;
  status?: null | "loading" | "success";

  variant?: ButtonVariant;
  color?: ButtonColor;
  size?: ButtonSize;
  className?: string;
  fullWidth?: boolean;

  icon?: React.ReactNode;
  disabled?: boolean;
};

export const FilledButton = forwardRef<HTMLButtonElement, FilledButtonProps>(
  (
    {
      children,
      icon,
      onClick,
      label,
      variant = "filled",
      color = "primary",
      size = "medium",
      fullWidth,
      className,
      status,
      disabled,
    },
    ref,
  ) => {
    const [isLoading, setIsLoading] = useState(false);

    const _onClick = async (event: React.MouseEvent) => {
      const ret = onClick?.(event);

      if (isPromiseLike(ret)) {
        // delay loading state to prevent flicker in case of quick response
        const timer = window.setTimeout(() => {
          setIsLoading(true);
        }, 50);
        try {
          await ret;
        } catch (error: any) {
          if (!(error instanceof AbortError)) {
            throw error;
          } else {
            console.warn(error);
          }
        } finally {
          clearTimeout(timer);
          setIsLoading(false);
        }
      }
    };

    const _status = isLoading ? "loading" : status;
    color = _status === "success" ? "success" : color;

    return (
      <button
        className={clsx(
          "ExcButton",
          `ExcButton--color-${color}`,
          `ExcButton--variant-${variant}`,
          `ExcButton--size-${size}`,
          `ExcButton--status-${_status}`,
          { "ExcButton--fullWidth": fullWidth },
          className,
        )}
        onClick={_onClick}
        type="button"
        aria-label={label}
        ref={ref}
        disabled={disabled || _status === "loading" || _status === "success"}
      >
        <div className="ExcButton__contents">
          {_status === "loading" ? (
            <Spinner className="ExcButton__statusIcon" />
          ) : (
            _status === "success" && (
              <div className="ExcButton__statusIcon">{tablerCheckIcon}</div>
            )
          )}
          {icon && (
            <div className="ExcButton__icon" aria-hidden>
              {icon}
            </div>
          )}
          {variant !== "icon" && (children ?? label)}
        </div>
      </button>
    );
  },
);

import React from "react";
import clsx from "clsx";

import "./FixedSideContainer.scss";

type FixedSideContainerProps = {
  children: React.ReactNode;
