const MERMAID_SYNTAX_ERROR_LINE = /(?:Parse|Lexical) error on line (\d+)[.:]/i;
const MERMAID_INACTIVE_PARTICIPANT_ERROR =
  /Trying to inactivate an inactive participant \((.+)\)/i;
const MERMAID_CARET_LINE = /^\s*-+\^\s*$/;

export const isMermaidParseSyntaxError = (message: string) =>
  MERMAID_SYNTAX_ERROR_LINE.test(message);

export const isMermaidAutoFixableError = (message: string) =>
  isMermaidParseSyntaxError(message) ||
  MERMAID_INACTIVE_PARTICIPANT_ERROR.test(message);

export const isMermaidCaretLine = (line: string) =>
  MERMAID_CARET_LINE.test(line);

export const getMermaidInactiveParticipant = (
  message: string,
): string | null => {
  const match = message.match(MERMAID_INACTIVE_PARTICIPANT_ERROR);
  if (!match?.[1]) {
    return null;
  }
  return match[1].trim();
};

const escapeRegExp = (value: string) =>
  value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

const getInactiveParticipantLineNumber = (
  message: string,
  sourceText: string,
): number | null => {
  const participant = getMermaidInactiveParticipant(message);
  if (!participant) {
    return null;
  }

  const deactivatePattern = new RegExp(
    `^\\s*deactivate\\s+${escapeRegExp(participant)}(?:\\s+%%.*)?\\s*$`,
  );
  const lines = sourceText.split(/\r?\n/);
  for (let index = lines.length - 1; index >= 0; index--) {
    if (deactivatePattern.test(lines[index])) {
      return index + 1;
    }
  }
  return null;
};

export const getMermaidErrorLineNumber = (
  message: string,
  sourceText?: string,
): number | null => {
  const match = message.match(MERMAID_SYNTAX_ERROR_LINE);
  if (!match) {
    if (!sourceText) {
      return null;
    }
    return getInactiveParticipantLineNumber(message, sourceText);
  }
  return Number.parseInt(match[1], 10);
};

const countMatches = (text: string, re: RegExp) =>
  (text.match(re) || []).length;

export const getMermaidSyntaxErrorGuidance = (
  message: string,
  sourceText?: string,
): { summary: string; likelyCauses: string[] } | null => {
  if (!isMermaidParseSyntaxError(message)) {
    return null;
  }

  const errorLine = getMermaidErrorLineNumber(message, sourceText);
  const summary = errorLine
    ? `Syntax error near line ${errorLine}.`
    : "Syntax error in Mermaid diagram.";

  const likelyCauses: string[] = [];

  if (sourceText) {
    const openBrackets = countMatches(sourceText, /\[/g);
    const closeBrackets = countMatches(sourceText, /\]/g);
    if (openBrackets !== closeBrackets) {
      likelyCauses.push("Unbalanced square brackets in a node label.");
    }

    const openParens = countMatches(sourceText, /\(/g);
    const closeParens = countMatches(sourceText, /\)/g);
    if (openParens !== closeParens) {
      likelyCauses.push("Unbalanced parentheses in a node shape.");
    }

    const openBraces = countMatches(sourceText, /\{/g);
    const closeBraces = countMatches(sourceText, /\}/g);
    if (openBraces !== closeBraces) {
      likelyCauses.push("Unbalanced braces in a decision node.");
    }

    const subgraphCount = countMatches(sourceText, /^\s*subgraph\b/gm);
    const endCount = countMatches(sourceText, /^\s*end\s*$/gm);
    if (subgraphCount > endCount) {
      likelyCauses.push("A block is missing an `end` statement.");
    }
  }

  if (/got 'NODE_STRING'/.test(message) || /got 'PS'/.test(message)) {
    likelyCauses.push(
      "An extra character/token may appear after a node or label definition.",
    );
  }

  if (likelyCauses.length === 0) {
    likelyCauses.push(
      "A node or edge line is malformed (missing/extra delimiters).",
    );
    likelyCauses.push("A block (`subgraph`, `class`, etc.) may be incomplete.");
  }

  return {
    summary,
    likelyCauses: [...new Set(likelyCauses)],
  };
};

export const formatMermaidParseErrorMessage = (message: string) => {
  if (!isMermaidParseSyntaxError(message)) {
    return message;
  }

  return message.replace(/\n\s*Expecting[\s\S]*$/, "").trimEnd();
};

import { isValidMermaidSyntax } from "./mermaidValidation";

describe("isValidMermaidSyntax", () => {
  describe("empty and whitespace content", () => {
    it("should return false for empty string", () => {
      expect(isValidMermaidSyntax("")).toBe(false);
    });

    it("should return false for whitespace-only content", () => {
      expect(isValidMermaidSyntax("   ")).toBe(false);
      expect(isValidMermaidSyntax("\n\n")).toBe(false);
      expect(isValidMermaidSyntax("\t\t")).toBe(false);
    });
  });

  describe("balanced brackets, braces, and parentheses", () => {
    it("should return true for content with balanced brackets", () => {
      expect(isValidMermaidSyntax("flowchart LR\nA[Start]")).toBe(true);
      expect(isValidMermaidSyntax("A[Node] --> B[End]")).toBe(true);
      expect(isValidMermaidSyntax("[[nested]]")).toBe(true);
    });

    it("should return true for content with balanced braces", () => {
      expect(isValidMermaidSyntax("graph TD\nA{Decision}")).toBe(true);
      expect(isValidMermaidSyntax("{{nested}}")).toBe(true);
    });

    it("should return true for content with balanced parentheses", () => {
      expect(isValidMermaidSyntax("flowchart LR\nA(Round)")).toBe(true);
      expect(isValidMermaidSyntax("((nested))")).toBe(true);
    });

    it("should return true for content with multiple balanced delimiters", () => {
      expect(isValidMermaidSyntax("A[Node] --> B{Decision} --> C(End)")).toBe(
        true,
      );
      expect(
        isValidMermaidSyntax("flowchart\nA[Start] --> B{Check} --> C(Done)"),
      ).toBe(true);
    });
  });

  describe("unbalanced brackets", () => {
    it("should return false for single unclosed bracket", () => {
      expect(isValidMermaidSyntax("flowchart LR\nA[Start")).toBe(false);
      expect(isValidMermaidSyntax("A[Node")).toBe(false);
    });

    it("should return false for multiple unclosed brackets", () => {
      expect(isValidMermaidSyntax("A[Node\nB[Another")).toBe(false);
      expect(isValidMermaidSyntax("[[[text")).toBe(false);
    });

    it("should return false when closing brackets outnumber opening brackets", () => {
      expect(isValidMermaidSyntax("A]")).toBe(false);
      expect(isValidMermaidSyntax("text]]]")).toBe(false);
    });
  });

  describe("unbalanced braces", () => {
    it("should return false for single unclosed brace", () => {
      expect(isValidMermaidSyntax("graph TD\nA{Decision")).toBe(false);
      expect(isValidMermaidSyntax("A{Node")).toBe(false);
    });

    it("should return false for multiple unclosed braces", () => {
      expect(isValidMermaidSyntax("A{Node\nB{Another")).toBe(false);
      expect(isValidMermaidSyntax("{{{text")).toBe(false);
    });

    it("should return false when closing braces outnumber opening braces", () => {
      expect(isValidMermaidSyntax("A}")).toBe(false);
      expect(isValidMermaidSyntax("text}}}")).toBe(false);
    });
  });

  describe("unbalanced parentheses", () => {
    it("should return false for single unclosed parenthesis", () => {
      expect(isValidMermaidSyntax("flowchart LR\nA(Round")).toBe(false);
      expect(isValidMermaidSyntax("A(Node")).toBe(false);
    });

    it("should return false for multiple unclosed parentheses", () => {
      expect(isValidMermaidSyntax("A(Node\nB(Another")).toBe(false);
      expect(isValidMermaidSyntax("(((text")).toBe(false);
    });

    it("should return false when closing parentheses outnumber opening parentheses", () => {
      expect(isValidMermaidSyntax("A)")).toBe(false);
      expect(isValidMermaidSyntax("text)))")).toBe(false);
    });
  });

  describe("incomplete patterns at end of line", () => {
    it("should return false for arrow patterns", () => {
      expect(isValidMermaidSyntax("A -->")).toBe(false);
      expect(isValidMermaidSyntax("flowchart LR\nA --")).toBe(false);
      expect(isValidMermaidSyntax("B --.")).toBe(false);
      expect(isValidMermaidSyntax("C ==>")).toBe(false);
      expect(isValidMermaidSyntax("D ==")).toBe(false);
      expect(isValidMermaidSyntax("E ~~")).toBe(false);
    });

    it("should return false for colon patterns", () => {
      expect(isValidMermaidSyntax("A::")).toBe(false);
      expect(isValidMermaidSyntax("B:")).toBe(false);
    });

    it("should return false for pipe and ampersand patterns", () => {
      expect(isValidMermaidSyntax("A|")).toBe(false);
      expect(isValidMermaidSyntax("B&")).toBe(false);
    });

    it("should return true when incomplete patterns are not at the end", () => {
      expect(isValidMermaidSyntax("A --> B")).toBe(true);
      expect(isValidMermaidSyntax("A -- text --> B")).toBe(true);
      expect(isValidMermaidSyntax("A: complete")).toBe(true);
      expect(isValidMermaidSyntax("A & B")).toBe(true);
      expect(isValidMermaidSyntax("A | B")).toBe(true);
    });

    it("should only check the last line for incomplete patterns", () => {
      expect(isValidMermaidSyntax("A -->\nB --> C")).toBe(true);
      expect(isValidMermaidSyntax("A:\nB --> C")).toBe(true);
    });
  });

  describe("complex real-world scenarios", () => {
    it("should return true for valid flowchart", () => {
      const mermaid = `flowchart TD
    Start[Start] --> Decision{Is it?}
    Decision -->|Yes| End1[End 1]
    Decision -->|No| End2[End 2]`;
      expect(isValidMermaidSyntax(mermaid)).toBe(true);
    });

    it("should return true for valid sequence diagram", () => {
      const mermaid = `sequenceDiagram
    Alice->>John: Hello John
    John-->>Alice: Great!`;
      expect(isValidMermaidSyntax(mermaid)).toBe(true);
    });

    it("should return false for incomplete flowchart (unclosed bracket)", () => {
      const mermaid = `flowchart TD
    Start[Start --> Decision{Is it?}
    Decision -->|Yes| End[End]`;
      expect(isValidMermaidSyntax(mermaid)).toBe(false);
    });

    it("should return false for flowchart with incomplete arrow at end", () => {
      const mermaid = `flowchart TD
    Start[Start] --> Decision{Is it?}
    Decision -->`;
      expect(isValidMermaidSyntax(mermaid)).toBe(false);
    });

    it("should return true for diagram with multiple node types", () => {
      const mermaid = `graph LR
    A[Square] --> B(Round)
    B --> C{Diamond}
    C --> D[Square]`;
      expect(isValidMermaidSyntax(mermaid)).toBe(true);
    });

    it("should return false for streaming content that is incomplete", () => {
      // Simulates partial AI-generated content during streaming
      expect(isValidMermaidSyntax("flowchart LR\nA[Start] --")).toBe(false);
      expect(isValidMermaidSyntax("flowchart LR\nA[Start")).toBe(false);
      expect(isValidMermaidSyntax("graph TD\nA{Decision")).toBe(false);
    });

    it("should return true for complete multi-line diagram", () => {
      const mermaid = `graph TB
    subgraph one
      a1[First]
    end
    subgraph two
      a2[Second]
    end
    a1 --> a2`;
      expect(isValidMermaidSyntax(mermaid)).toBe(true);
    });
  });

  describe("edge cases", () => {
    it("should handle content with only delimiters", () => {
      expect(isValidMermaidSyntax("[]")).toBe(true);
      expect(isValidMermaidSyntax("{}")).toBe(true);
      expect(isValidMermaidSyntax("()")).toBe(true);
      expect(isValidMermaidSyntax("[")).toBe(false);
      expect(isValidMermaidSyntax("{")).toBe(false);
      expect(isValidMermaidSyntax("(")).toBe(false);
    });

    it("should handle mixed valid and invalid scenarios", () => {
      expect(isValidMermaidSyntax("A[B] -->")).toBe(false);
      expect(isValidMermaidSyntax("A[B --")).toBe(false);
      expect(isValidMermaidSyntax("A{B:")).toBe(false);
    });

    it("should handle strings with special characters", () => {
      expect(isValidMermaidSyntax("A[Node with spaces]")).toBe(true);
      expect(
        isValidMermaidSyntax("A[Node with 'quotes' and numbers 123]"),
      ).toBe(true);
    });

    it("should trim content before validation", () => {
      expect(isValidMermaidSyntax("  A[Node]  \n")).toBe(true);
      expect(isValidMermaidSyntax("\n\nA[Node]\n\n")).toBe(true);
    });
  });
});

export const isValidMermaidSyntax = (content: string): boolean => {
  const trimmed = content.trim();
  if (!trimmed) {
    return false;
  }

  const openBrackets = (trimmed.match(/\[/g) || []).length;
  const closeBrackets = (trimmed.match(/\]/g) || []).length;
  const openBraces = (trimmed.match(/\{/g) || []).length;
  const closeBraces = (trimmed.match(/\}/g) || []).length;
  const openParens = (trimmed.match(/\(/g) || []).length;
  const closeParens = (trimmed.match(/\)/g) || []).length;

  if (
    openBrackets !== closeBrackets ||
    openBraces !== closeBraces ||
    openParens !== closeParens
  ) {
    return false;
  }

  const lastLine = trimmed.split("\n").pop()?.trim() || "";
  const incompletePatterns = [
    /-->$/,
    /--$/,
    /-\.$/,
    /==>$/,
    /==$/,
    /~~$/,
    /::$/,
    /:$/,
    /\|$/,
    /&$/,
  ];

  if (incompletePatterns.some((pattern) => pattern.test(lastLine))) {
    return false;
  }

  return true;
};

import clsx from "clsx";
import {
  forwardRef,
  useRef,
  useImperativeHandle,
  useLayoutEffect,
  useState,
} from "react";

import { Button } from "./Button";
import { eyeIcon, eyeClosedIcon } from "./icons";

import "./TextField.scss";

import type { KeyboardEvent } from "react";

type TextFieldProps = {
  onChange?: (value: string) => void;
  onClick?: () => void;
  onKeyDown?: (event: KeyboardEvent<HTMLInputElement>) => void;

  readonly?: boolean;
  fullWidth?: boolean;
  selectOnRender?: boolean;

  icon?: React.ReactNode;
  label?: string;
  className?: string;
  placeholder?: string;
  isRedacted?: boolean;
  type?: "text" | "search";
} & ({ value: string } | { defaultValue: string });

export const TextField = forwardRef<HTMLInputElement, TextFieldProps>(
  (
    {
      onChange,
      label,
      fullWidth,
      placeholder,
      readonly,
      selectOnRender,
      onKeyDown,
      isRedacted = false,
      icon,
      className,
      type,
      ...rest
    },
    ref,
  ) => {
    const innerRef = useRef<HTMLInputElement | null>(null);

    useImperativeHandle(ref, () => innerRef.current!);

    useLayoutEffect(() => {
      if (selectOnRender) {
        // focusing first is needed because vitest/jsdom
        innerRef.current?.focus();
        innerRef.current?.select();
      }
    }, [selectOnRender]);

    const [isTemporarilyUnredacted, setIsTemporarilyUnredacted] =
      useState<boolean>(false);

    return (
      <div
        className={clsx("ExcTextField", className, {
          "ExcTextField--fullWidth": fullWidth,
          "ExcTextField--hasIcon": !!icon,
        })}
        onClick={() => {
          innerRef.current?.focus();
        }}
      >
        {icon}
        {label && <div className="ExcTextField__label">{label}</div>}
        <div
          className={clsx("ExcTextField__input", {
            "ExcTextField__input--readonly": readonly,
          })}
        >
          <input
            className={clsx({
              "is-redacted":
                "value" in rest &&
                rest.value &&
                isRedacted &&
                !isTemporarilyUnredacted,
            })}
            readOnly={readonly}
            value={"value" in rest ? rest.value : undefined}
            defaultValue={
              "defaultValue" in rest ? rest.defaultValue : undefined
            }
            placeholder={placeholder}
            ref={innerRef}
            onChange={(event) => onChange?.(event.target.value)}
            onKeyDown={onKeyDown}
            type={type}
          />
          {isRedacted && (
            <Button
              onSelect={() =>
                setIsTemporarilyUnredacted(!isTemporarilyUnredacted)
              }
              style={{ border: 0, userSelect: "none" }}
            >
              {isTemporarilyUnredacted ? eyeClosedIcon : eyeIcon}
            </Button>
          )}
        </div>
      </div>
    );
  },
);

import { useCallback, useEffect, useRef } from "react";

import { CloseIcon } from "./icons";
import { IconButton } from "./IconButton";

import "./Toast.scss";

import type { CSSProperties, ReactNode } from "react";

const DEFAULT_TOAST_TIMEOUT = 5000;

const ProgressBar = ({ progress }: { progress: number }) => (
  <div className="Toast__progress-bar">
    <div
      className="Toast__progress-bar-fill"
      style={{
        width: `${Math.min(5, Math.round(progress * 100))}%`,
      }}
    />
  </div>
);

const ToastComponent = ({
  message,
  onClose,
  closable = false,
  // To prevent autoclose, pass duration as Infinity
  duration = DEFAULT_TOAST_TIMEOUT,
  style,
}: {
  message: ReactNode;
  onClose: () => void;
  closable?: boolean;
  duration?: number;
  style?: CSSProperties;
}) => {
  const timerRef = useRef<number>(0);
  const shouldAutoClose = duration !== Infinity;
  const scheduleTimeout = useCallback(() => {
    if (!shouldAutoClose) {
      return;
    }
    timerRef.current = window.setTimeout(() => onClose(), duration);
  }, [onClose, duration, shouldAutoClose]);

  useEffect(() => {
    if (!shouldAutoClose) {
      return;
    }
    scheduleTimeout();
    return () => clearTimeout(timerRef.current);
  }, [scheduleTimeout, message, duration, shouldAutoClose]);

  const onMouseEnter = shouldAutoClose
    ? () => clearTimeout(timerRef?.current)
    : undefined;
  const onMouseLeave = shouldAutoClose ? scheduleTimeout : undefined;
  return (
    <div
      className="Toast"
      role="status"
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      style={style}
    >
      <div className="Toast__message">{message}</div>
      {closable && (
        <IconButton
          icon={CloseIcon}
          aria-label="close"
          type="icon"
          onClick={onClose}
          className="close"
        />
      )}
    </div>
  );
};

export const Toast = Object.assign(ToastComponent, { ProgressBar });

import React, { useEffect, useState } from "react";
import clsx from "clsx";

import { capitalizeString } from "@excalidraw/common";

import { Popover } from "radix-ui";

import { trackEvent } from "../analytics";

import { IconButton } from "./IconButton";
import { isToolButtonDisabled } from "./Tools";

import "./ToolPopover.scss";

import { useExcalidrawContainer } from "./App";

import type { AppClassProperties } from "../types";

type ToolOption = {
  type: string;
  icon: React.ReactNode;
  title: string;
  fillable?: boolean;
};

type ToolPopoverProps = {
  app: AppClassProperties;
  options: readonly ToolOption[];
  activeTool: { type: string };
  defaultOption: string;
  "data-testid": string;
  onToolChange: (type: string) => void;
  displayedOption: ToolOption;
};

export const ToolPopover = ({
  app,
  options,
  activeTool,
  defaultOption,
  "data-testid": dataTestId,
  onToolChange,
  displayedOption,
}: ToolPopoverProps) => {
  const [isPopupOpen, setIsPopupOpen] = useState(false);
  const currentType = activeTool.type;
  const isActive = displayedOption.type === currentType;
  const SIDE_OFFSET = 16;
  const { container } = useExcalidrawContainer();

  // if currentType is not in options, close popup
  if (!options.some((o) => o.type === currentType) && isPopupOpen) {
    setIsPopupOpen(false);
  }

  // Close popover when user starts interacting with the canvas (pointer down)
  useEffect(() => {
    // app.onPointerDownEmitter emits when pointer down happens on canvas area
    const unsubscribe = app.onPointerDownEmitter.on(() => {
      setIsPopupOpen(false);
    });
    return () => unsubscribe?.();
  }, [app]);

  return (
    <Popover.Root open={isPopupOpen}>
      <Popover.Trigger asChild>
        <IconButton
          className={clsx({ fillable: displayedOption.fillable })}
          type="toggle"
          icon={displayedOption.icon}
          checked={isActive}
          disabled={options.every((option) =>
            isToolButtonDisabled(app, option.type),
          )}
          title={capitalizeString(displayedOption.title)}
          aria-label={capitalizeString(displayedOption.title)}
          data-testid={dataTestId}
          onSelect={() => {
            setIsPopupOpen((v) => !v);
            onToolChange(defaultOption);
          }}
        />
      </Popover.Trigger>

      <Popover.Content
        className="tool-popover-content"
        sideOffset={SIDE_OFFSET}
        collisionBoundary={container ?? undefined}
      >
        {options.map(({ type, icon, title, fillable }) => (
          <IconButton
            className={clsx({ fillable })}
            key={type}
            type="toggle"
            icon={icon}
            checked={currentType === type}
            disabled={isToolButtonDisabled(app, type)}
            title={capitalizeString(type)}
            aria-label={capitalizeString(type)}
            data-testid={`toolbar-${type}`}
            onSelect={() => {
              if (app.state.activeTool.type !== type) {
                trackEvent("toolbar", type, "ui");
                app.setActiveTool({ type: type as any });
                onToolChange?.(type);
              }
            }}
          />
        ))}
      </Popover.Content>
    </Popover.Root>
  );
};

