                  </fieldset>
                )}
            </DropdownMenu.Content>
          </DropdownMenu>
        </MainMenuTunnel.In>
      );
    },
  ),
  {
    Trigger: DropdownMenu.Trigger,
    Item: DropdownMenu.Item,
    ItemLink: DropdownMenu.ItemLink,
    ItemCustom: DropdownMenu.ItemCustom,
    Group: DropdownMenu.Group,
    Separator: DropdownMenu.Separator,
    Sub: DropdownMenuSub,
    DefaultItems,
  },
);

export default MainMenu;

import { positionElementBesideCursor } from "./positionElementBesideCursor";

const element = {
  width: 48,
  height: 48,
};

const container = {
  left: 100,
  top: 50,
  width: 400,
  height: 300,
};

describe("positionElementBesideCursor", () => {
  it("positions the element after the cursor when it fits", () => {
    expect(
      positionElementBesideCursor({
        cursor: { x: 200, y: 100 },
        element,
        container,
        gap: 20,
      }),
    ).toEqual({ left: 120, top: 70 });
  });

  it("flips an overflowing element to the other side of the cursor", () => {
    expect(
      positionElementBesideCursor({
        cursor: { x: 480, y: 330 },
        element,
        container,
        gap: 20,
      }),
    ).toEqual({ left: 312, top: 212 });
  });

  it("keeps a flipped element within the container", () => {
    expect(
      positionElementBesideCursor({
        cursor: { x: 160, y: 90 },
        element,
        container: { left: 100, top: 50, width: 100, height: 80 },
        gap: 20,
      }),
    ).toEqual({ left: 0, top: 0 });
  });

  it("pins an oversized element to the container origin", () => {
    expect(
      positionElementBesideCursor({
        cursor: { x: 130, y: 80 },
        element,
        container: { left: 100, top: 50, width: 40, height: 40 },
        gap: 0,
      }),
    ).toEqual({ left: 0, top: 0 });
  });
});

import { clamp } from "@excalidraw/math";

const positionAxis = ({
  cursorPosition,
  elementSize,
  containerSize,
  gap,
}: {
  cursorPosition: number;
  elementSize: number;
  containerSize: number;
  gap: number;
}) => {
  // flip to the other side of the cursor when overflowing the container
  const position =
    cursorPosition + gap + elementSize > containerSize
      ? cursorPosition - gap - elementSize
      : cursorPosition + gap;

  // If the element does not fit on either side, keep as much of it within the
  // container as possible.
  return clamp(position, 0, Math.max(0, containerSize - elementSize));
};

/**
 * Positions an element beside a cursor within a container, flipping the
 * element to the other side of the cursor when it would overflow the
 * container, resolved independently on each axis.
 *
 * Takes the cursor in client (viewport) coordinates and returns
 * container-local coordinates.
 */
export const positionElementBesideCursor = ({
  cursor,
  element,
  container,
  gap,
}: {
  /** client (viewport) coordinates */
  cursor: {
    x: number;
    y: number;
  };
  element: {
    width: number;
    height: number;
  };
  /** the container's bounding client rect */
  container: Pick<DOMRect, "left" | "top" | "width" | "height">;
  /** distance between the cursor and the positioned element */
  gap: number;
}) => ({
  left: positionAxis({
    cursorPosition: cursor.x - container.left,
    elementSize: element.width,
    containerSize: container.width,
    gap,
  }),
  top: positionAxis({
    cursorPosition: cursor.y - container.top,
    elementSize: element.height,
    containerSize: container.height,
    gap,
  }),
});

