/**
 * @param func handler taking at most single parameter (event).
 */

import { version as ReactVersion } from "react";
import { unstable_batchedUpdates } from "react-dom";

import { throttleRAF } from "@excalidraw/common";

export const withBatchedUpdates = <
  TFunction extends ((event: any) => void) | (() => void),
>(
  func: Parameters<TFunction>["length"] extends 0 | 1 ? TFunction : never,
) =>
  ((event) => {
    unstable_batchedUpdates(func as TFunction, event);
  }) as TFunction;

/**
 * barches React state updates and throttles the calls to a single call per
 * animation frame
 */
export const withBatchedUpdatesThrottled = <
  TFunction extends ((event: any) => void) | (() => void),
>(
  func: Parameters<TFunction>["length"] extends 0 | 1 ? TFunction : never,
) => {
  // @ts-ignore
  return throttleRAF<Parameters<TFunction>>(((event) => {
    unstable_batchedUpdates(func, event);
  }) as TFunction);
};

export const isRenderThrottlingEnabled = (() => {
  // we don't want to throttle in react < 18 because of #5439 and it was
  // getting more complex to maintain the fix
  let IS_REACT_18_AND_UP: boolean;
  try {
    const version = ReactVersion.split(".");
    IS_REACT_18_AND_UP = Number(version[0]) > 17;
  } catch {
    IS_REACT_18_AND_UP = false;
  }

  let hasWarned = false;

  return () => {
    if (window.EXCALIDRAW_THROTTLE_RENDER === true) {
      if (!IS_REACT_18_AND_UP) {
        if (!hasWarned) {
          hasWarned = true;
          console.warn(
            "Excalidraw: render throttling is disabled on React versions < 18.",
          );
        }
        return false;
      }
      return true;
    }
    return false;
  };
})();

import { clamp } from "@excalidraw/math";

import type {
  ElementRenderOffsets,
  ElementRenderOverride,
  ElementRenderOverrides,
} from "./types";

/** Validate and copy before publishing, so a rejected snapshot changes nothing. */
export const copyElementRenderOverrides = (
  overrides: ElementRenderOverrides | null,
): ElementRenderOverrides => {
  const copy = new Map<string, ElementRenderOverride>();
  for (const [id, value] of overrides ?? []) {
    const { opacity, offset } = value;
    if (
      (opacity !== undefined && !Number.isFinite(opacity)) ||
      (offset !== undefined &&
        (offset === null ||
          !Number.isFinite(offset.x) ||
          !Number.isFinite(offset.y)))
    ) {
      throw new TypeError(`Render overrides for ${id} must be finite numbers`);
    }
    if (opacity === undefined && offset === undefined) {
      continue;
    }
    copy.set(id, {
      ...(opacity !== undefined ? { opacity: clamp(opacity, 0, 100) } : {}),
      ...(offset ? { offset: { x: offset.x, y: offset.y } } : {}),
    });
  }
  return copy;
};

/**
 * Extracts the offsets of a snapshot, returning `previous` when they are the
 * same. Visibility is memoized on this map's identity, so a snapshot that only
 * changes opacities (a fade) never re-runs viewport geometry.
 */
export const getElementRenderOffsets = (
  overrides: ElementRenderOverrides,
  previous: ElementRenderOffsets,
): ElementRenderOffsets => {
  // Compare before allocating: fades can carry many unchanged offsets.
  let offsetCount = 0;
  let changed = false;
  for (const [id, { offset }] of overrides) {
    if (!offset) {
      continue;
    }
    offsetCount++;
    const before = previous.get(id);
    if (!before || before.x !== offset.x || before.y !== offset.y) {
      changed = true;
      break;
    }
  }
  if (!changed && offsetCount === previous.size) {
    return previous;
  }

  const next = new Map<string, NonNullable<ElementRenderOverride["offset"]>>();
  for (const [id, { offset }] of overrides) {
    if (offset) {
      next.set(id, offset);
    }
  }
  return next;
};

import { isRenderThrottlingEnabled } from "../reactUtils";

export type Animation<R extends object> = (params: {
  deltaTime: number;
  state?: R;
}) => R | null | undefined;

type AnimationRecord = {
  animation: Animation<any>;
  lastTime: number;
  state: any;
};

export class AnimationController {
  private static scheduledFrame:
    | { id: ReturnType<typeof requestAnimationFrame>; type: "raf" }
    | { id: ReturnType<typeof setTimeout>; type: "timeout" }
    | null = null;
  private static animations = new Map<string, AnimationRecord>();

  static start<R extends object>(key: string, animation: Animation<R>) {
    if (AnimationController.animations.has(key)) {
      return;
    }

    const record: AnimationRecord = {
      animation,
      lastTime: 0,
      state: undefined,
    };
    AnimationController.animations.set(key, record);

    let initialState: R | null | undefined;
    try {
      initialState = animation({
        deltaTime: 0,
        state: undefined,
      });
    } catch (error) {
      if (AnimationController.animations.get(key) === record) {
        AnimationController.animations.delete(key);
        AnimationController.cancelScheduledFrameIfIdle();
      }
      throw error;
    }

    // The initial callback may synchronously cancel this animation or replace
    // it with another animation under the same key. Never resurrect or
    // overwrite it after control returns.
    if (AnimationController.animations.get(key) !== record) {
      return;
    }

    if (!initialState) {
      AnimationController.animations.delete(key);
      AnimationController.cancelScheduledFrameIfIdle();
      return;
    }

    record.state = initialState;
    AnimationController.scheduleNextFrame();
  }

  private static scheduleNextFrame() {
    if (AnimationController.scheduledFrame) {
      return;
    }

    if (isRenderThrottlingEnabled()) {
      AnimationController.scheduledFrame = {
        id: requestAnimationFrame(AnimationController.tick),
        type: "raf",
      };
    } else {
      AnimationController.scheduledFrame = {
        id: setTimeout(AnimationController.tick, 0),
        type: "timeout",
      };
    }
  }

  private static cancelScheduledFrame() {
    if (!AnimationController.scheduledFrame) {
      return;
    }

    if (AnimationController.scheduledFrame.type === "raf") {
      cancelAnimationFrame(AnimationController.scheduledFrame.id);
    } else {
      clearTimeout(AnimationController.scheduledFrame.id);
    }

    AnimationController.scheduledFrame = null;
  }

  private static cancelScheduledFrameIfIdle() {
    if (AnimationController.animations.size > 0) {
      return false;
    }

    AnimationController.cancelScheduledFrame();
    return true;
  }

  private static tick() {
    AnimationController.scheduledFrame = null;

    if (AnimationController.animations.size > 0) {
      // A callback may synchronously add, cancel, or replace animations. Work
      // from the frame's starting set so newly started animations begin on the
      // next frame and every record runs at most once per tick.
      const animations = [...AnimationController.animations];
      for (const [key, animation] of animations) {
        if (AnimationController.animations.get(key) !== animation) {
          continue;
        }

        const now = performance.now();
        const deltaTime =
          animation.lastTime === 0 ? 0 : now - animation.lastTime;

        const state = animation.animation({
          deltaTime,
          state: animation.state,
        });

        // The callback may have cancelled or replaced itself. Only the record
        // that was invoked is allowed to update or remove its registration.
        if (AnimationController.animations.get(key) !== animation) {
          continue;
        }

        if (!state) {
          AnimationController.animations.delete(key);

          if (AnimationController.cancelScheduledFrameIfIdle()) {
            return;
          }
        } else {
          animation.lastTime = now;
          animation.state = state;
        }
      }

      if (AnimationController.cancelScheduledFrameIfIdle()) {
        return;
      }

      AnimationController.scheduleNextFrame();
    }
  }

  static running(key: string) {
    return AnimationController.animations.has(key);
  }

  static cancel(key: string) {
    AnimationController.animations.delete(key);
    AnimationController.cancelScheduledFrameIfIdle();
  }

  static reset() {
    AnimationController.animations.clear();
    AnimationController.cancelScheduledFrame();
  }
}

import { COLOR_WHITE } from "@excalidraw/common";

import { bootstrapCanvas } from "./helpers";

const setup = () => {
  const canvas = document.createElement("canvas");
  canvas.width = 200;
  canvas.height = 100;
  const context = canvas.getContext("2d")!;
  const clearRect = vi.spyOn(context, "clearRect");
  const fillRect = vi.spyOn(context, "fillRect");
  return { canvas, context, clearRect, fillRect };
};

const run = (viewBackgroundColor: unknown) => {
  const { canvas, context, clearRect, fillRect } = setup();
  bootstrapCanvas({
    canvas,
    scale: 1,
    normalizedWidth: 200,
    normalizedHeight: 100,
    viewBackgroundColor: viewBackgroundColor as string,
  });
  return { context, clearRect, fillRect };
};

describe("bootstrapCanvas background painting", () => {
  it("skips clearRect for an opaque hex color (fill fully repaints)", () => {
    const { clearRect, fillRect } = run("#ffffff");
    expect(clearRect).not.toHaveBeenCalled();
    expect(fillRect).toHaveBeenCalledTimes(1);
  });

  it("skips clearRect for a 3-digit opaque hex color", () => {
    const { clearRect, fillRect } = run("#fff");
    expect(clearRect).not.toHaveBeenCalled();
    expect(fillRect).toHaveBeenCalledTimes(1);
  });

  it("clears for a hex color with alpha (#RGBA / #RRGGBBAA)", () => {
    expect(run("#ffff").clearRect).toHaveBeenCalledTimes(1);
    expect(run("#ffffff80").clearRect).toHaveBeenCalledTimes(1);
  });

  it("clears and skips fill for the transparent keyword", () => {
    const { clearRect, fillRect } = run("transparent");
    expect(clearRect).toHaveBeenCalledTimes(1);
    expect(fillRect).not.toHaveBeenCalled();
  });

  it("clears for rgba()/hsla() colors and still fills", () => {
    const rgba = run("rgba(255, 0, 0, 0.5)");
    expect(rgba.clearRect).toHaveBeenCalledTimes(1);
    expect(rgba.fillRect).toHaveBeenCalledTimes(1);
  });

  // the ghosting bug (#10931): a corrupted value must never leave the prior
  // frame on screen — we always clear when we can't prove the color is opaque
  it("clears for a corrupted color value to prevent ghosting", () => {
    expect(run("0000").clearRect).toHaveBeenCalledTimes(1);
    expect(run("asdfgh").clearRect).toHaveBeenCalledTimes(1);
  });

  it("falls back to white when the color is rejected by the canvas", () => {
    const { canvas, context } = setup();
    // simulate a stale fillStyle left over from a previous frame's drawing
    context.fillStyle = "#ff0000";
    let fillStyleAtFillTime = "";
    vi.spyOn(context, "fillRect").mockImplementation(() => {
      fillStyleAtFillTime = context.fillStyle as string;
    });

    bootstrapCanvas({
      canvas,
      scale: 1,
      normalizedWidth: 200,
      normalizedHeight: 100,
      viewBackgroundColor: "not-a-color",
    });

    // not the stale red — the seeded default
    expect(fillStyleAtFillTime).toBe(COLOR_WHITE);
  });

  it("clears for a non-string background", () => {
    const { clearRect, fillRect } = run(undefined);
    expect(clearRect).toHaveBeenCalledTimes(1);
    expect(fillRect).not.toHaveBeenCalled();
  });
});

import { COLOR_WHITE, THEME, applyDarkModeFilter } from "@excalidraw/common";

import type { StaticCanvasRenderConfig } from "../scene/types";
import type { AppState, StaticCanvasAppState } from "../types";

export const DEFAULT_SELECTION_COLOR = "#6965db";

/**
 * Returns the theme's selection color (`--color-selection`), read from the
 * computed style of any element inside the editor container so that host
 * overrides are respected. Falls back to the default when unavailable.
 */
export const getSelectionColor = (element: Element | null | undefined) =>
  (element &&
    getComputedStyle(element).getPropertyValue("--color-selection").trim()) ||
  DEFAULT_SELECTION_COLOR;

export const fillCircle = (
  context: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  radius: number,
  stroke: boolean,
  fill = true,
) => {
  context.beginPath();
  context.arc(cx, cy, radius, 0, Math.PI * 2);
  if (fill) {
    context.fill();
  }
  if (stroke) {
    context.stroke();
  }
};

/**
 * The scroll the renderers draw at: the real one, rounded to whole device
 * pixels. Panning writes a fractional scroll (pointer delta ÷ zoom), and an
 * element's cached bitmap blitted at a fractional device offset gets
 * resampled — so as the fraction drifts under a pan, every element pulses
 * between crisp and soft. A whole-pixel scroll moves the scene the way a
 * browser scrolls a page: each element keeps its own, constant sub-pixel
 * phase and a pan never changes how anything is filtered. The difference
 * stays under half a device pixel, so hit-testing and DOM overlays keep
 * using the real scroll. Identity when nothing needs to change.
 */
export const snapScrollToDevicePixels = <
  T extends { scrollX: number; scrollY: number; zoom: { value: number } },
>(
  appState: T,
  scale: number,
): T => {
  // device pixels per scene unit
  const devicePixels = appState.zoom.value * scale;
  if (!(devicePixels > 0)) {
    return appState;
  }
  const scrollX = Math.round(appState.scrollX * devicePixels) / devicePixels;
  const scrollY = Math.round(appState.scrollY * devicePixels) / devicePixels;
  return scrollX === appState.scrollX && scrollY === appState.scrollY
    ? appState
    : { ...appState, scrollX, scrollY };
};

export const getNormalizedCanvasDimensions = (
  canvas: HTMLCanvasElement,
  scale: number,
): [number, number] => {
  // When doing calculations based on canvas width we should used normalized one
  return [canvas.width / scale, canvas.height / scale];
};

export const bootstrapCanvas = ({
  canvas,
  scale,
  normalizedWidth,
  normalizedHeight,
  theme,
  isExporting,
  viewBackgroundColor,
}: {
  canvas: HTMLCanvasElement;
  scale: number;
  normalizedWidth: number;
  normalizedHeight: number;
  theme?: AppState["theme"];
  isExporting?: StaticCanvasRenderConfig["isExporting"];
  viewBackgroundColor?: StaticCanvasAppState["viewBackgroundColor"];
}): CanvasRenderingContext2D => {
  const context = canvas.getContext("2d")!;

  context.setTransform(1, 0, 0, 1, 0, 0);
  context.scale(scale, scale);

  // Paint background
  if (typeof viewBackgroundColor === "string") {
    // An opaque fill repaints every pixel, so clearRect would be redundant.
    // For anything else — transparency, or a value we can't be certain about
    // (e.g. corrupted persisted state like "0000") — clear first so the
    // previous frame can't bleed through.
    //
    // We skip opaque #RRGGBB and #RGB hex colors as a quick optimization.
    const isOpaque = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(viewBackgroundColor);

    if (!isOpaque) {
      context.clearRect(0, 0, normalizedWidth, normalizedHeight);
    }

    if (viewBackgroundColor !== "transparent") {
      context.save();
      // The canvas silently ignores an invalid fillStyle, which would leave a
      // stale color from a previous draw. Seed a sane default so corrupted
      // values fall back to white instead of painting garbage.
      context.fillStyle = COLOR_WHITE;
      context.fillStyle = applyDarkModeFilter(
        viewBackgroundColor,
        theme === THEME.DARK,
      );
      context.fillRect(0, 0, normalizedWidth, normalizedHeight);
      context.restore();
    }
  } else {
    context.clearRect(0, 0, normalizedWidth, normalizedHeight);
  }

  return context;
};

export const strokeRectWithRotation_simple = (
  context: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number,
  cx: number,
  cy: number,
  angle: number,
  fill: boolean = false,
  /** should account for zoom */
  radius: number = 0,
) => {
  context.save();
  context.translate(cx, cy);
  context.rotate(angle);
  if (fill) {
    context.fillRect(x - cx, y - cy, width, height);
  }
  if (radius && context.roundRect) {
    context.beginPath();
    context.roundRect(x - cx, y - cy, width, height, radius);
    context.stroke();
    context.closePath();
  } else {
    context.strokeRect(x - cx, y - cy, width, height);
  }
  context.restore();
};

