describe("color picker hotkeys", () => {
  it("reports an excluded (hidden) entry's hotkey as handled without selecting it", () => {
    // regression: returning "unhandled" let the key escape the modal and hit
    // global shortcuts (`q` toggles the tool lock; see the integration
    // regression in bucketFill.test.tsx)
    const onChange = vi.fn();
    const palette = {
      transparent: COLOR_PALETTE.transparent,
      red: "#ff0000",
    } as ColorPaletteCustom;

    const handled = colorPickerKeyNavHandler(
      handlerArgs("q", palette, onChange, [COLOR_PALETTE.transparent]),
    );

    expect(handled).toBe(true);
    expect(onChange).not.toHaveBeenCalled();
  });

  it("reports a hotkey past the end of a short custom palette as handled", () => {
    // a host-provided palette with fewer entries than hotkey bindings must
    // not leak the unbound keys either
    const onChange = vi.fn();
    const palette = { red: "#ff0000" } as ColorPaletteCustom;

    // `b` is the 15th binding — far past the single palette entry
    const handled = colorPickerKeyNavHandler(
      handlerArgs("b", palette, onChange),
    );

    expect(handled).toBe(true);
    expect(onChange).not.toHaveBeenCalled();
  });

  it("still selects a present, non-excluded entry", () => {
    const onChange = vi.fn();
    const palette = {
      transparent: COLOR_PALETTE.transparent,
      red: "#ff0000",
    } as ColorPaletteCustom;

    const handled = colorPickerKeyNavHandler(
      handlerArgs("w", palette, onChange, [COLOR_PALETTE.transparent]),
    );

    expect(handled).toBe(true);
    expect(onChange).toHaveBeenCalledWith("#ff0000");
  });

  it("steps over an excluded entry when navigating vertically", () => {
    // three rows of five; `transparent` sits in column 0 of row 1 and is
    // excluded, so vertical moves through that cell must skip it in the
    // arrow's direction (wrapping) instead of landing on the hidden swatch
    const palette = {
      transparent: COLOR_PALETTE.transparent,
      white: "#w0",
      gray: "#g0",
      black: "#k0",
      bronze: "#b0",
      red: "#r1",
      green: "#g1",
      blue: "#b1",
      yellow: "#y1",
      orange: "#o1",
      pink: "#r2",
      grape: "#g2",
      violet: "#b2",
      cyan: "#y2",
      teal: "#o2",
    } as unknown as ColorPaletteCustom;
    const excluded = [COLOR_PALETTE.transparent];

    // up from row 2 / column 0 wraps past the excluded cell to row 3
    let onChange = vi.fn();
    expect(
      colorPickerKeyNavHandler({
        ...handlerArgs("ArrowUp", palette, onChange, excluded),
        activeColorPickerSection: "baseColors",
        color: "#r1",
      }),
    ).toBe(true);
    expect(onChange).toHaveBeenCalledWith("#r2");

    // down from row 3 / column 0 wraps past the excluded cell to row 2
    onChange = vi.fn();
    expect(
      colorPickerKeyNavHandler({
        ...handlerArgs("ArrowDown", palette, onChange, excluded),
        activeColorPickerSection: "baseColors",
        color: "#r2",
      }),
    ).toBe(true);
    expect(onChange).toHaveBeenCalledWith("#r1");
  });
});

import {
  COLOR_PALETTE,
  DEFAULT_ELEMENT_STROKE_PICKS,
  DEFAULT_STICKY_NOTE_BG,
  STICKY_NOTE_BACKGROUND_PICKS,
} from "@excalidraw/common";

import {
  getColorTargetAppStateUpdates,
  resolveColorTarget,
} from "../actions/colorTargets";
import { getDefaultAppState } from "../appState";

import { API } from "./helpers/api";

import type { AppState } from "../types";

const appState = (overrides: Partial<AppState> = {}): AppState =>
  ({
    ...getDefaultAppState(),
    selectedElementIds: {},
    editingTextElement: null,
    ...overrides,
  } as AppState);

describe("resolveColorTarget", () => {
  const note = API.createElement({ type: "stickynote", id: "note" });
  const label = API.createElement({
    type: "text",
    id: "label",
    containerId: "note",
  });
  const rectangle = API.createElement({ type: "rectangle", id: "rectangle" });
  const elements = [note, label, rectangle];

  it("follows the active tool when nothing is targeted", () => {
    const regular = resolveColorTarget(appState(), elements, "strokeColor");
    expect(regular.kind).toBe("regular");
    expect(regular.appStateKeys).toEqual(["currentItemStrokeColor"]);
    expect(regular.topPicks).toBe(DEFAULT_ELEMENT_STROKE_PICKS);
    expect(regular.excludedColors).toBeUndefined();

    const sticky = resolveColorTarget(
      appState({
        activeTool: {
          ...getDefaultAppState().activeTool,
          type: "stickynote" as const,
          customType: null,
        },
      }),
      elements,
      "backgroundColor",
    );
    expect(sticky.kind).toBe("sticky");
    expect(sticky.appStateKeys).toEqual([
      "currentItemStickynoteBackgroundColor",
    ]);
    expect(sticky.topPicks).toBe(STICKY_NOTE_BACKGROUND_PICKS);
    expect(sticky.customizableTopPicks).toBe("stickyNoteBackground");
    expect(sticky.excludedColors).toContain(COLOR_PALETTE.transparent);
  });

  it("classifies a note (and its label) as the sticky domain", () => {
    const target = resolveColorTarget(
      appState({ selectedElementIds: { note: true } }),
      elements,
      "strokeColor",
    );
    expect(target.kind).toBe("sticky");
    expect(target.appStateKeys).toEqual(["currentItemStickynoteStrokeColor"]);
  });

  it("writes both domains for a mixed selection but shows the regular picker", () => {
    const target = resolveColorTarget(
      appState({ selectedElementIds: { note: true, rectangle: true } }),
      elements,
      "strokeColor",
    );
    expect(target.kind).toBe("mixed");
    expect(target.appStateKeys).toEqual([
      "currentItemStrokeColor",
      "currentItemStickynoteStrokeColor",
    ]);
    expect(target.topPicks).toBe(DEFAULT_ELEMENT_STROKE_PICKS);
    expect(target.excludedColors).toBeUndefined();
  });

  it("treats the sticky label being edited as a sticky target even with no selection", () => {
    // `handleTextWysiwyg` deselects while editing; `changeProperty` still
    // targets the edited text explicitly
    const target = resolveColorTarget(
      appState({ editingTextElement: label }),
      elements,
      "strokeColor",
    );
    expect(target.kind).toBe("sticky");
  });

  it("normalizes transparent for the sticky defaults only", () => {
    const stickyStroke = resolveColorTarget(
      appState({ selectedElementIds: { note: true } }),
      elements,
      "strokeColor",
    );
    expect(
      getColorTargetAppStateUpdates(stickyStroke, COLOR_PALETTE.transparent),
    ).toEqual({ currentItemStickynoteStrokeColor: COLOR_PALETTE.black });

    const stickyBackground = resolveColorTarget(
      appState({ selectedElementIds: { note: true } }),
      elements,
      "backgroundColor",
    );
    expect(
      getColorTargetAppStateUpdates(
        stickyBackground,
        COLOR_PALETTE.transparent,
      ),
    ).toEqual({ currentItemStickynoteBackgroundColor: DEFAULT_STICKY_NOTE_BG });

    const regular = resolveColorTarget(
      appState({ selectedElementIds: { rectangle: true } }),
      elements,
      "backgroundColor",
    );
    expect(
      getColorTargetAppStateUpdates(regular, COLOR_PALETTE.transparent),
    ).toEqual({ currentItemBackgroundColor: COLOR_PALETTE.transparent });
  });
});

import { COLOR_TOP_PICKS_SLOTS } from "@excalidraw/common";

import { restoreAppState } from "../data/restore";

describe("restore appState.colorTopPicks", () => {
  it("dedupes notation variants and drops non-strings", () => {
    const restored = restoreAppState(
      {
        colorTopPicks: {
          elementStroke: null,
          elementBackground: [
            "#FFF",
            "#ffffff",
            "white",
            "#a5d8ff",
            "rgb(165, 216, 255)",
            "#eebefa",
            42,
            "transparent",
            "rgba(0, 0, 0, 0)",
          ],
        },
      } as any,
      null,
    );
    expect(restored.colorTopPicks.elementBackground).toEqual([
      "#FFF",
      "#a5d8ff",
      "#eebefa",
      "transparent",
    ]);
    expect(restored.colorTopPicks.elementStroke).toBe(null);
  });

  it("caps at the strip slot count and nulls malformed input", () => {
    const many = Array.from(
      { length: 20 },
      (_, i) => `#0000${String(i).padStart(2, "0")}`,
    );
    const restored = restoreAppState(
      {
        colorTopPicks: { elementStroke: many, elementBackground: "junk" },
      } as any,
      null,
    );
    expect(restored.colorTopPicks.elementStroke).toEqual(
      many.slice(0, COLOR_TOP_PICKS_SLOTS),
    );
    expect(restored.colorTopPicks.elementBackground).toBe(null);
  });
});

