      await getTextEditor();

      // each side snaps to its own minimum
      const note = h.elements.find((element) => element.type === "stickynote")!;
      expect(note.width).toBe(STICKY_NOTE_MIN_SIZE);
      expect(note.height).toBe(25 + STICKY_NOTE_BODY_INSET_Y);
