    const editor = await getTextEditor();
    updateTextEditor(editor, "hello");
    Keyboard.exitTextEditor(editor);

    const text = h.elements[0] as ExcalidrawTextElement;
    expect(h.elements).toHaveLength(1);
    expect(text.type).toBe("text");
