  it("edits the existing bound text instead of creating another", async () => {
    const rectangle = API.createElement({
      type: "rectangle",
      x: 100,
      y: 100,
      width: 200,
      height: 100,
    });
    // positioned at the container center, as bound text always is
    const boundText = API.createElement({
      type: "text",
      text: "ola",
      x: 190,
