  it("deletes the text and unbinds on empty submit", async () => {
    const rectangle = API.createElement({
      type: "rectangle",
      x: 100,
      y: 100,
      width: 200,
      height: 100,
    });
    API.setElements([rectangle]);

    mouse.doubleClickAt(150, 130);
    const editor = await getTextEditor();
