import { fireEvent, GlobalTestState, render, waitFor } from "./test-utils";

const { h } = window;

describe("eye dropper", () => {
  it("keeps the color preview within the editor container", async () => {
    await render(<Excalidraw autoFocus={true} handleKeyboardGlobally={true} />);

    Keyboard.keyPress("i");

    const preview = await waitFor(() => {
      const element =
        GlobalTestState.renderResult.container.querySelector<HTMLDivElement>(
          ".excalidraw-eye-dropper-preview",
        );
      expect(element).not.toBeNull();
      return element!;
    });

    const eyeDropperContainer =
      GlobalTestState.renderResult.container.querySelector<HTMLDivElement>(
        ".excalidraw-eye-dropper-backdrop",
      )!;
    expect(eyeDropperContainer.style.cursor).toMatch(
      /^url\(data:image\/svg\+xml/,
    );
    expect(eyeDropperContainer.style.cursor).toMatch(/\) 2 21, auto$/);

    eyeDropperContainer.getBoundingClientRect = () => ({
      left: 100,
      top: 50,
      right: 500,
      bottom: 350,
      width: 400,
      height: 300,
      x: 100,
      y: 50,
      toJSON: () => {},
    });
    Object.defineProperties(preview, {
      offsetWidth: { configurable: true, value: 48 },
      offsetHeight: { configurable: true, value: 48 },
    });

    // This position fits within the viewport, but not within the editor.
    fireEvent.pointerMove(window, { clientX: 480, clientY: 330 });

    expect(preview.style.left).toBe("325px");
    expect(preview.style.top).toBe("225px");
  });

  it("applies the unfiltered color in dark mode", async () => {
    await render(
      <Excalidraw
        autoFocus={true}
        handleKeyboardGlobally={true}
        theme={THEME.DARK}
      />,
    );

    const ctx = h.app.canvas.getContext("2d")!;
    vi.spyOn(ctx, "getImageData").mockReturnValue({
      data: new Uint8ClampedArray([18, 18, 18, 255]),
    } as ImageData);

    Keyboard.keyPress(KEYS.I);

    const eyeDropperContainer = await waitFor(() => {
      const element =
        GlobalTestState.renderResult.container.querySelector<HTMLDivElement>(
          ".excalidraw-eye-dropper-backdrop",
        );
      expect(element).not.toBeNull();
      return element!;
    });

    fireEvent.pointerUp(eyeDropperContainer, {
      clientX: 50,
      clientY: 50,
    });

    expect(h.state.currentItemBackgroundColor).toBe("#ffffff");
  });

  it("contrasts the preview border with the sampled color", async () => {
    await render(<Excalidraw autoFocus={true} handleKeyboardGlobally={true} />);

    const ctx = h.app.canvas.getContext("2d")!;
    const getImageDataSpy = vi.spyOn(ctx, "getImageData").mockReturnValue({
      data: new Uint8ClampedArray([18, 18, 18, 255]),
    } as ImageData);

    Keyboard.keyPress(KEYS.I);

    const preview = await waitFor(() => {
      const element =
        GlobalTestState.renderResult.container.querySelector<HTMLDivElement>(
          ".excalidraw-eye-dropper-preview",
        );
      expect(element).not.toBeNull();
      return element!;
    });

    expect(
      preview.style.getPropertyValue("--eye-dropper-preview-border-color"),
    ).toBe("#fff");

    getImageDataSpy.mockReturnValue({
      data: new Uint8ClampedArray([237, 237, 237, 255]),
    } as ImageData);
    fireEvent.pointerMove(window, { clientX: 50, clientY: 50 });

    expect(
      preview.style.getPropertyValue("--eye-dropper-preview-border-color"),
    ).toBe("#222");
  });
});

import React from "react";

import { MIME_TYPES } from "@excalidraw/common";

import { serializeAsJSON } from "../data/json";
import { Excalidraw } from "../index";

import { API } from "./helpers/api";
import { Keyboard } from "./helpers/ui";
import { act, fireEvent, GlobalTestState, render, waitFor } from "./test-utils";

const { h } = window;

// jsdom has no DragEvent constructor. MouseEvent supplies the coordinates and
// modifier keys, and the data store models files being protected until drop.
const drag = (
  target: Element,
  type: string,
  {
    files = [],
    types = ["Files"],
    ...init
  }: MouseEventInit & { files?: File[]; types?: string[] } = {},
) => {
  const event = new target.ownerDocument.defaultView!.MouseEvent(type, {
    bubbles: true,
    cancelable: true,
    clientX: 200,
    clientY: 200,
    ...init,
  });
  Object.defineProperty(event, "dataTransfer", {
    value: {
      dropEffect: "none",
      types,
      files: type === "drop" ? files : [],
      items: files.map((file) => ({
        kind: "file",
        type: file.type,
        getAsFile: () => (type === "drop" ? file : null),
      })),
    },
  });
  fireEvent(target, event);
  return event as MouseEvent & { dataTransfer: { dropEffect: string } };
};

const overlay = () =>
  GlobalTestState.renderResult.container.querySelector(".file-drop-overlay");

const sceneFile = () =>
  new h.app.ownerWindow.File(
    [
      serializeAsJSON(
        [API.createElement({ type: "ellipse", id: "existing" })],
        { ...h.state, viewBackgroundColor: "#ff0000" },
        {},
        "local",
      ),
    ],
    "scene.excalidraw",
    { type: MIME_TYPES.json },
  );

describe("file drop overlay", () => {
  it("ignores text and library-item drags, and stays visible across child boundaries", async () => {
    await render(<Excalidraw />);
    const canvas = GlobalTestState.interactiveCanvas;
    const container = canvas.closest(".excalidraw")!;

    for (const type of [MIME_TYPES.text, MIME_TYPES.excalidrawlibIds]) {
      drag(canvas, "dragenter", { types: [type] });
      expect(overlay()).toBeNull();
    }

    drag(container, "dragenter");
    expect(overlay()?.textContent).toContain("Drop to replace content");
    drag(canvas, "dragenter");
    drag(container, "dragleave");
    expect(overlay()).not.toBeNull();
    drag(canvas, "dragleave");
    expect(overlay()).toBeNull();
  });

  it("updates when Shift changes through drag events or keyboard events", async () => {
    await render(<Excalidraw />);
    const canvas = GlobalTestState.interactiveCanvas;
    drag(canvas, "dragenter", { shiftKey: true });
    expect(overlay()?.textContent).toContain("Drop to add to canvas");

    drag(canvas, "dragover", { shiftKey: false });
    expect(overlay()?.textContent).toContain("Drop to replace content");
    fireEvent.keyDown(h.app.ownerDocument, { key: "Shift", shiftKey: true });
    expect(overlay()?.textContent).toContain(
      "Your existing content will be kept",
    );
    fireEvent.keyUp(h.app.ownerDocument, { key: "Shift", shiftKey: false });
    expect(overlay()?.textContent).toContain("Drop to replace content");
  });

  it.each(["drop", "dragend", "Escape", "blur"])(
    "clears on %s and can show again for the next drag",
    async (type) => {
      await render(<Excalidraw />);
