    const { getByToolName, container } = await render(<Excalidraw />);
    // select tool
    const tool = getByToolName("arrow");
    fireEvent.click(tool);

    const canvas = container.querySelector("canvas.interactive")!;
    // first point is added on pointer down
    fireEvent.pointerDown(canvas, { clientX: 30, clientY: 30 });

    // second point, enable multi point
    fireEvent.pointerUp(canvas, { clientX: 30, clientY: 30 });
    fireEvent.pointerMove(canvas, { clientX: 50, clientY: 60 });

    // third point
    fireEvent.pointerDown(canvas, { clientX: 50, clientY: 60 });
    fireEvent.pointerUp(canvas);
    fireEvent.pointerMove(canvas, { clientX: 100, clientY: 140 });

    // done
    fireEvent.pointerDown(canvas);
    fireEvent.pointerUp(canvas);
    fireEvent.keyDown(document, {
      key: KEYS.ENTER,
    });

    expect(renderInteractiveScene.mock.calls.length).toMatchInlineSnapshot(
      `11`,
    );
    expect(renderStaticScene.mock.calls.length).toMatchInlineSnapshot(`7`);
    expect(h.elements.length).toEqual(1);

    const element = h.elements[0] as ExcalidrawLinearElement;

    expect(element.type).toEqual("arrow");
    expect(element.x).toEqual(30);
    expect(element.y).toEqual(30);
    expect(element.points).toEqual([
      [0, 0],
      [20, 30],
      [70, 110],
    ]);

    h.elements.forEach((element) => expect(element).toMatchSnapshot());
  });

  it("line", async () => {
    const { getByToolName, container } = await render(<Excalidraw />);
    // select tool
    const tool = getByToolName("line");
    fireEvent.click(tool);

    const canvas = container.querySelector("canvas.interactive")!;
    // first point is added on pointer down
    fireEvent.pointerDown(canvas, { clientX: 30, clientY: 30 });

    // second point, enable multi point
    fireEvent.pointerUp(canvas, { clientX: 30, clientY: 30 });
    fireEvent.pointerMove(canvas, { clientX: 50, clientY: 60 });

    // third point
    fireEvent.pointerDown(canvas, { clientX: 50, clientY: 60 });
    fireEvent.pointerUp(canvas);
    fireEvent.pointerMove(canvas, { clientX: 100, clientY: 140 });

    // done
    fireEvent.pointerDown(canvas);
    fireEvent.pointerUp(canvas);
    fireEvent.keyDown(document, {
      key: KEYS.ENTER,
    });
    expect(renderInteractiveScene.mock.calls.length).toMatchInlineSnapshot(
      `11`,
    );
    expect(renderStaticScene.mock.calls.length).toMatchInlineSnapshot(`7`);
    expect(h.elements.length).toEqual(1);

    const element = h.elements[0] as ExcalidrawLinearElement;

    expect(element.type).toEqual("line");
    expect(element.x).toEqual(30);
    expect(element.y).toEqual(30);
    expect(element.points).toEqual([
      [0, 0],
      [20, 30],
      [70, 110],
    ]);

    h.elements.forEach((element) => expect(element).toMatchSnapshot());
  });

  it("prevents switching to eraser while creating a multi-point line", async () => {
    const { getByToolName, container } = await render(<Excalidraw />);
    // select tool
    const tool = getByToolName("line");
    fireEvent.click(tool);

    const canvas = container.querySelector("canvas.interactive")!;
    // first point is added on pointer down
    fireEvent.pointerDown(canvas, { clientX: 30, clientY: 30 });

    // second point, enable multi point
    fireEvent.pointerUp(canvas, { clientX: 30, clientY: 30 });
    fireEvent.pointerMove(canvas, { clientX: 50, clientY: 60 });

    expect(h.state.activeTool.type).toEqual("line");

    // try to switch to eraser
    fireEvent.keyDown(canvas, {
      key: KEYS.E,
    });

    expect(h.state.activeTool.type).toEqual("line");

    // third point should still be added to the line instead of erasing
    fireEvent.pointerDown(canvas, { clientX: 50, clientY: 60 });
    fireEvent.pointerUp(canvas);
    fireEvent.pointerMove(canvas, { clientX: 100, clientY: 140 });

    // done
    fireEvent.pointerDown(canvas);
    fireEvent.pointerUp(canvas);
    fireEvent.keyDown(document, {
      key: KEYS.ENTER,
    });

    expect(renderInteractiveScene.mock.calls.length).toMatchInlineSnapshot(
      `11`,
    );
    expect(renderStaticScene.mock.calls.length).toMatchInlineSnapshot(`7`);
    expect(h.elements.length).toEqual(1);
  });
});

import React from "react";
import { vi } from "vitest";

import { KEYS, ORIG_ID } from "@excalidraw/common";

import {
  getElementBounds,
  newElementWith,
  reconcileDuplicatedElements,
  duplicateElements,
} from "@excalidraw/element";

import { pointFrom } from "@excalidraw/math";

import type { LocalPoint } from "@excalidraw/math";

import type {
  ExcalidrawArrowElement,
  ExcalidrawElement,
  NonDeletedExcalidrawElement,
} from "@excalidraw/element/types";

import { actionDuplicateSelection } from "../actions";
import { createPasteEvent, serializeAsClipboardJSON } from "../clipboard";
import { Excalidraw } from "../index";

import { API } from "./helpers/api";
import { Pointer, Keyboard } from "./helpers/ui";
import {
  act,
  assertElements,
  getCloneByOrigId,
  render,
  waitFor,
  GlobalTestState,
  unmountComponent,
} from "./test-utils";

import type { ExcalidrawProps, NormalizedZoomValue } from "../types";

const { h } = window;

const mouse = new Pointer("mouse");

vi.mock("@excalidraw/common", async (importOriginal) => {
  const module = await importOriginal<typeof import("@excalidraw/common")>();
  const { mockThrottleRAF } = await import("./helpers/mocks");

  return {
    __esmodule: true,
    ...module,
    isDarwin: false,
    KEYS: {
      ...module.KEYS,
      CTRL_OR_CMD: "ctrlKey",
    },
    throttleRAF: mockThrottleRAF,
  };
});

type OnDuplicate = NonNullable<ExcalidrawProps["onDuplicate"]>;

const isDuplicate = (
  element: ExcalidrawElement,
  prevElements: readonly ExcalidrawElement[],
) => !prevElements.some((prevElement) => prevElement.id === element.id);

/** returns new objects for every duplicate */
const stampDuplicates: OnDuplicate = (nextElements, prevElements) =>
  nextElements.map((element) =>
    isDuplicate(element, prevElements)
      ? newElementWith(element, {
          customData: { stamped: true, frameId: element.frameId },
        })
      : element,
  );

/** vetoes duplicates of elements with the supplied ids */
const vetoDuplicatesOf =
  (...origIds: ExcalidrawElement["id"][]): OnDuplicate =>
  (nextElements, prevElements) =>
    nextElements.filter(
      (element) =>
        !isDuplicate(element, prevElements) ||
        !origIds.includes((element as any)[ORIG_ID]),
    );

const renderWithOnDuplicate = async (onDuplicate: OnDuplicate) => {
  await render(
    <Excalidraw
      autoFocus={true}
      handleKeyboardGlobally={true}
      initialData={{ appState: { zoom: { value: 1 as NormalizedZoomValue } } }}
      onDuplicate={onDuplicate}
    />,
  );
  Object.assign(document, {
    elementFromPoint: () => GlobalTestState.canvas,
  });
};

const paste = async (elements: readonly NonDeletedExcalidrawElement[]) => {
  const clipboardJSON = await serializeAsClipboardJSON({
    elements,
    files: null,
  });
  Keyboard.withModifierKeys({ ctrl: true }, () => {
    Keyboard.keyPress(KEYS.V);
    document.dispatchEvent(
      createPasteEvent({ types: { "text/plain": clipboardJSON } }),
    );
  });
};

const altDrag = (element: ExcalidrawElement, offset: number) => {
  const x = element.x + element.width / 2;
  const y = element.y + element.height / 2;
  Keyboard.withModifierKeys({ alt: true }, () => {
    mouse.downAt(x, y);
    mouse.moveTo(x + offset / 2, y + offset / 2);
    mouse.moveTo(x + offset, y + offset);
    mouse.up();
  });
};

const createFrame = () =>
  API.createElement({
    type: "frame",
    x: 0,
    y: 0,
    width: 400,
    height: 400,
  });

beforeEach(() => {
  unmountComponent();
  localStorage.clear();
  mouse.reset();
});

describe("props.onDuplicate returning new objects for duplicates", () => {
  beforeEach(async () => {
    await renderWithOnDuplicate(stampDuplicates);
  });

  it("duplicate action", () => {
    const rectangle = API.createElement({ type: "rectangle" });
    API.setElements([rectangle]);
    API.setSelectedElements([rectangle]);

    act(() => {
      h.app.actionManager.executeAction(actionDuplicateSelection);
    });

    assertElements(h.elements, [
      { id: rectangle.id },
      {
        [ORIG_ID]: rectangle.id,
        selected: true,
        customData: { stamped: true, frameId: null },
      },
    ]);
  });

  it("alt-drag", () => {
    const rectangle = API.createElement({
      type: "rectangle",
      x: 0,
      y: 0,
      width: 100,
      height: 100,
    });
    API.setElements([rectangle]);

    mouse.select(rectangle);
    altDrag(rectangle, 50);

    assertElements(h.elements, [
      { id: rectangle.id, x: 0, y: 0 },
      {
        [ORIG_ID]: rectangle.id,
        selected: true,
        x: 50,
        y: 50,
        customData: { stamped: true, frameId: null },
      },
    ]);
  });

  it("alt-drag of a container with bound text", () => {
    const [container, text] = API.createTextContainer();
    API.setElements([container, text]);

    expect([container.x, container.y, text.x, text.y]).toEqual([0, 0, 0, 0]);

    mouse.select(container);
    altDrag(container, 50);

    const containerDuplicate = getCloneByOrigId(container.id);
    const textDuplicate = getCloneByOrigId(text.id);

    assertElements(h.elements, [
      { id: container.id, x: 0, y: 0 },
      { id: text.id, x: 0, y: 0, containerId: container.id },
      {
        [ORIG_ID]: container.id,
        selected: true,
        x: 50,
        y: 50,
        boundElements: [{ type: "text", id: textDuplicate.id }],
        customData: { stamped: true, frameId: null },
      },
      {
        [ORIG_ID]: text.id,
        x: 50,
        y: 50,
        containerId: containerDuplicate.id,
        customData: { stamped: true, frameId: null },
      },
    ]);
  });

  it("paste over a frame", async () => {
    const frame = createFrame();
    const [container, text] = API.createTextContainer();
    API.setElements([frame]);

    mouse.moveTo(200, 200);
    // bound text which needs to be redrawn to fit its container
    await paste([container, newElementWith(text, { x: -50, y: -50 })]);

    await waitFor(() => {
      expect(h.elements.length).toBe(3);
    });

    const containerDuplicate = getCloneByOrigId(container.id);
    const textDuplicate = getCloneByOrigId(text.id);

    assertElements(h.elements, [
      {
        [ORIG_ID]: container.id,
        selected: true,
        frameId: frame.id,
        // host sees the duplicates already assigned to the frame
        customData: { stamped: true, frameId: frame.id },
      },
      {
        [ORIG_ID]: text.id,
        frameId: frame.id,
        containerId: containerDuplicate.id,
        customData: { stamped: true, frameId: frame.id },
      },
      { id: frame.id },
    ]);

    expect(textDuplicate.x).toBeGreaterThan(containerDuplicate.x);
    expect(textDuplicate.y).toBeGreaterThan(containerDuplicate.y);
    expect(textDuplicate.x + textDuplicate.width).toBeLessThan(
      containerDuplicate.x + containerDuplicate.width,
    );
  });
});

describe("props.onDuplicate changing already measured duplicates", () => {
  // pasting over a frame measures the duplicates (generating their shapes)
  // ahead of the callback
  it("should not keep stale shapes or bounds", async () => {
    await renderWithOnDuplicate((nextElements, prevElements) =>
      nextElements.map((element) => {
        if (!isDuplicate(element, prevElements)) {
          return element;
        }
        return element.type === "arrow"
          ? newElementWith(element, {
              strokeColor: "#ff0000",
              width: 200,
              points: [
                pointFrom<LocalPoint>(0, 0),
                pointFrom<LocalPoint>(200, 0),
              ],
            })
          : // partial element (version isn't bumped)
            ({ id: element.id, width: 50 } as ExcalidrawElement);
      }),
    );

    const frame = createFrame();
    const arrow = API.createElement({
      type: "arrow",
      x: 0,
      y: 0,
      width: 100,
      height: 0,
      points: [pointFrom<LocalPoint>(0, 0), pointFrom<LocalPoint>(100, 0)],
    });
    const rectangle = API.createElement({
      type: "rectangle",
      x: 0,
      y: 50,
      width: 100,
      height: 100,
    });
    API.setElements([frame]);

    mouse.moveTo(200, 200);
    await paste([arrow, rectangle]);

    await waitFor(() => {
      expect(h.elements.length).toBe(3);
    });

    const elementsMap = h.app.scene.getNonDeletedElementsMap();
    const getWidth = (element: ExcalidrawElement) => {
      const [x1, , x2] = getElementBounds(element, elementsMap);
      return Math.round(x2 - x1);
    };

    const arrowDuplicate = getCloneByOrigId(arrow.id);
    const rectangleDuplicate = getCloneByOrigId(rectangle.id);

    expect(arrowDuplicate.frameId).toBe(frame.id);
    expect(getWidth(arrowDuplicate)).toBe(200);
    expect(getWidth(rectangleDuplicate)).toBe(50);
  });
});

describe("props.onDuplicate vetoing duplicates", () => {
  const createRectangles = () => {
    const rectangle1 = API.createElement({
      id: "rectangle1",
      type: "rectangle",
      x: 0,
      y: 0,
      width: 100,
      height: 100,
    });
    const rectangle2 = API.createElement({
      id: "rectangle2",
      type: "rectangle",
      x: 200,
      y: 0,
      width: 100,
      height: 100,
    });
    return [rectangle1, rectangle2] as const;
  };

  describe("some", () => {
    beforeEach(async () => {
      await renderWithOnDuplicate(vetoDuplicatesOf("rectangle1"));
    });

    it("duplicate action", () => {
      const [rectangle1, rectangle2] = createRectangles();
      API.setElements([rectangle1, rectangle2]);
      API.setSelectedElements([rectangle1, rectangle2]);

      act(() => {
        h.app.actionManager.executeAction(actionDuplicateSelection);
      });

      assertElements(h.elements, [
        { id: rectangle1.id },
        { id: rectangle2.id },
        { [ORIG_ID]: rectangle2.id, selected: true },
      ]);
    });

    it("alt-drag leaves the original behind", () => {
      const [rectangle1, rectangle2] = createRectangles();
      API.setElements([rectangle1, rectangle2]);
      API.setSelectedElements([rectangle1, rectangle2]);

      altDrag(rectangle1, 50);

      assertElements(h.elements, [
        { id: rectangle1.id, x: 0, y: 0 },
        { id: rectangle2.id, x: 200, y: 0 },
        { [ORIG_ID]: rectangle2.id, selected: true, x: 250, y: 50 },
      ]);
    });

    it("paste over a frame", async () => {
      const [rectangle1, rectangle2] = createRectangles();
      const frame = createFrame();
      API.setElements([frame]);

      mouse.moveTo(200, 200);
      await paste([rectangle1, rectangle2]);

      await waitFor(() => {
        expect(h.elements.length).toBe(2);
      });

      assertElements(h.elements, [
        { [ORIG_ID]: rectangle2.id, selected: true, frameId: frame.id },
        { id: frame.id },
      ]);
    });
  });

  describe.each([
    ["by omitting them", vetoDuplicatesOf("rectangle1", "rectangle2")],
    ["by returning false", (() => false) as OnDuplicate],
  ])("all, %s", (_, handler) => {
    const onDuplicate = vi.fn(handler);

    beforeEach(async () => {
      onDuplicate.mockClear();
      await renderWithOnDuplicate(onDuplicate);
    });

    it("duplicate action", () => {
      const [rectangle1, rectangle2] = createRectangles();
      API.setElements([rectangle1, rectangle2]);
      API.setSelectedElements([rectangle1, rectangle2]);

      act(() => {
        h.app.actionManager.executeAction(actionDuplicateSelection);
      });

      expect(onDuplicate).toHaveBeenCalledTimes(1);
      expect(API.getUndoStack().length).toBe(0);
      assertElements(h.elements, [
        { id: rectangle1.id, selected: true },
        { id: rectangle2.id, selected: true },
      ]);
    });

    it("alt-drag moves the originals", () => {
      const [rectangle1, rectangle2] = createRectangles();
      API.setElements([rectangle1, rectangle2]);
      API.setSelectedElements([rectangle1, rectangle2]);

      altDrag(rectangle1, 50);

      expect(onDuplicate).toHaveBeenCalledTimes(1);
      assertElements(h.elements, [
        { id: rectangle1.id, selected: true, x: 50, y: 50 },
        { id: rectangle2.id, selected: true, x: 250, y: 50 },
      ]);
    });

    it("paste over a frame", async () => {
      const [rectangle1, rectangle2] = createRectangles();
      const frame = createFrame();
      API.setElements([frame]);

      mouse.moveTo(200, 200);
      await paste([rectangle1, rectangle2]);

      await waitFor(() => {
        expect(onDuplicate).toHaveBeenCalledTimes(1);
      });

      expect(API.getUndoStack().length).toBe(0);
      assertElements(h.elements, [{ id: frame.id }]);
    });
  });
});

describe("props.onDuplicate data", () => {
  const onDuplicate = vi.fn<OnDuplicate>();

  const getCall = () => {
    expect(onDuplicate).toHaveBeenCalledTimes(1);
    const [nextElements, prevElements, data] = onDuplicate.mock.calls[0];
    return { nextElements, prevElements, ...data };
  };

  beforeEach(async () => {
    onDuplicate.mockClear();
    await renderWithOnDuplicate(onDuplicate);
  });

  it("duplicate action", () => {
    const [container, text] = API.createTextContainer();
    const rectangle = API.createElement({ type: "rectangle" });
    API.setElements([container, text, rectangle]);
    API.setSelectedElements([container]);

    act(() => {
      h.app.actionManager.executeAction(actionDuplicateSelection);
    });

    const {
      duplicateElements,
      originalElements,
      origIdToDuplicateId,
      duplicateIdToOrigId,
    } = getCall();

    const containerDuplicate = getCloneByOrigId(container.id);
    const textDuplicate = getCloneByOrigId(text.id);

    // only what takes part in the duplication
    expect([...originalElements]).toEqual([
      [container.id, container],
      [text.id, text],
    ]);
    expect([...duplicateElements.keys()]).toEqual([
      containerDuplicate.id,
      textDuplicate.id,
    ]);
    expect(duplicateElements.get(containerDuplicate.id)).toBe(
      containerDuplicate,
    );
    expect([...origIdToDuplicateId]).toEqual([
      [container.id, containerDuplicate.id],
      [text.id, textDuplicate.id],
    ]);
    expect([...duplicateIdToOrigId]).toEqual([
      [containerDuplicate.id, container.id],
      [textDuplicate.id, text.id],
    ]);
    // the original of a duplicate
    expect(
      originalElements.get(duplicateIdToOrigId.get(textDuplicate.id)!),
    ).toBe(text);
  });

  it("alt-drag supplies the originals as they are in next elements", () => {
    const rectangle = API.createElement({
      type: "rectangle",
      x: 0,
      y: 0,
      width: 100,
      height: 100,
    });
    API.setElements([rectangle]);

    mouse.select(rectangle);
    altDrag(rectangle, 50);

    const { nextElements, duplicateElements, originalElements } = getCall();

    expect(originalElements.size).toBe(1);
    expect(originalElements.get(rectangle.id)).toBe(
      nextElements.find((element) => element.id === rectangle.id),
    );
    expect(originalElements.get(rectangle.id)).toMatchObject({ x: 0, y: 0 });
    expect([...duplicateElements.values()]).toEqual([
      getCloneByOrigId(rectangle.id),
    ]);
  });

  it("paste supplies the pasted elements as originals", async () => {
    const rectangle = API.createElement({ id: "rectangle", type: "rectangle" });
    API.setElements([rectangle]);

    await paste([rectangle]);

    await waitFor(() => {
      expect(h.elements.length).toBe(2);
    });

    const { prevElements, originalElements, origIdToDuplicateId } = getCall();

    const original = originalElements.get(rectangle.id)!;
    expect(prevElements).toEqual([rectangle]);
    // the pasted element, not the scene element it was copied from
    expect(original).not.toBe(rectangle);
    expect(h.elements).not.toContain(original);
    expect(origIdToDuplicateId.get(rectangle.id)).toBe(
      getCloneByOrigId(rectangle.id).id,
    );
  });
});

describe("reconcileDuplicatedElements()", () => {
  const duplicate = (elements: readonly ExcalidrawElement[]) => {
    const { duplicatedElements } = duplicateElements({
      type: "everything",
      elements,
    });
    const byOrigId = (origId: ExcalidrawElement["id"]) =>
      duplicatedElements.find(
        (element) => (element as any)[ORIG_ID] === origId,
      )!;
    return { duplicatedElements, byOrigId };
  };

  it("should return the supplied elements if host returns nothing", () => {
    const rectangle = API.createElement({ type: "rectangle" });
    const { duplicatedElements } = duplicate([rectangle]);
    const nextElements = [rectangle, ...duplicatedElements];

    const result = reconcileDuplicatedElements(
      undefined,
      nextElements,
      duplicatedElements,
    );

    expect(result.elements).toBe(nextElements);
    expect(result.duplicatedElements).toBe(duplicatedElements);
  });

  it("should veto all duplicates if host returns false", () => {
    const rectangle = API.createElement({ type: "rectangle" });
    const { duplicatedElements } = duplicate([rectangle]);
    const nextElements = [rectangle, ...duplicatedElements];

    const result = reconcileDuplicatedElements(
      false,
      nextElements,
      duplicatedElements,
    );

    expect(result.duplicatedElements).toEqual([]);
  });

  it("should merge into duplicates, and replace other elements", () => {
    const rectangle = newElementWith(API.createElement({ type: "rectangle" }), {
      customData: { a: 1 },
    });
    const { duplicatedElements } = duplicate([rectangle]);
    const [rectangleDuplicate] = duplicatedElements;

    const hostRectangle = newElementWith(rectangle, { locked: true });

    const result = reconcileDuplicatedElements(
      [
        hostRectangle,
        newElementWith(rectangleDuplicate, {
          link: "https://excalidraw.com",
          customData: { b: 2 },
        }),
      ],
      [rectangle, rectangleDuplicate],
      duplicatedElements,
    );

    expect(result.elements[0]).toBe(hostRectangle);
    expect(rectangle.locked).toBe(false);

    expect(result.elements[1]).toBe(rectangleDuplicate);
    expect(result.duplicatedElements).toEqual([rectangleDuplicate]);
    expect(rectangleDuplicate.link).toBe("https://excalidraw.com");
    // shallow merge (nested objects are replaced)
    expect(rectangleDuplicate.customData).toEqual({ b: 2 });
  });

  it("should keep properties omitted by the host", () => {
    const rectangle = API.createElement({ type: "rectangle", x: 0 });
    const { duplicatedElements } = duplicate([rectangle]);
    const [rectangleDuplicate] = duplicatedElements;
    const expected = { ...rectangleDuplicate, x: 100 };

    const result = reconcileDuplicatedElements(
      [
        rectangle,
        { id: rectangleDuplicate.id, x: 100 } as unknown as ExcalidrawElement,
      ],
      [rectangle, rectangleDuplicate],
      duplicatedElements,
    );

    expect(result.elements[1]).toBe(rectangleDuplicate);
    expect(rectangleDuplicate).toEqual({
      ...expected,
      // bumped, so that what's cached by version is invalidated
      version: expected.version + 1,
      versionNonce: expect.any(Number),
      updated: expect.any(Number),
    });
  });

  it("should veto duplicates returned as deleted", () => {
    const rectangle = API.createElement({ type: "rectangle" });
    const { duplicatedElements } = duplicate([rectangle]);

    const result = reconcileDuplicatedElements(
      [
        rectangle,
        newElementWith<ExcalidrawElement>(duplicatedElements[0], {
          isDeleted: true,
        }),
      ],
      [rectangle, ...duplicatedElements],
      duplicatedElements,
    );

    expect(result.elements).toEqual([rectangle]);
    expect(result.duplicatedElements).toEqual([]);
  });

  it("should veto bound text of a vetoed container", () => {
    const rectangle = API.createElement({
      id: "rectangle",
      type: "rectangle",
      boundElements: [{ type: "text", id: "text" }],
    });
    const text = API.createElement({
      id: "text",
      type: "text",
      containerId: rectangle.id,
    });
    const { duplicatedElements, byOrigId } = duplicate([rectangle, text]);
    const nextElements = [rectangle, text, ...duplicatedElements];

    const result = reconcileDuplicatedElements(
      nextElements.filter((element) => element !== byOrigId(rectangle.id)),
      nextElements,
      duplicatedElements,
    );

    expect(result.elements).toEqual([rectangle, text]);
    expect(result.duplicatedElements).toEqual([]);
  });

  it("should veto bound text of a vetoed container (partial element)", () => {
    const rectangle = API.createElement({
      id: "rectangle",
      type: "rectangle",
      boundElements: [{ type: "text", id: "text" }],
    });
    const text = API.createElement({
      id: "text",
      type: "text",
      containerId: rectangle.id,
    });
    const { duplicatedElements, byOrigId } = duplicate([rectangle, text]);

    const result = reconcileDuplicatedElements(
      [
        rectangle,
        text,
        {
          id: byOrigId(text.id).id,
          text: "changed",
        } as unknown as ExcalidrawElement,
      ],
      [rectangle, text, ...duplicatedElements],
      duplicatedElements,
    );

    expect(result.elements).toEqual([rectangle, text]);
    expect(result.duplicatedElements).toEqual([]);
  });

  it("should clear references to vetoed duplicates", () => {
    const frame = API.createElement({ id: "frame", type: "frame" });
    const rectangle = API.createElement({
      id: "rectangle",
      type: "rectangle",
      frameId: frame.id,
      boundElements: [
        { type: "text", id: "text" },
        { type: "arrow", id: "arrow" },
      ],
    });
    const text = API.createElement({
      id: "text",
      type: "text",
      frameId: frame.id,
      containerId: rectangle.id,
    });
    const ellipse = API.createElement({
      id: "ellipse",
      type: "ellipse",
      boundElements: [{ type: "arrow", id: "arrow" }],
    });
    const arrow = API.createElement({
      id: "arrow",
      type: "arrow",
      startBinding: {
        elementId: rectangle.id,
        fixedPoint: [0.5, 0.5],
        mode: "orbit",
      },
      endBinding: {
        elementId: ellipse.id,
        fixedPoint: [0.5, 0.5],
        mode: "orbit",
      },
    });
    const elements = [rectangle, text, frame, ellipse, arrow];
    const { duplicatedElements, byOrigId } = duplicate(elements);
    const nextElements = [...elements, ...duplicatedElements];

    // sanity check
    expect(byOrigId(rectangle.id).frameId).toBe(byOrigId(frame.id).id);

    const vetoed = [
      byOrigId(frame.id),
      byOrigId(text.id),
      byOrigId(ellipse.id),
    ];

    const result = reconcileDuplicatedElements(
      nextElements.filter((element) => !vetoed.includes(element as any)),
      nextElements,
      duplicatedElements,
    );

    const rectangleDuplicate = byOrigId(rectangle.id);
    const arrowDuplicate = byOrigId(arrow.id) as ExcalidrawArrowElement;

    expect(result.elements).toEqual([
      ...elements,
      rectangleDuplicate,
      arrowDuplicate,
    ]);
    expect(result.duplicatedElements).toEqual([
      rectangleDuplicate,
      arrowDuplicate,
    ]);

    expect(rectangleDuplicate.frameId).toBe(null);
    expect(rectangleDuplicate.boundElements).toEqual([
      { type: "arrow", id: arrowDuplicate.id },
    ]);
    expect(arrowDuplicate.startBinding?.elementId).toBe(rectangleDuplicate.id);
    expect(arrowDuplicate.endBinding).toBe(null);
  });
});

import React from "react";
import { vi } from "vitest";

import { resolvablePromise } from "@excalidraw/common";

import { Excalidraw, CaptureUpdateAction } from "../../index";
import { API } from "../helpers/api";
import { Pointer } from "../helpers/ui";
import { render, unmountComponent } from "../test-utils";

import type { ExcalidrawImperativeAPI } from "../../types";

describe("event callbacks", () => {
  const h = window.h;

  let excalidrawAPI: ExcalidrawImperativeAPI;

  const mouse = new Pointer("mouse");

  beforeEach(async () => {
    const excalidrawAPIPromise = resolvablePromise<ExcalidrawImperativeAPI>();
    await render(
      <Excalidraw
        onExcalidrawAPI={(api) => excalidrawAPIPromise.resolve(api as any)}
      />,
    );
    excalidrawAPI = await excalidrawAPIPromise;
  });

  it("should resolve editor:mount/editor:initialize when subscribed before mount", async () => {
    unmountComponent();

    const lifecyclePromise = resolvablePromise<{
      api: ExcalidrawImperativeAPI;
      mount: Promise<{
        excalidrawAPI: ExcalidrawImperativeAPI;
        container: HTMLDivElement | null;
      }>;
      initialize: Promise<ExcalidrawImperativeAPI>;
    }>();

    await render(
      <Excalidraw
        onExcalidrawAPI={(api) => {
          if (api) {
            lifecyclePromise.resolve({
              api,
              mount: api.onEvent("editor:mount"),
              initialize: api.onEvent("editor:initialize"),
            });
          }
        }}
      />,
    );

    const { api, mount, initialize } = await lifecyclePromise;
    await expect(mount).resolves.toEqual({
      excalidrawAPI: api,
      container: expect.any(HTMLDivElement),
    });
    await expect(initialize).resolves.toBe(api);
  });

  it("should replay editor:mount/editor:initialize to late subscribers", async () => {
    const onMount = vi.fn();
    const onInitialize = vi.fn();

    excalidrawAPI.onEvent("editor:mount", onMount);
    excalidrawAPI.onEvent("editor:initialize", onInitialize);

    await Promise.resolve();

    expect(onMount).toHaveBeenCalledTimes(1);
    expect(onMount).toHaveBeenCalledWith({
      excalidrawAPI,
      container: expect.any(HTMLDivElement),
    });
    expect(onInitialize).toHaveBeenCalledTimes(1);
    expect(onInitialize).toHaveBeenCalledWith(excalidrawAPI);

    await expect(excalidrawAPI.onEvent("editor:mount")).resolves.toEqual({
      excalidrawAPI,
      container: expect.any(HTMLDivElement),
    });
    await expect(excalidrawAPI.onEvent("editor:initialize")).resolves.toBe(
      excalidrawAPI,
    );
  });

  it("should call onMount before onInitialize props", async () => {
    unmountComponent();

    const calls: string[] = [];

    await render(
      <Excalidraw
        onMount={({ excalidrawAPI, container }) => {
          expect(excalidrawAPI).toBeDefined();
          expect(container).toBeInstanceOf(HTMLDivElement);
          calls.push("mount");
        }}
        onInitialize={() => {
          calls.push("initialize");
        }}
      />,
    );

    expect(calls).toEqual(["mount", "initialize"]);
  });

  it("should trigger onChange on render", async () => {
    const onChange = vi.fn();

    const origBackgroundColor = h.state.viewBackgroundColor;
    excalidrawAPI.onChange(onChange);
    API.updateScene({
      appState: { viewBackgroundColor: "red" },
      captureUpdate: CaptureUpdateAction.IMMEDIATELY,
    });
    expect(onChange).toHaveBeenCalledWith(
      // elements
      [],
      // appState
      expect.objectContaining({
        viewBackgroundColor: "red",
      }),
      // files
      {},
    );
    expect(onChange.mock?.lastCall?.[1].viewBackgroundColor).not.toBe(
      origBackgroundColor,
    );
  });

  it("should trigger onPointerDown/onPointerUp on canvas pointerDown/pointerUp", async () => {
    const onPointerDown = vi.fn();
    const onPointerUp = vi.fn();

    excalidrawAPI.onPointerDown(onPointerDown);
    excalidrawAPI.onPointerUp(onPointerUp);

    mouse.downAt(100);
    expect(onPointerDown).toHaveBeenCalledTimes(1);
    expect(onPointerUp).not.toHaveBeenCalled();
    mouse.up();
    expect(onPointerDown).toHaveBeenCalledTimes(1);
    expect(onPointerUp).toHaveBeenCalledTimes(1);
  });
});

import React from "react";
import { fireEvent } from "@testing-library/react";
import { vi } from "vitest";

import {
  CURSOR_TYPE,
  POINTER_BUTTON,
  viewportCoordsToSceneCoords,
} from "@excalidraw/common";

import { Excalidraw } from "../index";

import { API } from "./helpers/api";
import { GlobalTestState, render } from "./test-utils";

const { h } = window;

const secondaryButton = {
  pointerId: 1,
  pointerType: "mouse",
  // `button` identifies the pressed button, `buttons` the held-down set
  button: POINTER_BUTTON.SECONDARY,
  buttons: 2,
};

const at = (clientX: number, clientY: number) => ({
  ...secondaryButton,
  clientX,
  clientY,
});

const getViewport = () => ({
  scrollX: h.state.scrollX,
  scrollY: h.state.scrollY,
  zoom: h.state.zoom.value,
});

const canvas = () => GlobalTestState.interactiveCanvas;

describe("secondary-button pan", () => {
  beforeEach(async () => {
    await render(<Excalidraw />);
  });

  it.each([false, true])(
    "pans past five pixels with no context menu (viewModeEnabled=%s)",
    (viewModeEnabled) => {
      API.setAppState({ viewModeEnabled });
      fireEvent.pointerDown(canvas(), at(100, 100));
      const start = getViewport();

      // at the five-pixel threshold it is still a click
      fireEvent.pointerMove(canvas(), at(103, 104));
      expect(getViewport()).toEqual(start);
      expect(canvas().style.cursor).not.toBe(CURSOR_TYPE.GRABBING);

      // past it the pan engages, and moves from here on
      fireEvent.pointerMove(canvas(), at(106, 100));
      expect(getViewport()).toEqual(start);
      expect(canvas().style.cursor).toBe(CURSOR_TYPE.GRABBING);
      fireEvent.pointerMove(canvas(), at(108, 103));
      expect(getViewport()).toEqual({
        ...start,
        scrollX: start.scrollX + 2 / start.zoom,
        scrollY: start.scrollY + 3 / start.zoom,
      });

      fireEvent.pointerUp(window, { ...at(108, 103), buttons: 0 });
      expect(h.state.contextMenu).toBe(null);

      // the platform's own contextmenu for this press (Windows fires it on
      // mouseup) is not a new click...
      fireEvent.contextMenu(canvas(), at(108, 103));
      expect(h.state.contextMenu).toBe(null);
      // ...but only that one
      fireEvent.contextMenu(canvas(), at(108, 103));
      expect(h.state.contextMenu).not.toBe(null);
    },
  );

  it("lets the platform's contextmenu after mouseup open the menu, as always", () => {
    fireEvent.pointerDown(canvas(), at(100, 100));
    fireEvent.pointerMove(canvas(), at(104, 102));
    expect(h.state.contextMenu).toBe(null);

    // Windows fires contextmenu after mouseup: nothing is open at release,
    // so the event lands on the canvas and opens the menu, as before
    fireEvent.pointerUp(window, { ...at(104, 102), buttons: 0 });
    expect(h.state.contextMenu).toBe(null);
    fireEvent.contextMenu(canvas(), at(104, 102));
    const menu = h.state.contextMenu;
    expect(menu).not.toBe(null);
    expect(menu!.left).toBe(104 - h.state.offsetLeft);
    expect(menu!.top).toBe(102 - h.state.offsetTop);
  });

  it.each([false, true])(
    "pauses pointer broadcasts until pan release (viewModeEnabled=%s)",
    (viewModeEnabled) => {
      const onPointerUpdate = vi.fn();
      GlobalTestState.renderResult.rerender(
        <Excalidraw onPointerUpdate={onPointerUpdate} />,
      );
      API.setAppState({ viewModeEnabled });
      fireEvent.pointerDown(canvas(), at(100, 100));
      fireEvent.pointerMove(canvas(), at(103, 104));
      fireEvent.pointerMove(canvas(), at(106, 100));
      fireEvent.pointerMove(canvas(), at(140, 135));
      expect(onPointerUpdate).not.toHaveBeenCalled();

      // The release can be beyond the last delivered pointer move.
      const released = { ...at(150, 145), buttons: 0 };
      fireEvent.pointerUp(canvas(), released);

      expect(onPointerUpdate).toHaveBeenCalledTimes(1);
      expect(onPointerUpdate).toHaveBeenLastCalledWith(
        expect.objectContaining({
          pointer: {
            ...viewportCoordsToSceneCoords(released, h.state),
            tool: "pointer",
          },
          button: "up",
        }),
      );

      const hovered = { ...released, clientX: 160, clientY: 155 };
      fireEvent.pointerMove(canvas(), hovered);
      expect(onPointerUpdate).toHaveBeenCalledTimes(2);
      expect(onPointerUpdate).toHaveBeenLastCalledWith(
        expect.objectContaining({
          pointer: {
            ...viewportCoordsToSceneCoords(hovered, h.state),
            tool: "pointer",
          },
          button: "up",
        }),
      );
    },
  );

  it("does not broadcast an old pan release after a new press", () => {
    const onPointerUpdate = vi.fn();
    GlobalTestState.renderResult.rerender(
      <Excalidraw onPointerUpdate={onPointerUpdate} />,
    );
    fireEvent.pointerDown(canvas(), at(100, 100));
    fireEvent.pointerMove(canvas(), at(106, 100));
    fireEvent.pointerMove(canvas(), at(140, 135));

    const nextPress = { ...at(150, 145), button: 0, buttons: 1 };
    try {
      // A new press cleans up the pan if its pointerup was missed.
      fireEvent.pointerDown(canvas(), nextPress);
      expect(onPointerUpdate).toHaveBeenLastCalledWith(
        expect.objectContaining({ button: "down" }),
      );
    } finally {
      fireEvent.pointerUp(canvas(), { ...nextPress, buttons: 0 });
    }
  });

  it("opens the context menu on release when not dragged (contextmenu on mousedown)", () => {
    fireEvent.pointerDown(canvas(), at(100, 100));
    // macOS and Linux fire contextmenu with the press, before any drag
    // could be told apart from a click
    fireEvent.contextMenu(canvas(), at(100, 100));
    expect(h.state.contextMenu).toBe(null);

    fireEvent.pointerUp(window, { ...at(100, 100), buttons: 0 });
    expect(h.state.contextMenu).not.toBe(null);
  });

  it("does not open a menu for a drag on platforms that fire contextmenu on mousedown", () => {
    fireEvent.pointerDown(canvas(), at(100, 100));
    fireEvent.contextMenu(canvas(), at(100, 100));
    fireEvent.pointerMove(canvas(), at(130, 120));
    fireEvent.pointerMove(canvas(), at(150, 140));
    fireEvent.pointerUp(window, { ...at(150, 140), buttons: 0 });
    expect(h.state.contextMenu).toBe(null);

    // the menu is available again to a later, unrelated request
    fireEvent.contextMenu(canvas(), at(150, 140));
    expect(h.state.contextMenu).not.toBe(null);
  });

  it("selects the element under the pointer like a right-click does", () => {
    const rectangle = API.createElement({
      type: "rectangle",
      x: 10,
      y: 10,
      width: 50,
      height: 50,
      // filled, so its interior hit-tests (a transparent shape only hits
      // on its stroke)
      backgroundColor: "#ffc9c9",
      fillStyle: "solid",
    });
    API.setElements([rectangle]);

    fireEvent.pointerDown(canvas(), at(30, 30));
    // contextmenu with the press: the session opens the menu on release
    fireEvent.contextMenu(canvas(), at(30, 30));
    fireEvent.pointerUp(window, { ...at(30, 30), buttons: 0 });

    expect(h.state.contextMenu).not.toBe(null);
    expect(h.state.selectedElementIds[rectangle.id]).toBe(true);
  });

  it("leaves a menu-less editor menu-less while still panning", async () => {
    await render(<Excalidraw interaction={false} />);
    fireEvent.pointerDown(canvas(), at(100, 100));
    fireEvent.contextMenu(canvas(), at(100, 100));
    fireEvent.pointerUp(window, { ...at(100, 100), buttons: 0 });
    expect(h.state.contextMenu).toBe(null);
  });
});

import React from "react";

import { Excalidraw } from "../index";
import { snapScrollToDevicePixels } from "../renderer/helpers";

import { API } from "./helpers/api";
import { act, GlobalTestState, render, waitFor } from "./test-utils";

import type { NormalizedZoomValue } from "../types";

type CanvasEvent = {
  type: string;
  transform: [number, number, number, number, number, number];
  props: { dx: number; dy: number; dWidth: number };
};

/** the static canvas's element blits, in device pixels */
const getBlits = () => {
  const context = GlobalTestState.canvas.getContext("2d") as any;
  return (context.__getEvents() as CanvasEvent[])
    .filter((event) => event.type === "drawImage")
    .map(({ transform: [a, b, c, d, e, f], props }) => ({
      // the matrix's scale, whatever its rotation
      scale: Math.hypot(a, b),
      x: a * props.dx + c * props.dy + e,
      y: b * props.dx + d * props.dy + f,
      width: props.dWidth,
    }));
};

/** re-renders at the given viewport and returns that render's blits */
const renderAt = async (zoom: number, scrollX: number, scrollY: number) => {
  (GlobalTestState.canvas.getContext("2d") as any).__clearEvents();
  API.setAppState({
    zoom: { value: zoom as NormalizedZoomValue },
    scrollX,
    scrollY,
  });
  return waitFor(() => {
    // the static scene renders on the next frame
    const blits = getBlits().filter(
      (blit) => Math.abs(blit.scale - zoom) < 1e-9,
    );
    expect(blits.length).toBeGreaterThan(0);
    return blits;
  });
};

const distanceToWholePixel = ({ x, y }: { x: number; y: number }) =>
  Math.abs(x - Math.round(x)) + Math.abs(y - Math.round(y));

describe("element pixel snap", () => {
  beforeEach(async () => {
    await render(<Excalidraw />);
    // jsdom gives the editor no size, which culls every element
    API.setAppState({ width: 800, height: 600 });
  });

  it.each([
    ["text", { type: "text" as const, text: "hello" }],
    ["rectangle", { type: "rectangle" as const, width: 120, height: 60 }],
  ])(
    "blits an unrotated %s on whole device pixels at any zoom",
    async (_, props) => {
      API.setElements([API.createElement({ x: 10.37, y: 20.61, ...props })]);
      for (const zoom of [1, 1.5, 0.73, 2.2]) {
        const blits = await renderAt(zoom, 3.3, -7.77);
        for (const blit of blits) {
          expect(distanceToWholePixel(blit)).toBeLessThan(1e-6);
        }
      }
    },
  );

  it.each([Math.PI / 2, (3 * Math.PI) / 2])(
    "snaps a right-angle rotation (%s rad) without displacing it",
    async (angle) => {
      API.setElements([
        API.createElement({
          type: "rectangle",
          x: 110.37,
          y: 120.61,
          width: 120,
          height: 60,
          angle: angle as any,
        }),
      ]);
      const blits = await renderAt(1.5, 3.3, -7.77);
      for (const blit of blits) {
        expect(distanceToWholePixel(blit)).toBeLessThan(1e-6);
        // and it stays where the element is — a formula that divides by the
        // near-zero diagonal of a rotation sends it far offscreen
        expect(Math.abs(blit.x)).toBeLessThan(2000);
        expect(Math.abs(blit.y)).toBeLessThan(2000);
      }
    },
  );

  it("does not snap while a zoom gesture keeps the cached bitmaps", async () => {
    API.setElements([
      API.createElement({ type: "text", x: 10.37, y: 20.61, text: "hello" }),
    ]);
    // the bitmaps are resampled during the gesture; rounding would only
    // make elements twitch
    await renderAt(1, 0, 0);
    (GlobalTestState.canvas.getContext("2d") as any).__clearEvents();
    API.setAppState({
      shouldCacheIgnoreZoom: true,
      zoom: { value: 1.5 as NormalizedZoomValue },
      scrollX: 3.3,
      scrollY: -7.77,
    });
    const [blit] = await waitFor(() => {
      const blits = getBlits();
      expect(blits.length).toBeGreaterThan(0);
      return blits;
    });
    expect(distanceToWholePixel(blit)).toBeGreaterThan(1e-3);
    API.setAppState({ shouldCacheIgnoreZoom: false });
  });

  it.each([
    // a plain fractional offset, and one that is exactly half a device pixel
    // at 150% (51 scene units → 76.5), where the float noise of a drag used
    // to flip the rounding between two neighbors
    ["fractional", { box: [100.3, 100.3], label: [150.7, 140.2] }],
    ["half-pixel tie", { box: [10, 10], label: [61, 30] }],
  ])(
    "keeps a label at a constant device offset from its container while dragged (%s)",
    async (_, { box, label }) => {
      const offsets = new Set<string>();
      for (const drag of [0, 0.3, 0.4, 0.7, 1.4]) {
        API.setElements([
          API.createElement({
            type: "rectangle",
            id: "box",
            x: box[0] + drag,
            y: box[1] + drag,
            width: 200,
            height: 100,
            boundElements: [{ type: "text", id: "label" }],
          }),
          API.createElement({
            type: "text",
            id: "label",
            x: label[0] + drag,
            y: label[1] + drag,
            text: "hi",
            fontSize: 20,
            containerId: "box",
          }),
        ]);
        const blits = await renderAt(1.5, 3.3, -7.77);
        expect(blits).toHaveLength(2);
        for (const blit of blits) {
          expect(distanceToWholePixel(blit)).toBeLessThan(1e-6);
        }
        // the container's bitmap is the wider one
        const [labelBlit, boxBlit] = [...blits].sort(
          (p, q) => p.width - q.width,
        );
        offsets.add(`${labelBlit.x - boxBlit.x},${labelBlit.y - boxBlit.y}`);
      }
      expect(offsets.size).toBe(1);
    },
  );

  it("leaves rotated elements alone", async () => {
    API.setElements([
      API.createElement({
        type: "text",
        x: 10.37,
        y: 20.61,
        text: "hello",
        angle: 0.4 as any,
      }),
    ]);
    (GlobalTestState.canvas.getContext("2d") as any).__clearEvents();
    API.setAppState({
      zoom: { value: 1.5 as NormalizedZoomValue },
      scrollX: 3.3,
      scrollY: -7.77,
    });
    // a rotated blit is resampled regardless; at these coordinates its
    // unsnapped offset is not a whole pixel
    const [blit] = await waitFor(() => {
      const blits = getBlits();
      expect(blits.length).toBeGreaterThan(0);
      return blits;
    });
    expect(distanceToWholePixel(blit)).toBeGreaterThan(1e-3);
  });

  it.each([0, Math.PI / 2, 0.4])(
    "places overridden bitmaps like translated document geometry (%s rad)",
    async (angle) => {
      const ownerWindow = GlobalTestState.canvas.ownerDocument.defaultView!;
      const pixelRatioDescriptor = Object.getOwnPropertyDescriptor(
        ownerWindow,
        "devicePixelRatio",
      )!;
      try {
        for (const devicePixelRatio of [1, 2]) {
          Object.defineProperty(ownerWindow, "devicePixelRatio", {
            configurable: true,
            value: devicePixelRatio,
          });
          for (const zoom of [1, 1.5, 0.73]) {
            const props = {
              type: "rectangle" as const,
              x: 110.37,
              y: 140.61,
              width: 120,
              height: 60,
              angle: angle as any,
            };
            const element = API.createElement(props);
            API.setElements([element]);
            await renderAt(zoom, 3.3, -7.77);
            (GlobalTestState.canvas.getContext("2d") as any).__clearEvents();
            act(() =>
              window.h.app.api.setElementRenderOverrides(
                new Map([[element.id, { offset: { x: 13.37, y: -7.61 } }]]),
              ),
            );
            const [overridden] = await waitFor(() => {
              const blits = getBlits();
              expect(blits).toHaveLength(1);
              return blits;
            });
            act(() => window.h.app.api.setElementRenderOverrides(null));
            API.setElements([
              API.createElement({
                ...props,
                x: props.x + 13.37,
                y: props.y - 7.61,
              }),
            ]);
            const [translated] = await renderAt(zoom, 3.3, -7.77);
            expect(overridden.x).toBeCloseTo(translated.x, 6);
            expect(overridden.y).toBeCloseTo(translated.y, 6);
            expect(overridden.scale).toBeCloseTo(translated.scale, 6);
            if (angle !== 0.4) {
              expect(distanceToWholePixel(overridden)).toBeLessThan(1e-6);
            }
          }
        }
      } finally {
        Object.defineProperty(
          ownerWindow,
          "devicePixelRatio",
          pixelRatioDescriptor,
        );
      }
    },
  );

  it("keeps bound-label snapping stable through inherited fractional offsets", async () => {
    const box = API.createElement({
      type: "rectangle",
      id: "box",
      x: 10,
      y: 10,
      width: 200,
      height: 100,
      boundElements: [{ type: "text", id: "label" }],
    });
    const label = API.createElement({
      type: "text",
      id: "label",
      x: 61,
      y: 30,
      text: "hi",
      fontSize: 20,
      containerId: box.id,
    });
    API.setElements([box, label]);
    await renderAt(1.5, 3.3, -7.77);
    const offsets = new Set<string>();
    for (const translation of [0, 0.3, 0.4, 0.7, 1.4]) {
      (GlobalTestState.canvas.getContext("2d") as any).__clearEvents();
      act(() =>
        window.h.app.api.setElementRenderOverrides(
          new Map([[box.id, { offset: { x: translation, y: translation } }]]),
        ),
      );
      const blits = await waitFor(() => {
        const blits = getBlits();
        expect(blits).toHaveLength(2);
        return blits;
      });
      const [labelBlit, boxBlit] = [...blits].sort((p, q) => p.width - q.width);
      offsets.add(`${labelBlit.x - boxBlit.x},${labelBlit.y - boxBlit.y}`);
    }
    expect(offsets.size).toBe(1);
  });
});

describe("scroll pixel snap", () => {
  it("rounds the scroll to whole device pixels and is identity when it already is", () => {
    const zoom = { value: 1.5 as NormalizedZoomValue };
    const snapped = snapScrollToDevicePixels(
      { scrollX: 3.3, scrollY: -7.77, zoom },
      2,
    );
    // 3.3 × 1.5 × 2 = 9.9 → 10;  -7.77 × 3 = -23.31 → -23
    expect(snapped.scrollX * 3).toBeCloseTo(10, 9);
    expect(snapped.scrollY * 3).toBeCloseTo(-23, 9);

    const whole = { scrollX: 4, scrollY: -6, zoom };
    expect(snapScrollToDevicePixels(whole, 2)).toBe(whole);
  });

  it("blits a shape at integer coordinates on whole device pixels at any fractional scroll", async () => {
    await render(<Excalidraw />);
    API.setAppState({ width: 800, height: 600 });
    API.setElements([
      API.createElement({
        type: "rectangle",
        x: 100,
        y: 200,
        width: 200,
        height: 100,
      }),
    ]);
    // zooms at which the element canvas's padding is itself whole device
    // pixels, so the only fractional term left is the scroll
    for (const zoom of [1, 1.5]) {
      const [atFirst] = await renderAt(zoom, 3.3, -7.77);
      expect(distanceToWholePixel(atFirst)).toBeLessThan(1e-6);
      // a tenth of a device pixel further lands on the same pixels
      const [atSecond] = await renderAt(zoom, 3.3 + 0.1 / zoom, -7.77);
      expect(atSecond).toEqual(atFirst);
    }
  });
});

describe("grid pixel snap", () => {
  /** the static canvas's path starts, in device pixels */
  const getPathStarts = () => {
    const context = GlobalTestState.canvas.getContext("2d") as any;
    return (context.__getEvents() as CanvasEvent[])
      .filter((event) => event.type === "moveTo")
      .map(({ transform: [a, , , d, e, f], props }) => ({
        scale: a,
        x: a * (props as any).x + e,
        y: d * (props as any).y + f,
      }));
  };
  const fraction = (value: number) => value - Math.floor(value);

  it("centers one-pixel grid lines on device pixels at any zoom", async () => {
    await render(<Excalidraw />);
    API.setAppState({ width: 800, height: 600, gridModeEnabled: true });
    // zooms at which a grid line is at least a device pixel wide — 1.9
    // included, where `(1 / zoom) × zoom` evaluates just under 1
    for (const zoom of [1, 1.5, 1.9, 2.2]) {
      (GlobalTestState.canvas.getContext("2d") as any).__clearEvents();
      API.setAppState({
        zoom: { value: zoom as NormalizedZoomValue },
        scrollX: 3.3,
        scrollY: -7.77,
      });
      const lines = await waitFor(() => {
        const starts = getPathStarts().filter(
          (start) => Math.abs(start.scale - zoom) < 1e-9,
        );
        expect(starts.length).toBeGreaterThan(0);
        return starts;
      });
      for (const line of lines) {
        // a vertical line has its x on the half pixel, a horizontal its y
        const onHalfPixel =
          Math.abs(fraction(line.x) - 0.5) < 1e-6 ||
          Math.abs(fraction(line.y) - 0.5) < 1e-6;
        expect(onHalfPixel).toBe(true);
      }
    }
  });
});

import { waitFor } from "@testing-library/dom";
import { fireEvent } from "@testing-library/react";

import {
  stripIgnoredNodesFromErrorMessage,
  trimErrorStack,
} from "../test-utils";

export const TEXT_EDITOR_SELECTOR =
  ".excalidraw-textEditorContainer > textarea";

export const getTextEditor = async ({
  selector = TEXT_EDITOR_SELECTOR,
  waitForEditor = true,
}: { selector?: string; waitForEditor?: boolean } = {}) => {
  const error = trimErrorStack(new Error());
  try {
    const query = () => document.querySelector(selector) as HTMLTextAreaElement;
    if (waitForEditor) {
      await waitFor(() => expect(query()).not.toBe(null));
      return query();
    }
    return query();
  } catch (err: any) {
    stripIgnoredNodesFromErrorMessage(err);
    err.stack = error.stack;
    throw err;
  }
};

export const updateTextEditor = (
  editor: HTMLTextAreaElement | HTMLInputElement,
  value: string,
) => {
  fireEvent.change(editor, { target: { value } });
  fireEvent.input(editor);
};

import { queries, buildQueries } from "@testing-library/react";

import { TOOL_TYPE } from "@excalidraw/common";

import type { ToolType } from "@excalidraw/excalidraw/types";

const _getAllByToolName = (container: HTMLElement, tool: ToolType | "lock") => {
  const toolTitle = tool === "lock" ? "lock" : TOOL_TYPE[tool];
  return (
    queries
      .getAllByTestId(container, `toolbar-${toolTitle}`)
      // an open ToolPopover renders options with the same testids as the
      // toolbar buttons — "by tool name" means the toolbar-level button
      .filter((el) => !el.closest(".tool-popover-content"))
  );
};

const getMultipleError = (_container: any, tool: any) =>
  `Found multiple elements with tool name: ${tool}`;
const getMissingError = (_container: any, tool: any) =>
  `Unable to find an element with tool name: ${tool}`;

export const [
  queryByToolName,
  getAllByToolName,
  getByToolName,
  findAllByToolName,
  findByToolName,
] = buildQueries<(ToolType | "lock")[]>(
  _getAllByToolName,
  getMultipleError,
  getMissingError,
);

