      expect(ids(-590)).toEqual(sceneIds);
      expect(ids(-580)).toEqual(sceneIds);
      expect(ids(-570)).toEqual(sceneIds);
      expect(ids(0)).toEqual(sceneIds.filter((elementId) => elementId !== id));
    },
