});

import React from "react";

import { KEYS } from "@excalidraw/common";

import { Excalidraw } from "../index";

import { API } from "./helpers/api";
import { Keyboard } from "./helpers/ui";
import {
  mockBoundingClientRect,
  render,
  restoreOriginalGetBoundingClientRect,
  waitFor,
} from "./test-utils";

const { h } = window;

describe("appState", () => {
  it("scroll-to-content on init works with non-zero offsets", async () => {
    const WIDTH = 200;
    const HEIGHT = 100;
    const OFFSET_LEFT = 20;
    const OFFSET_TOP = 10;

    const ELEM_WIDTH = 100;
    const ELEM_HEIGHT = 60;

    mockBoundingClientRect();

    await render(
      <div>
        <Excalidraw
          initialData={{
            elements: [
              API.createElement({
                type: "rectangle",
                id: "A",
                width: ELEM_WIDTH,
                height: ELEM_HEIGHT,
              }),
            ],
            scrollToContent: true,
          }}
        />
      </div>,
    );
    await waitFor(() => {
      expect(h.state.width).toBe(200);
      expect(h.state.height).toBe(100);
      expect(h.state.offsetLeft).toBe(OFFSET_LEFT);
      expect(h.state.offsetTop).toBe(OFFSET_TOP);

      // assert scroll is in center
      expect(h.state.scrollX).toBe(WIDTH / 2 - ELEM_WIDTH / 2);
      expect(h.state.scrollY).toBe(HEIGHT / 2 - ELEM_HEIGHT / 2);
    });
    restoreOriginalGetBoundingClientRect();
  });

  it("initialState.viewport on init takes precedence over scrollToContent", async () => {
    mockBoundingClientRect();

    await render(
      <Excalidraw
        initialData={{
          elements: [
            API.createElement({
              type: "rectangle",
              id: "A",
              width: 100,
              height: 60,
            }),
            API.createElement({
              type: "rectangle",
              id: "B",
              x: 1000,
              y: 500,
              width: 200,
              height: 100,
            }),
          ],
          scrollToContent: true,
        }}
        initialState={{
          viewport: {
            target: "B",
            fit: "scale-down",
            lock: { scroll: true, zoom: true, overscroll: 15 },
          },
        }}
      />,
    );

    await waitFor(() => {
      expect(h.state.width).toBe(200);
      expect(h.state.height).toBe(100);
      expect(h.state.scrollX).toBe(-1000);
      expect(h.state.scrollY).toBe(-500);
      expect(h.state.scrollConstraints).toMatchObject({
        x: 1000,
        y: 500,
        width: 200,
        height: 100,
        lockScroll: true,
        lockZoom: true,
        overscroll: 15,
      });
    });

    restoreOriginalGetBoundingClientRect();
  });

  it("moving by page up/down/left/right", async () => {
    mockBoundingClientRect();
    await render(<Excalidraw handleKeyboardGlobally={true} />, {});

    const scrollTest = () => {
      const initialScrollY = h.state.scrollY;
      const initialScrollX = h.state.scrollX;
      const pageStepY = h.state.height / h.state.zoom.value;
      const pageStepX = h.state.width / h.state.zoom.value;
      // Assert the following assertions have meaning
      expect(pageStepY).toBeGreaterThan(0);
      expect(pageStepX).toBeGreaterThan(0);
      // Assert we scroll up
      Keyboard.keyPress(KEYS.PAGE_UP);
      expect(h.state.scrollY).toBe(initialScrollY + pageStepY);
      // x-axis unchanged
      expect(h.state.scrollX).toBe(initialScrollX);

      // Assert we scroll down
      Keyboard.keyPress(KEYS.PAGE_DOWN);
      Keyboard.keyPress(KEYS.PAGE_DOWN);
      expect(h.state.scrollY).toBe(initialScrollY - pageStepY);
      // x-axis unchanged
      expect(h.state.scrollX).toBe(initialScrollX);

      // Assert we scroll left
      Keyboard.withModifierKeys({ shift: true }, () => {
        Keyboard.keyPress(KEYS.PAGE_UP);
      });
      expect(h.state.scrollX).toBe(initialScrollX + pageStepX);
      // y-axis unchanged
      expect(h.state.scrollY).toBe(initialScrollY - pageStepY);

      // Assert we scroll right
      Keyboard.withModifierKeys({ shift: true }, () => {
        Keyboard.keyPress(KEYS.PAGE_DOWN);
        Keyboard.keyPress(KEYS.PAGE_DOWN);
      });
      expect(h.state.scrollX).toBe(initialScrollX - pageStepX);
      // y-axis unchanged
      expect(h.state.scrollY).toBe(initialScrollY - pageStepY);
    };

    const zoom = h.state.zoom.value;
    // Assert we scroll properly when zoomed in
    API.setAppState({ zoom: { value: (zoom * 1.1) as typeof zoom } });
    scrollTest();
    // Assert we scroll properly when zoomed out
    API.setAppState({ zoom: { value: (zoom * 0.9) as typeof zoom } });
    scrollTest();
    // Assert we scroll properly with normal zoom
    API.setAppState({ zoom: { value: zoom } });
    scrollTest();
    restoreOriginalGetBoundingClientRect();
  });
});

import React from "react";
import { vi } from "vitest";

import { KEYS, MAX_ZOOM } from "@excalidraw/common";

import { Excalidraw } from "../index";
import {
  actionResetZoom,
  actionZoomIn,
  actionZoomOut,
  actionZoomToFit,
  actionZoomToFitSelection,
} from "../actions/actionCanvas";
import { getNormalizedZoom } from "../scene";
import {
  snapBackToConstraints,
  SCROLL_CONSTRAINTS_SNAP_BACK_ANIMATION_KEY,
  SCROLL_TO_CONTENT_ANIMATION_KEY,
} from "../components/App.viewport";
import {
  constrainScrollState,
  DEFAULT_OVERSCROLL,
  getViewportForZoomWithScrollConstraints,
} from "../viewport";
import { AnimationController } from "../renderer/animation";

import { API } from "./helpers/api";
import { Keyboard, Pointer } from "./helpers/ui";
import {
  fireEvent,
  GlobalTestState,
  mockBoundingClientRect,
  render,
  restoreOriginalGetBoundingClientRect,
  waitFor,
} from "./test-utils";

import type { AppState, ScrollConstraints } from "../types";

const { h } = window;

// `mockBoundingClientRect()` makes the viewport 200 x 100
const VIEWPORT = { width: 200, height: 100 };

const makeState = (
  overrides: Partial<AppState> & {
    scrollConstraints: ScrollConstraints | null;
  },
): Pick<
  AppState,
  "scrollX" | "scrollY" | "zoom" | "width" | "height" | "scrollConstraints"
> => ({
  scrollX: 0,
  scrollY: 0,
  zoom: { value: getNormalizedZoom(1) },
  width: VIEWPORT.width,
  height: VIEWPORT.height,
  ...overrides,
});

/** A lock box with sensible defaults; pass `lockScroll`/`lockZoom`/`zoom`/
 * `overscroll`/`offsets` to override. */
const makeLock = (
  overrides: Partial<ScrollConstraints> &
    Pick<ScrollConstraints, "x" | "y" | "width" | "height">,
): ScrollConstraints => ({
  lockScroll: false,
  lockZoom: false,
  zoom: 1,
  overscroll: 0,
  ...overrides,
});

const waitForAnimationToStop = (key: string, maxFrames = 200) => {
  return React.act(
    () =>
      new Promise<void>((resolve) => {
        let remaining = maxFrames;
        const check = () => {
          if (!AnimationController.running(key) || --remaining <= 0) {
            resolve();
          } else {
            requestAnimationFrame(check);
          }
        };
        requestAnimationFrame(check);
      }),
  );
};

describe("constrainScrollState (pure)", () => {
  it("returns scroll/zoom unchanged when there is no lock", () => {
    const state = makeState({
      scrollX: 123,
      scrollY: -45,
      zoom: { value: getNormalizedZoom(0.5) },
      scrollConstraints: null,
    });

    expect(constrainScrollState(state)).toEqual({
      scrollX: 123,
      scrollY: -45,
      zoom: { value: getNormalizedZoom(0.5) },
    });
  });

  it("leaves scroll free when only zoom is locked", () => {
    const lock = makeLock({
      x: 0,
      y: 0,
      width: 1000,
      height: 1000,
      lockZoom: true,
      zoom: 0.2,
    });
    const result = constrainScrollState(
      makeState({ scrollX: 9999, scrollY: 9999, scrollConstraints: lock }),
    );
    expect(result.scrollX).toBe(9999);
    expect(result.scrollY).toBe(9999);
  });

  it("leaves zoom free when only scroll is locked", () => {
    const lock = makeLock({
      x: 0,
      y: 0,
      width: 1000,
      height: 1000,
      lockScroll: true,
    });
    // a zoom that would have been forced up by the old box-cover fit zoom
    // (0.2 for this box) stays as-is when only scroll is locked
    const { zoom } = constrainScrollState(
      makeState({
        zoom: { value: getNormalizedZoom(0.15) },
        scrollConstraints: lock,
      }),
    );
    expect(zoom.value).toBeCloseTo(0.15);
  });

  describe("scroll lock", () => {
    const lock = makeLock({
      x: 0,
      y: 0,
      width: 1000,
      height: 1000,
      lockScroll: true,
    });

    it("clamps scroll so the viewport can't leave the box", () => {
      // pan past the box's top-left corner → clamp to the corner (scroll 0)
      const corner = constrainScrollState(
        makeState({ scrollX: 100, scrollY: 100, scrollConstraints: lock }),
      );
      expect(corner.scrollX).toBeCloseTo(0);
      expect(corner.scrollY).toBeCloseTo(0);

      // pan past the box's far edges → clamp to width/height - boxSize
      const farEdge = constrainScrollState(
        makeState({ scrollX: -5000, scrollY: -5000, scrollConstraints: lock }),
      );
      expect(farEdge.scrollX).toBeCloseTo(VIEWPORT.width - lock.width); // -800
      expect(farEdge.scrollY).toBeCloseTo(VIEWPORT.height - lock.height); // -900
    });

    it("leaves an in-bounds viewport untouched", () => {
      const inBounds = makeState({
        scrollX: -100,
        scrollY: -100,
        zoom: { value: getNormalizedZoom(1) },
        scrollConstraints: lock,
      });
      expect(constrainScrollState(inBounds)).toMatchObject({
        scrollX: -100,
        scrollY: -100,
        zoom: { value: getNormalizedZoom(1) },
      });
    });

    it("centers the box when the viewport is larger than it", () => {
      // at zoom 0.1 the visible width (200/0.1 = 2000) exceeds the box (1000),
      // so there's no pan room → the box is centered on the axis
      const result = constrainScrollState(
        makeState({
          scrollX: 999,
          zoom: { value: getNormalizedZoom(0.1) },
          scrollConstraints: lock,
        }),
      );
      // centered: (min + max) / 2, min = w/zoom - (x+w), max = -x
      const centeredX = (VIEWPORT.width / 0.1 - lock.width + 0) / 2;
      expect(result.scrollX).toBeCloseTo(centeredX);
    });
  });
});

