        target: { x: 30, y: 40, height: 60 },
        fit: "scale-down",
        animation: false,
        lock: { scroll: true },
      });
    });

    expect(h.state.scrollConstraints).toMatchObject({
      x: 30,
      y: 40,
      width: h.state.width,
      height: 60,
    });

    React.act(() => {
      h.app.viewport.setViewport({
        target: { x: 70, y: 80 },
        fit: "scale-down",
        animation: false,
        lock: { scroll: true },
      });
    });

    expect(h.state.scrollConstraints).toMatchObject({
      x: 70,
      y: 80,
      width: h.state.width,
      height: h.state.height,
    });
