      expect(h.state.currentItemStrokeColor).toBe(RED);
      expect(h.state.currentItemStickynoteStrokeColor).toBe(RED);
    });

    it("creates notes from the sticky defaults, not the shape defaults", async () => {
      API.setAppState({
