    expect(h.app.toolDrag.preview).toBeNull();
    const [note] = liveNotes();
    expect(liveNotes()).toHaveLength(1);
    // centered on the pointer, at the default size
    const center = viewportCoordsToSceneCoords(
      { clientX: 400, clientY: 350 },
      h.state,
    );
    expect(note.x + note.width / 2).toBeCloseTo(center.x);
    expect(note.y + note.height / 2).toBeCloseTo(center.y);
    expect(note.width).toBe(DEFAULT_STICKY_NOTE_SIZE);
    expect(note.baseHeight).toBe(DEFAULT_STICKY_NOTE_SIZE);
    // The drop is recorded while its label is being edited.
    expect(h.state.editingTextElement).not.toBeNull();
    expect(API.getUndoStack()).toHaveLength(1);
    // back on the selection tool (the editor owns the selection meanwhile,
    // as on the click path)
    expect(h.state.activeTool.type).toBe("selection");

    // Abandoning the editor leaves one visible action; undo removes the note.
    Keyboard.keyPress(KEYS.ESCAPE, await getTextEditor());
    expect(API.getUndoStack()).toHaveLength(1);
    Keyboard.undo();
    expect(liveNotes()).toHaveLength(0);
  });

  it("places the preview and dropped note on the grid", () => {
    API.setAppState({ gridModeEnabled: true, gridSize: 20 });
    dragOut(300, 300);
    expect(h.app.toolDrag.preview).toMatchObject({ x: 180, y: 180 });

    fireEvent.pointerUp(GlobalTestState.interactiveCanvas, {
      ...POINTER,
      button: 0,
      clientX: 300,
      clientY: 300,
    });
    expect(liveNotes()[0]).toMatchObject({ x: 180, y: 180 });
  });

  it("leaves nothing behind when Escape cancels the drag", () => {
    dragOut(300, 260);
    expect(h.app.toolDrag.preview).not.toBeNull();

    fireEvent.keyDown(window, { key: KEYS.ESCAPE });
    expect(h.app.toolDrag.preview).toBeNull();

    // a pointer-up arriving after the cancel is inert
    fireEvent.pointerUp(GlobalTestState.interactiveCanvas, {
      ...POINTER,
      button: 0,
      clientX: 300,
      clientY: 260,
    });
    expect(h.elements).toHaveLength(0);
    expect(API.getUndoStack()).toHaveLength(0);
    expect(h.state.editingTextElement).toBeNull();
  });

  it("drops nothing when released outside the canvas", () => {
    dragOut(300, 260);
    fireEvent.pointerUp(document.body, {
      ...POINTER,
      button: 0,
      clientX: 300,
      clientY: 260,
    });
    expect(h.app.toolDrag.preview).toBeNull();
    expect(h.elements).toHaveLength(0);
    expect(API.getUndoStack()).toHaveLength(0);
  });

  it("keeps a plain click selecting the tool", () => {
    const button = stickyButton();
    fireEvent.pointerDown(button, { ...POINTER, button: 0 });
    fireEvent.pointerUp(button, { ...POINTER, button: 0 });
    fireEvent.click(button);
    expect(h.state.activeTool.type).toBe("stickynote");
    expect(h.app.toolDrag.preview).toBeNull();
    expect(h.elements).toHaveLength(0);
  });
});

import { render as renderComponent, fireEvent } from "@testing-library/react";
import { vi } from "vitest";

import { Tooltip, hideTooltip } from "../components/Tooltip";

import { act } from "./test-utils";

const TOOLTIP_DELAY = 500;
const TOOLTIP_WARM_WINDOW = 300;

const getTooltip = () =>
  document.querySelector<HTMLDivElement>(".excalidraw-tooltip");

const isTooltipVisible = () =>
  !!getTooltip()?.classList.contains("excalidraw-tooltip--visible");

const wrapperOf = (container: HTMLElement, label: string) =>
  container.querySelector<HTMLDivElement>(`[data-testid="${label}"]`)!
    .parentElement!;

const Harness = ({ labels, delay }: { labels: string[]; delay?: boolean }) => (
  <>
    {labels.map((label) => (
      <Tooltip key={label} label={label} delay={delay}>
        <button data-testid={label} />
      </Tooltip>
    ))}
  </>
);

describe("Tooltip", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    // the tooltip state is shared by every instance (one tooltip node per
    // page), so start each test cold: nothing visible, warm window elapsed
    hideTooltip();
    vi.advanceTimersByTime(TOOLTIP_WARM_WINDOW + 1);
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("does not flash when the pointer only passes over", () => {
    const { container } = renderComponent(<Harness labels={["a"]} delay />);
    const wrapper = wrapperOf(container, "a");

    fireEvent.pointerEnter(wrapper);
    fireEvent.pointerLeave(wrapper);

    act(() => {
      vi.advanceTimersByTime(TOOLTIP_DELAY);
    });
    expect(isTooltipVisible()).toBe(false);
  });

  it("skips the delay while still warm from a tooltip that just hid", () => {
    const { container } = renderComponent(
      <Harness labels={["a", "b"]} delay />,
    );

    fireEvent.pointerEnter(wrapperOf(container, "a"));
    act(() => {
      vi.advanceTimersByTime(TOOLTIP_DELAY);
    });
    expect(isTooltipVisible()).toBe(true);

    fireEvent.pointerLeave(wrapperOf(container, "a"));
    expect(isTooltipVisible()).toBe(false);

    fireEvent.pointerEnter(wrapperOf(container, "b"));
    expect(isTooltipVisible()).toBe(true);
    expect(getTooltip()!.textContent).toBe("b");
  });

  it("an unrelated Tooltip unmounting doesn't hide a visible tooltip", async () => {
    const { container, rerender } = renderComponent(
      <Harness labels={["a", "b"]} />,
    );

    fireEvent.pointerEnter(wrapperOf(container, "a"));
    expect(isTooltipVisible()).toBe(true);

    // "b" unmounts for its own reasons (e.g. a collaborator leaving)
    rerender(<Harness labels={["a"]} />);
    await Promise.resolve();

    expect(isTooltipVisible()).toBe(true);
    expect(getTooltip()!.textContent).toBe("a");
  });

  it("hides when the Tooltip showing it unmounts", async () => {
    const { container, rerender } = renderComponent(
      <Harness labels={["a", "b"]} />,
    );

    fireEvent.pointerEnter(wrapperOf(container, "a"));
    expect(isTooltipVisible()).toBe(true);

    rerender(<Harness labels={["b"]} />);
    // retracted by the MutationObserver, whose callbacks run as a microtask
    await Promise.resolve();

    expect(isTooltipVisible()).toBe(false);
  });
});

import React from "react";
import { vi } from "vitest";

import { CURSOR_TYPE, KEYS } from "@excalidraw/common";

